import { useState, useEffect, useRef } from 'react'
import { Link } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import { getComments, addComment, deleteComment } from '../lib/supabase'
import { formatDistanceToNow } from 'date-fns'
import { es } from 'date-fns/locale'
import DefaultAvatar from './DefaultAvatar'
import useAutoResizeTextarea from '../hooks/useAutoResizeTextarea'
import './CommentSection.css'

export default function CommentSection({ tierlistId, ownerId }) {
    const { user, profile } = useAuth()
    const [comments, setComments] = useState([])
    const [loading, setLoading] = useState(true)
    const [newComment, setNewComment] = useState('')
    const commentInputRef = useRef(null)
    const [submitting, setSubmitting] = useState(false)
    useAutoResizeTextarea(commentInputRef, newComment)

    useEffect(() => {
        loadComments()
    }, [tierlistId])

    const loadComments = async () => {
        try {
            const data = await getComments(tierlistId)
            setComments(data)
        } catch (error) {
            console.error('Error loading comments:', error)
        } finally {
            setLoading(false)
        }
    }

    const handleSubmit = async (e) => {
        e.preventDefault()
        if (!newComment.trim() || submitting) return

        setSubmitting(true)
        try {
            const addedComment = await addComment(tierlistId, newComment)
            setComments(prev => [...prev, addedComment])
            setNewComment('')
        } catch (error) {
            console.error('Error posting comment:', error)
            alert('Error al comentar')
        } finally {
            setSubmitting(false)
        }
    }

    const handleDelete = async (commentId) => {
        if (!confirm('¿Borrar comentario?')) return
        try {
            await deleteComment(commentId)
            setComments(prev => prev.filter(c => c.id !== commentId))
        } catch (error) {
            console.error('Error deleting comment:', error)
            alert('Error al borrar')
        }
    }

    if (loading) return <div className="loading-spinner"></div>

    return (
        <section className="comments-section">
            <h3 className="section-title">Comentarios ({comments.length})</h3>

            <div className="comments-list">
                {comments.length === 0 ? (
                    <p className="no-comments">Sé el primero en comentar.</p>
                ) : (
                    comments.map(comment => (
                        <div key={comment.id} className="comment">
                            <Link to={`/profile/${comment.profiles.username}`} className="comment-avatar">
                                {comment.profiles.avatar_url ? (
                                    <img src={comment.profiles.avatar_url} alt={comment.profiles.username} />
                                ) : <DefaultAvatar accent={comment.profiles.theme_color} />}
                            </Link>
                            <div className="comment-content">
                                <div className="comment-header">
                                    <Link to={`/profile/${comment.profiles.username}`} className="comment-author">
                                        {comment.profiles.display_name}
                                    </Link>
                                    <span className="comment-date">
                                        {formatDistanceToNow(new Date(comment.created_at), { addSuffix: true, locale: es })}
                                    </span>
                                </div>
                                <p className="comment-text">{comment.content}</p>
                            </div>
                            {(user?.id === comment.user_id || user?.id === ownerId) && (
                                <button
                                    onClick={() => handleDelete(comment.id)}
                                    className="delete-comment-btn"
                                    title="Borrar comentario"
                                >
                                    ✕
                                </button>
                            )}
                        </div>
                    ))
                )}
            </div>

            {user && profile ? (
                <form onSubmit={handleSubmit} className="comment-form">
                    <textarea
                        ref={commentInputRef}
                        value={newComment}
                        onChange={(e) => setNewComment(e.target.value)}
                        placeholder="Escribe un comentario..."
                        maxLength={300}
                        rows={1}
                        required
                    />
                    <button type="submit" className="btn btn-primary" disabled={submitting || !newComment.trim()}>
                        {submitting ? 'Enviando...' : 'Comentar'}
                    </button>
                </form>
            ) : (
                <div className="login-prompt">
                    <Link to={user ? '/onboarding' : '/register'} className="comment-auth-link">
                        Inicia sesión para comentar
                    </Link>
                </div>
            )}
        </section>
    )
}

import React, { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { getCustomItemGroups, saveCustomItemGroup, unsaveCustomItemGroup } from '../lib/customItemGroupService'
import './CustomItemGroupsPicker.css'

const PERSONAL_TABS = [
  { id: 'mine', label: 'Mis grupos' },
  { id: 'saved', label: 'Guardados' },
]

function GroupArtwork({ group }) {
  const items = (group.items || []).slice(0, 4)
  if (!items.length) return <span className="cig-art cig-art-empty">{group.name?.slice(0, 1)?.toUpperCase() || 'G'}</span>
  return <span className="cig-art" aria-hidden="true">{items.map((item, index) => {
    const image = typeof item === 'string' ? item : item?.image_url || item?.cover_url || item?.cover_image || item?.imageUrl || item?.cover?.url
    const name = typeof item === 'string' ? '' : item?.name || item?.title || ''
    return image
      ? <img key={item?.id || `${image}-${index}`} src={image} alt="" loading="lazy" />
      : <i key={item?.id || index}>{name.slice(0, 1)?.toUpperCase() || '·'}</i>
  })}</span>
}

export default function CustomItemGroupsPicker({ userId, onAddGroup }) {
  const [groups, setGroups] = useState({ mine: [], public: [], saved: [] })
  const [activeTab, setActiveTab] = useState('mine')
  const [query, setQuery] = useState('')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [busyGroupId, setBusyGroupId] = useState(null)

  const loadGroups = async () => {
    setLoading(true)
    try {
      setGroups(await getCustomItemGroups(userId))
      setError('')
    } catch (loadError) {
      setError(loadError.message || 'No se pudieron cargar los grupos.')
    } finally { setLoading(false) }
  }

  useEffect(() => { loadGroups() }, [userId])

  const toggleSaved = async group => {
    if (!userId || busyGroupId) return
    setBusyGroupId(group.id)
    try {
      if (group.is_saved || activeTab === 'saved') await unsaveCustomItemGroup(group.id, userId)
      else await saveCustomItemGroup(group.id, userId)
      await loadGroups()
    } catch (saveError) {
      setError(saveError.message || 'No se pudo guardar el grupo.')
    } finally { setBusyGroupId(null) }
  }

  const personalGroups = groups[activeTab] || []
  const publicGroups = useMemo(() => {
    const term = query.trim().toLocaleLowerCase()
    if (!term) return groups.public
    return groups.public.filter(group => [group.name, group.description, ...(group.items || []).map(item => typeof item === 'string' ? item : item?.name || item?.title)]
      .filter(Boolean).some(value => String(value).toLocaleLowerCase().includes(term)))
  }, [groups.public, query])

  const renderGroup = (group, tab) => <article className="cig-group" key={group.id}>
    <GroupArtwork group={group} />
    <div className="cig-group-copy"><strong>{group.name}</strong><small>{group.items?.length || 0} elementos</small></div>
    <button className="cig-add" type="button" onClick={() => onAddGroup(group)}>Añadir</button>
    {tab !== 'mine' && <button className={`cig-save${group.is_saved || tab === 'saved' ? ' is-saved' : ''}`} type="button" title={group.is_saved || tab === 'saved' ? 'Quitar de guardados' : 'Guardar grupo'} aria-label={group.is_saved || tab === 'saved' ? `Quitar ${group.name} de guardados` : `Guardar ${group.name}`} disabled={busyGroupId === group.id} onClick={() => toggleSaved(group)}>{busyGroupId === group.id ? '…' : group.is_saved || tab === 'saved' ? '✓' : '♡'}</button>}
  </article>

  return <section className="cig-picker" aria-label="Grupos de elementos">
    {userId && <>
      <div className="cig-personal-heading"><strong>Tus grupos</strong><Link to="/groups">Gestionar</Link></div>
      <div className="cig-personal-tabs" role="tablist" aria-label="Tus grupos">
        {PERSONAL_TABS.map(tab => <button type="button" role="tab" key={tab.id} aria-selected={activeTab === tab.id} className={activeTab === tab.id ? 'active' : ''} onClick={() => setActiveTab(tab.id)}>{tab.label}</button>)}
      </div>
      {loading ? <p className="cig-state">Cargando grupos…</p> : error ? <p className="cig-state is-error">{error}</p> : personalGroups.length ? <div className="cig-list">{personalGroups.map(group => renderGroup(group, activeTab))}</div> : <p className="cig-state">{activeTab === 'mine' ? 'Aún no tienes grupos.' : 'Todavía no has guardado grupos.'}</p>}
    </>}

    <div className="cig-public-heading"><strong>Grupos públicos</strong></div>
    <label className="cig-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="7.3"/><path d="m16.2 16.2 4.3 4.3"/></svg><input type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar grupos públicos…" aria-label="Buscar grupos públicos" /></label>
    {loading ? <p className="cig-state">Cargando grupos…</p> : error ? <p className="cig-state is-error">{error}</p> : publicGroups.length ? <div className="cig-list cig-public-list">{publicGroups.map(group => renderGroup(group, 'public'))}</div> : <p className="cig-state">{query ? 'No hay grupos que coincidan con la búsqueda.' : 'Todavía no hay grupos públicos.'}</p>}
  </section>
}

import { useState, useEffect } from 'react'
import { useAuth } from '../context/AuthContext'
import {
    getTodayPrompt,
    getUserResponse,
    submitResponse,
    getAggregatedResults,
    formatResultsText,
    getQuestionResponses
} from '../lib/dailyPromptsService'
import './DailyPrompt.css'

export default function DailyPrompt() {
    const { user } = useAuth()
    const [prompt, setPrompt] = useState(null)
    const [userResponse, setUserResponse] = useState(null)
    const [results, setResults] = useState(null)
    const [loading, setLoading] = useState(true)
    const [submitting, setSubmitting] = useState(false)
    const [questionText, setQuestionText] = useState('')
    const [questionResponses, setQuestionResponses] = useState([])

    useEffect(() => {
        loadPrompt()
    }, [user])

    const loadPrompt = async () => {
        if (!user) {
            setLoading(false)
            return
        }

        try {
            // Obtener prompt del día (prioridad a poll)
            const todayPrompt = await getTodayPrompt()

            if (!todayPrompt) {
                setLoading(false)
                return
            }

            setPrompt(todayPrompt)

            // Verificar si el usuario ya respondió
            const response = await getUserResponse(todayPrompt.id, user.id)
            setUserResponse(response)

            // Si ya respondió, cargar resultados
            if (response) {
                if (todayPrompt.type === 'poll') {
                    const aggregated = await getAggregatedResults(todayPrompt.id)
                    setResults(aggregated)
                } else if (todayPrompt.type === 'question') {
                    const responses = await getQuestionResponses(todayPrompt.id)
                    setQuestionResponses(responses)
                }
            }
        } catch (error) {
            console.error('Error loading daily prompt:', error)
        } finally {
            setLoading(false)
        }
    }

    const handlePollVote = async (optionId) => {
        if (!user || submitting || userResponse) return

        setSubmitting(true)
        try {
            const result = await submitResponse(prompt.id, user.id, { choice: optionId })

            if (result.success) {
                setUserResponse(result.data)
                // Cargar resultados
                const aggregated = await getAggregatedResults(prompt.id)
                setResults(aggregated)
            }
        } catch (error) {
            console.error('Error submitting vote:', error)
        } finally {
            setSubmitting(false)
        }
    }

    const handleQuestionSubmit = async (e) => {
        e.preventDefault()
        if (!user || submitting || userResponse || !questionText.trim()) return

        setSubmitting(true)
        try {
            const result = await submitResponse(prompt.id, user.id, { text: questionText.trim() })

            if (result.success) {
                setUserResponse(result.data)
                // Cargar otras respuestas
                const responses = await getQuestionResponses(prompt.id)
                setQuestionResponses(responses)
                setQuestionText('')
            }
        } catch (error) {
            console.error('Error submitting answer:', error)
        } finally {
            setSubmitting(false)
        }
    }

    if (loading) {
        return null // O un skeleton loader
    }

    if (!prompt) {
        return null // No mostrar nada si no hay prompt
    }

    // POLL - ¿Cuál prefieres hoy?
    if (prompt.type === 'poll') {
        const options = prompt.options || []

        return (
            <div className="daily-prompt">
                <div className="daily-prompt-header">
                    <h3>
                        <img
                            src="/icons/videogame.png"
                            alt="Poll"
                            style={{ width: '28px', height: '28px', marginRight: '10px', verticalAlign: 'middle' }}
                        />
                        {prompt.content}
                    </h3>
                    <span className="daily-badge">
                        <img src="/icons/clock.png" alt="Time" style={{ width: '12px', height: '12px', marginRight: '4px', filter: 'brightness(0) invert(1)' }} />
                        Hoy
                    </span>
                </div>

                {!userResponse ? (
                    <div className="poll-options">
                        {options.map(option => (
                            <button
                                key={option.id}
                                className="poll-option"
                                onClick={() => handlePollVote(option.id)}
                                disabled={submitting}
                            >
                                {option.image && (
                                    <div className="poll-option-image">
                                        <img src={option.image} alt={option.label} />
                                    </div>
                                )}
                                <div className="poll-option-label">
                                    {option.label}
                                </div>
                            </button>
                        ))}
                    </div>
                ) : (
                    <div className="poll-results">
                        <div className="results-header">
                            <span className="check-icon">✓</span>
                            <span>Ya votaste</span>
                        </div>

                        {results && (
                            <>
                                <div className="results-text">
                                    {formatResultsText(results, options)}
                                </div>

                                <div className="results-bars">
                                    {options.map(option => {
                                        const optionData = results.distribution[option.id]
                                        const percentage = optionData?.percentage || 0
                                        const isUserChoice = userResponse.answer.choice === option.id

                                        return (
                                            <div key={option.id} className={`result-bar ${isUserChoice ? 'user-choice' : ''}`}>
                                                <div className="result-label">
                                                    {option.label}
                                                    {isUserChoice && <span className="your-vote"> (tu voto)</span>}
                                                </div>
                                                <div className="result-bar-track">
                                                    <div
                                                        className="result-bar-fill"
                                                        style={{ width: `${percentage}%` }}
                                                    />
                                                </div>
                                                <div className="result-percentage">{percentage}%</div>
                                            </div>
                                        )
                                    })}
                                </div>
                            </>
                        )}
                    </div>
                )}
            </div>
        )
    }

    // QUESTION - Pregunta diaria
    if (prompt.type === 'question') {
        return (
            <div className="daily-prompt daily-question">
                <div className="daily-prompt-header">
                    <h3>
                        <img
                            src="/icons/dialog.png"
                            alt="Question"
                            style={{ width: '28px', height: '28px', marginRight: '10px', verticalAlign: 'middle' }}
                        />
                        {prompt.content}
                    </h3>
                    <span className="daily-badge">
                        <img src="/icons/clock.png" alt="Time" style={{ width: '12px', height: '12px', marginRight: '4px', filter: 'brightness(0) invert(1)' }} />
                        Hoy
                    </span>
                </div>

                {!userResponse ? (
                    <form onSubmit={handleQuestionSubmit} className="question-form">
                        <textarea
                            value={questionText}
                            onChange={(e) => setQuestionText(e.target.value)}
                            placeholder="Escribe tu respuesta..."
                            maxLength={200}
                            disabled={submitting}
                            rows={3}
                        />
                        <button
                            type="submit"
                            className="btn btn-primary"
                            disabled={submitting || !questionText.trim()}
                        >
                            {submitting ? 'Enviando...' : 'Responder'}
                        </button>
                    </form>
                ) : (
                    <div className="question-results">
                        <div className="results-header">
                            <span className="check-icon">✓</span>
                            <span>Respondiste: "{userResponse.answer.text}"</span>
                        </div>

                        {questionResponses.length > 0 && (
                            <div className="other-responses">
                                <h4>Otras respuestas</h4>
                                <div className="responses-list">
                                    {questionResponses.slice(0, 10).map((resp, idx) => (
                                        <div key={idx} className="response-item">
                                            <p>"{resp.text}"</p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>
        )
    }

    return null
}

export function getDefaultAvatarDataUrl(accent = '#14b8a6') {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="none"><circle cx="128" cy="128" r="128" fill="#111719"/><circle cx="128" cy="92" r="42" stroke="${accent}" stroke-width="12"/><path d="M48 218c8-43 39-70 80-70s72 27 80 70" stroke="${accent}" stroke-width="12" stroke-linecap="round"/></svg>`
  return `data:image/svg+xml,${encodeURIComponent(svg)}`
}

export default function DefaultAvatar({ accent = '#14b8a6', className = '', title, style }) {
  const src = getDefaultAvatarDataUrl(accent)
  return <img src={src} className={className} style={style} alt={title || ''} aria-hidden={title ? undefined : true} />
}

import { useState, useEffect } from 'react'
import { createPortal } from 'react-dom'
import { Link, useNavigate } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../context/AuthContext'
import LoadingSpinner from './LoadingSpinner'
import { BADGES_MAP } from '../lib/badges'
import DefaultAvatar from './DefaultAvatar'
import './FollowsModal.css'

const IconClose = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" />
    </svg>
)

export default function FollowsModal({ isOpen, onClose, type, userId, themeColor }) {
    const { user: currentUser, profile } = useAuth()
    const navigate = useNavigate()
    const [currentTab, setCurrentTab] = useState(type)
    const [users, setUsers] = useState([])
    const [loading, setLoading] = useState(true)
    const [searchQuery, setSearchQuery] = useState('')
    const [myFollowingIds, setMyFollowingIds] = useState(new Set())

    useEffect(() => {
        if (isOpen) {
            setCurrentTab(type)
            setSearchQuery('')
        }
    }, [isOpen, type])

    useEffect(() => {
        if (isOpen && userId) {
            loadUsers()
            loadMyFollows()
        }
    }, [isOpen, userId, currentTab])

    const loadMyFollows = async () => {
        if (!currentUser) return
        const { data } = await supabase.from('follows').select('following_id').eq('follower_id', currentUser.id)
        if (data) {
            setMyFollowingIds(new Set(data.map(d => d.following_id)))
        }
    }

    const loadUsers = async () => {
        setLoading(true)
        try {
            let ids = []
            if (currentTab === 'followers') {
                const { data } = await supabase.from('follows').select('follower_id').eq('following_id', userId)
                ids = data?.map(d => d.follower_id) || []
            } else {
                const { data } = await supabase.from('follows').select('following_id').eq('follower_id', userId)
                ids = data?.map(d => d.following_id) || []
            }

            if (ids.length === 0) {
                setUsers([])
                setLoading(false)
                return
            }

            const { data: profiles } = await supabase
                .from('profiles')
                .select('id, username, display_name, avatar_url, bio, featured_badge, theme_color')
                .in('id', ids)

            setUsers(profiles || [])
        } catch (error) {
            console.error('Error loading follows:', error)
        } finally {
            setLoading(false)
        }
    }

    const handleToggleFollow = async (e, targetUserId) => {
        e.preventDefault()
        e.stopPropagation()
        if (!currentUser) {
            navigate('/register')
            return
        }
        if (!profile) {
            navigate('/onboarding')
            return
        }

        const isFollowing = myFollowingIds.has(targetUserId)
        const newSet = new Set(myFollowingIds)

        if (isFollowing) {
            newSet.delete(targetUserId)
            setMyFollowingIds(newSet)
            await supabase.from('follows').delete().eq('follower_id', currentUser.id).eq('following_id', targetUserId)
        } else {
            newSet.add(targetUserId)
            setMyFollowingIds(newSet)
            await supabase.from('follows').insert({ follower_id: currentUser.id, following_id: targetUserId })
        }
    }

    if (!isOpen) return null

    const filteredUsers = users.filter(u => 
        u.display_name?.toLowerCase().includes(searchQuery.toLowerCase()) || 
        u.username?.toLowerCase().includes(searchQuery.toLowerCase())
    )

    return createPortal((
        <div
            className="follows-modal-overlay"
            onClick={onClose}
            style={themeColor ? { '--brand-primary': themeColor, '--brand-dark': themeColor } : undefined}
        >
            <div className="follows-modal-card" onClick={e => e.stopPropagation()}>
                <div className="follows-modal-header">
                    <div className="follows-tabs">
                        <button 
                            className={`follows-tab ${currentTab === 'followers' ? 'active' : ''}`}
                            onClick={() => setCurrentTab('followers')}
                        >
                            Seguidores
                        </button>
                        <button 
                            className={`follows-tab ${currentTab === 'following' ? 'active' : ''}`}
                            onClick={() => setCurrentTab('following')}
                        >
                            Siguiendo
                        </button>
                    </div>
                    <button className="follows-close-btn" onClick={onClose}>
                        <IconClose />
                    </button>
                </div>

                <div className="follows-search-wrap">
                    <input
                        type="text"
                        className="follows-search-input"
                        placeholder="Buscar personas..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        autoFocus
                    />
                </div>

                <div className="follows-list-body">
                    {loading ? (
                        <div className="follows-loading">
                            <LoadingSpinner />
                            <p>Cargando usuarios...</p>
                        </div>
                    ) : filteredUsers.length > 0 ? (
                        filteredUsers.map(u => {
                            const isMe = currentUser?.id === u.id
                            const isFollowing = myFollowingIds.has(u.id)

                            return (
                                <Link 
                                    key={u.id} 
                                    to={`/profile/${u.username}`} 
                                    className="follows-user-row"
                                    onClick={onClose}
                                >
                                    <div className="follows-user-info">
                                        {u.avatar_url ? (
                                            <img src={u.avatar_url} alt="" className="follows-user-avatar" style={{ borderColor: u.theme_color || 'var(--brand-primary)' }} />
                                        ) : (
                                            <DefaultAvatar className="follows-user-placeholder" accent={u.theme_color} style={{ borderColor: u.theme_color || 'var(--brand-primary)' }} />
                                        )}
                                        <div className="follows-user-text">
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                                <span className="follows-user-name">{u.display_name}</span>
                                                {u.featured_badge && BADGES_MAP[u.featured_badge] && (
                                                    <div style={{ color: BADGES_MAP[u.featured_badge].color, display: 'flex', alignItems: 'center' }} title={BADGES_MAP[u.featured_badge].title}>
                                                        {BADGES_MAP[u.featured_badge].icon}
                                                    </div>
                                                )}
                                            </div>
                                            <span className="follows-user-username">@{u.username}</span>
                                        </div>
                                    </div>

                                    {!isMe && (
                                        <button 
                                            className={isFollowing ? 'follows-btn-unfollow' : 'follows-btn-follow'}
                                            onClick={(e) => handleToggleFollow(e, u.id)}
                                        >
                                            {isFollowing ? 'Siguiendo' : 'Seguir'}
                                        </button>
                                    )}
                                </Link>
                            )
                        })
                    ) : (
                        <div className="follows-empty">
                            {searchQuery 
                                ? 'No se encontraron usuarios que coincidan con tu búsqueda.' 
                                : currentTab === 'followers' 
                                    ? 'Aún no tiene seguidores.' 
                                    : 'Aún no sigue a nadie.'}
                        </div>
                    )}
                </div>
            </div>
        </div>
    ), document.body)
}

import { useEffect, useMemo, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { Link } from 'react-router-dom'
import DefaultAvatar from './DefaultAvatar'
import { getAccentTextColor } from '../lib/colorContrast'
import { deleteUserStatus, getActiveStatuses, saveUserStatus } from '../lib/statusService'
import './HomeStatuses.css'

function deezerJsonp(url) {
  return new Promise((resolve, reject) => {
    const callback = `homeStatusDz_${Date.now()}_${Math.random().toString(36).slice(2)}`
    const script = document.createElement('script')
    const finish = value => { script.remove(); delete window[callback]; resolve(value) }
    const timeout = window.setTimeout(() => finish(null), 5000)
    window[callback] = value => { window.clearTimeout(timeout); finish(value) }
    script.onerror = () => {
      window.clearTimeout(timeout)
      delete window[callback]
      script.remove()
      reject(new Error('No se pudo conectar con Deezer.'))
    }
    script.src = `${url}${url.includes('?') ? '&' : '?'}output=jsonp&callback=${callback}`
    document.body.appendChild(script)
  })
}

async function findSongs(query) {
  const result = await deezerJsonp(`https://api.deezer.com/search?q=${encodeURIComponent(query)}&limit=6`)
  return (result?.data || []).map(track => ({
    trackId: track.id,
    name: track.title,
    artist: track.artist?.name || 'Artista desconocido',
    cover: track.album?.cover_medium,
    previewUrl: track.preview,
    provider: 'deezer',
  })).filter(track => track.previewUrl)
}

function Avatar({ person }) {
  const name = person.display_name || person.username || 'Usuario'
  return <span className="home-status-avatar" style={{ '--status-accent': person.theme_color || 'var(--brand-primary)' }}>
    {person.avatar_url ? <img src={person.avatar_url} alt="" loading="lazy" /> : <DefaultAvatar accent={person.theme_color} />}
  </span>
}

function StatusSong({ song, playing, onToggle }) {
  return <div className="home-status-song-detail">
    {song.cover && <img src={song.cover} alt="" />}
    <span><strong>{song.name}</strong><small>{song.artist}</small></span>
    <button type="button" className="home-status-play" onClick={onToggle} aria-label={playing ? 'Pausar canción' : 'Reproducir canción'}>
      {playing ? <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 5h4v14H7zM15 5h4v14h-4z" /></svg> : <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7z" /></svg>}
    </button>
  </div>
}

export default function HomeStatuses({ user, profile, friends = [] }) {
  const [statuses, setStatuses] = useState({})
  const [textEditing, setTextEditing] = useState(false)
  const [text, setText] = useState('')
  const [songPickerOpen, setSongPickerOpen] = useState(false)
  const [songQuery, setSongQuery] = useState('')
  const [songResults, setSongResults] = useState([])
  const [searchingSongs, setSearchingSongs] = useState(false)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [viewed, setViewed] = useState(null)
  const [playing, setPlaying] = useState(false)
  const audioRef = useRef(null)
  const searchSequence = useRef(0)
  const textRef = useRef(null)
  const people = useMemo(() => [
    ...(user ? [{ ...profile, id: user.id, username: profile?.username, display_name: profile?.display_name || 'Tú', avatar_url: profile?.avatar_url, theme_color: profile?.theme_color }] : []),
    ...friends.filter(friend => friend.id !== user?.id).slice(0, user ? 4 : 5),
  ], [user, profile, friends])

  useEffect(() => {
    let active = true
    let timer
    const loadStatuses = async () => {
      try {
        const items = await getActiveStatuses(people.map(person => person.id))
        if (!active) return
        setStatuses(Object.fromEntries(items.map(item => [item.user_id, item])))
      } catch (err) { console.error('No se pudieron cargar los estados:', err) }
      if (active) timer = window.setTimeout(loadStatuses, 60_000)
    }
    loadStatuses()
    return () => { active = false; window.clearTimeout(timer) }
  }, [people])

  useEffect(() => {
    if (!songPickerOpen || songQuery.trim().length < 2) {
      setSongResults([])
      return undefined
    }
    const sequence = ++searchSequence.current
    const timer = window.setTimeout(async () => {
      setSearchingSongs(true)
      try {
        const results = await findSongs(songQuery.trim())
        if (sequence === searchSequence.current) setSongResults(results)
      } catch (err) {
        if (sequence === searchSequence.current) setError(err.message)
      } finally {
        if (sequence === searchSequence.current) setSearchingSongs(false)
      }
    }, 350)
    return () => window.clearTimeout(timer)
  }, [songPickerOpen, songQuery])

  useEffect(() => {
    if (textEditing && textRef.current) {
      const textarea = textRef.current
      textarea.focus()
      textarea.style.height = 'auto'
      textarea.style.height = `${textarea.scrollHeight}px`
    }
  }, [textEditing])

  useEffect(() => {
    if (!viewed) return undefined
    const onKeyDown = event => { if (event.key === 'Escape') setViewed(null) }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [viewed])

  useEffect(() => () => {
    if (audioRef.current) { audioRef.current.pause(); audioRef.current = null }
  }, [])

  useEffect(() => {
    if (viewed || !audioRef.current) return
    audioRef.current.pause()
    audioRef.current = null
    setPlaying(false)
  }, [viewed])

  const stopSong = () => {
    if (!audioRef.current) return
    audioRef.current.pause()
    audioRef.current.currentTime = 0
    audioRef.current = null
    setPlaying(false)
  }

  const toggleSong = async song => {
    if (audioRef.current) {
      if (audioRef.current.dataset.trackId === String(song.trackId) && !audioRef.current.paused) {
        audioRef.current.pause()
        setPlaying(false)
        return
      }
      stopSong()
    }
    let preview = song.previewUrl
    if (song.trackId) {
      try {
        const result = await deezerJsonp(`https://api.deezer.com/track/${encodeURIComponent(song.trackId)}`)
        preview = result?.preview || preview
      } catch { /* Use the preview stored with the status. */ }
    }
    if (!preview) return
    const audio = new Audio(preview)
    audio.dataset.trackId = String(song.trackId)
    audio.volume = 0.5
    audio.onplay = () => setPlaying(true)
    audio.onpause = () => setPlaying(false)
    audio.onended = () => { setPlaying(false); audio.currentTime = 0; audio.volume = 0.5 }
    audio.ontimeupdate = () => {
      if (!audio.duration) return
      const remaining = audio.duration - audio.currentTime
      if (remaining < 3 && remaining > 0) audio.volume = Math.max(0, remaining / 3 * 0.5)
    }
    audioRef.current = audio
    try { await audio.play() } catch (err) { console.warn('No se pudo reproducir la canción del estado:', err) }
  }

  const beginTextEdit = () => {
    setText(statuses[user?.id]?.status_type === 'text' ? statuses[user.id].content : '')
    setError('')
    setSongPickerOpen(false)
    setTextEditing(true)
  }

  const saveStatus = async status => {
    if (!user?.id) return false
    setError('')
    setSaving(true)
    try {
      const saved = await saveUserStatus(user.id, status)
      setStatuses(current => ({ ...current, [user.id]: saved }))
      setTextEditing(false)
      setSongPickerOpen(false)
      setSongQuery('')
      return true
    } catch (err) {
      console.error('No se pudo guardar el estado:', err)
      setError('No se pudo guardar. Inténtalo de nuevo.')
      return false
    } finally { setSaving(false) }
  }

  const submitText = event => {
    event?.preventDefault?.()
    if (!text.trim()) { setError('Escribe algo para compartir.'); return }
    saveStatus({ type: 'text', content: text })
  }

  const resizeText = event => {
    event.currentTarget.style.height = 'auto'
    event.currentTarget.style.height = `${event.currentTarget.scrollHeight}px`
    setText(event.currentTarget.value)
    setError('')
  }

  const selectSong = song => saveStatus({ type: 'song', song })

  const removeOwnStatus = async () => {
    try {
      await deleteUserStatus(user.id)
      setStatuses(current => { const next = { ...current }; delete next[user.id]; return next })
      setViewed(null)
    } catch (err) { console.error('No se pudo borrar el estado:', err) }
  }

  const detailModal = viewed && <div className="home-status-overlay" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget) setViewed(null) }}>
    <section className="home-status-dialog" role="dialog" aria-modal="true" aria-label={`Estado de ${viewed.person.display_name || viewed.person.username || 'Usuario'}`}>
      <button className="home-status-close" type="button" onClick={() => setViewed(null)} aria-label="Cerrar">×</button>
      <header className="home-status-dialog-author"><Avatar person={viewed.person}/><span><strong>{viewed.person.display_name || viewed.person.username || 'Usuario'}</strong><small>Estado · vence a las {new Date(viewed.status.expires_at).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}</small></span></header>
      {viewed.status.status_type === 'song'
        ? <StatusSong song={viewed.status.song} playing={playing} onToggle={() => toggleSong(viewed.status.song)} />
        : <p className="home-status-dialog-text">{viewed.status.content}</p>}
      <footer className="home-status-dialog-actions">
        {viewed.isOwn && <button type="button" className="home-status-delete" onClick={removeOwnStatus}>Eliminar estado</button>}
        {!viewed.isOwn && <button type="button" className="home-status-reply" disabled title="Los mensajes estarán disponibles próximamente">Responder · próximamente</button>}
      </footer>
    </section>
  </div>

  const selfPerson = people[0]
  const ownStatus = selfPerson ? statuses[selfPerson.id] : null
  const expandedComposer = textEditing || songPickerOpen
  const ownAccent = selfPerson?.theme_color || '#14b8a6'
  const ownBubbleStyle = { '--status-accent': ownAccent, '--status-text': getAccentTextColor(ownAccent) }

  return <section className="home-summary-friends">
    <span className="home-summary-label">Amigos conectados</span>
    {expandedComposer && selfPerson
      ? <div className="home-status-expanded" style={ownBubbleStyle}>
          <button className="home-status-expanded-close" type="button" onClick={() => { setTextEditing(false); setSongPickerOpen(false); setError('') }} aria-label="Cerrar editor">×</button>
          {textEditing
            ? <form className="home-status-bubble home-status-expanded-bubble home-status-inline-editor" onSubmit={submitText}>
                <textarea ref={textRef} value={text} maxLength={80} onChange={resizeText} onKeyDown={event => { if (event.key === 'Enter' && !event.shiftKey) submitText(event) }} placeholder="¿Qué tienes en mente?" aria-label="Escribe tu estado" />
                <span className="home-status-inline-actions"><small>{text.length}/80</small><button type="submit" disabled={saving || !text.trim()} aria-label="Publicar estado" title="Publicar">✓</button></span>
              </form>
            : <div className="home-status-bubble home-status-expanded-bubble is-expanded-song-prompt"><span>{ownStatus?.status_type === 'song' ? `♫ ${ownStatus.song?.name || 'Canción'}` : ownStatus?.content || 'Elige una canción para tu estado'}</span></div>}
          <div className="home-status-expanded-avatar"><Avatar person={selfPerson}/><span className="home-status-connected-dot" aria-hidden="true" /></div>
          <strong className="home-status-expanded-name">{profile?.display_name || profile?.username || 'Tú'}</strong>
          <button type="button" className="home-status-music-button is-expanded" onClick={() => { setSongPickerOpen(true); setTextEditing(false); setError('') }} aria-label="Añadir una canción al estado" title="Añadir canción">
            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/></svg>
          </button>
          {error && <p className="home-status-inline-error" role="alert">{error}</p>}
        </div>
      : <div className="home-status-list">
      {people.map((person, index) => {
        const isOwn = index === 0 && person.id === user?.id
        const status = statuses[person.id]
        const name = isOwn ? 'Tú' : person.display_name || person.username || 'Usuario'
        const label = status?.status_type === 'song' ? `♫ ${status.song?.name || 'Canción'}` : status?.content
        const accent = person.theme_color || '#14b8a6'
        const bubbleStyle = { '--status-accent': accent, '--status-text': getAccentTextColor(accent) }
        const openFriendStatus = () => {
          if (!status) return
          setViewed({ person, status, isOwn })
          if (status.status_type === 'song' && status.song) toggleSong(status.song)
        }
        return <div key={person.id} className={`home-status-person${isOwn ? ' is-self' : ''}`}>
          {isOwn
              ? <button type="button" className={`home-status-bubble${status?.status_type === 'song' ? ' is-song' : ''}${status ? '' : ' is-placeholder'}`} style={bubbleStyle} onClick={status?.status_type === 'song' ? openFriendStatus : beginTextEdit}>
                  <span>{label || 'Escribe un estado'}</span>
                </button>
              : status && <button type="button" className={`home-status-bubble${status.status_type === 'song' ? ' is-song' : ''}`} style={bubbleStyle} onClick={openFriendStatus}><span>{label}</span></button>}
          <div className="home-status-avatar-wrap">
            {isOwn
              ? <button type="button" className="home-status-avatar-button" onClick={beginTextEdit} aria-label="Escribe tu estado"><Avatar person={person}/></button>
              : <Link className="home-status-avatar-button" to={person.username ? `/profile/${person.username}` : '/profile'} aria-label={`Ver el perfil de ${name}`}><Avatar person={person}/></Link>}
            <span className="home-status-connected-dot" aria-hidden="true" />
          </div>
          <span className="home-status-name">{name}</span>
        </div>
      })}
    </div>}
    {songPickerOpen && <div className={`home-status-song-popover${expandedComposer ? ' is-expanded' : ''}`}>
      <header><strong>Añadir canción</strong><button type="button" onClick={() => { setSongPickerOpen(false); setError('') }} aria-label="Cerrar búsqueda">×</button></header>
      <input autoFocus value={songQuery} onChange={event => { setSongQuery(event.target.value); setError('') }} placeholder="Busca una canción…" aria-label="Buscar canción" />
      {searchingSongs && <p className="home-status-search-hint">Buscando…</p>}
      {songResults.length > 0 && <div className="home-status-song-results">{songResults.map(song => <button type="button" key={song.trackId} onClick={() => selectSong(song)} disabled={saving}>{song.cover && <img src={song.cover} alt="" />}<span><strong>{song.name}</strong><small>{song.artist}</small></span><b>{saving ? '…' : 'Elegir'}</b></button>)}</div>}
      {!searchingSongs && songQuery.trim().length >= 2 && !songResults.length && <p className="home-status-search-hint">No se encontraron canciones con vista previa.</p>}
      {error && <p className="home-status-error" role="alert">{error}</p>}
    </div>}
    {typeof document !== 'undefined' && detailModal && createPortal(detailModal, document.body)}
  </section>
}

import { createPostgresChannel } from '../lib/postgresChannel'
import { useCallback, useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { Link, Outlet, useLocation, useNavigate } from 'react-router-dom'
import { SiKofi } from 'react-icons/si'
import { useAuth } from '../context/AuthContext'
import { supabase } from '../lib/supabase'
import { getAccentTextColor, getVisibleAccentColor } from '../lib/colorContrast'
import { hasCustomAvatar } from '../lib/avatar'
import { ListsEntryModal } from '../pages/lists/ListsEntry'
import DefaultAvatar from './DefaultAvatar'
import InstallApp from './InstallApp'
import { isPwaTransitionRoute, isStandalonePwa, navigatePwaRoute } from '../lib/pwaRouteTransition'
import './Layout.css'

const Icon = ({ name }) => {
  const common = { width: 23, height: 23, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 1.9, strokeLinecap: 'round', strokeLinejoin: 'round', 'aria-hidden': true }
  const paths = {
    home: <><path d="m3 10 9-7 9 7"/><path d="M5 9v12h5v-7h4v7h5V9"/></>,
    reviews: <path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3z"/>,
    spaces: <><circle cx="9" cy="8" r="3.5"/><path d="M2.5 20v-1.5a6.5 6.5 0 0 1 13 0V20z"/><path d="M16 5a3.5 3.5 0 0 1 0 6.8M18 14a5.5 5.5 0 0 1 3.5 5.1V20H19"/></>,
    search: <><circle cx="10.8" cy="10.8" r="7.3"/><path d="m16.2 16.2 4.3 4.3"/></>,
    share: <><circle cx="12" cy="12" r="9"/><path d="M12 7v10M7 12h10"/></>,
    activity: <><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></>,
    more: <><path d="M4 7h16M4 12h16M4 17h16"/></>,
    close: <><path d="m18 6-12 12M6 6l12 12"/></>,
    logout: <><path d="M10 17l5-5-5-5M15 12H3"/><path d="M12 3h6a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-6"/></>,
    arrow: <><path d="m9 18 6-6-6-6"/></>,
    user: <><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></>,
  }
  return <svg {...common}>{paths[name]}</svg>
}

function MoreMenu({ profile, image, username, accentColor, onSignOut, accounts = [], userId, onSwitchAccount, onAddAccount, switchingAccountId }) {
  const [accountsOpen, setAccountsOpen] = useState(false)
  const displayName = profile?.display_name || username || 'Mi cuenta'
  const accountCount = new Set([...accounts.map(account => account.id), userId].filter(Boolean)).size
  const canAddAccount = accountCount < 3
  if (accountsOpen) return <>
    <div className="more-submenu-heading">
      <button className="more-submenu-back" type="button" aria-label="Volver al menú" onClick={() => setAccountsOpen(false)}>
        <Icon name="arrow" />
      </button>
      <strong>Cuentas</strong>
    </div>
    <div className="more-submenu-divider" />
    <button className={`more-current-account ${switchingAccountId === userId ? 'is-switching' : ''}`} type="button" aria-current="true" aria-busy={switchingAccountId === userId} aria-label={`${displayName}, cuenta actual`}>
      {image ? <img src={image} alt="" /> : <DefaultAvatar className="more-account-avatar-placeholder" accent={profile?.theme_color} />}
      <span className="more-account-copy"><strong>{displayName}</strong><small>@{username || 'usuario'}</small></span>
      {switchingAccountId === userId
        ? <span className="more-account-loading-spinner" role="status" aria-label="Cambiando de cuenta" />
        : <svg className="more-account-check" style={{ color: accentColor }} viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6" /></svg>}
    </button>
    {accounts.filter(account => account.id !== userId).map(account => {
      const savedProfile = account.profile
      const savedName = savedProfile?.display_name || savedProfile?.username || account.email || 'Cuenta'
      const savedUsername = savedProfile?.username
      const savedImage = (hasCustomAvatar(savedProfile?.avatar_url) && savedProfile.avatar_url) || (hasCustomAvatar(savedProfile?.profile_picture) && savedProfile.profile_picture) || null
      const isSwitching = account.id === switchingAccountId
      return <button key={account.id} className={`more-current-account ${isSwitching ? 'is-switching' : ''}`} type="button" onClick={() => onSwitchAccount(account.id)} aria-label={`Cambiar a ${savedName}`} aria-busy={isSwitching}>
        {savedImage ? <img src={savedImage} alt="" /> : <DefaultAvatar className="more-account-avatar-placeholder" accent={savedProfile?.theme_color} />}
        <span className="more-account-copy"><strong>{savedName}</strong><small>{savedUsername ? `@${savedUsername}` : account.email}</small></span>
        {isSwitching && <span className="more-account-loading-spinner" role="status" aria-label="Cambiando de cuenta" />}
      </button>
    })}
    <nav className="more-menu-links more-account-actions" aria-label="Acciones de cuenta">
      <button className="more-menu-link" type="button" onClick={onAddAccount} disabled={!canAddAccount}>{canAddAccount ? 'Añadir cuenta' : 'Límite de cuentas alcanzado'}</button>
      {!canAddAccount && <small className="more-account-limit">Máximo 3 cuentas por navegador.</small>}
      <button className="more-menu-link more-account-signout" type="button" onClick={onSignOut}>Cerrar sesión @{username || 'usuario'}</button>
    </nav>
  </>
  return <>
    <button className="more-account" type="button" aria-haspopup="true" aria-expanded="false" onClick={() => setAccountsOpen(true)}>
      {image ? <img src={image} alt="" /> : <DefaultAvatar className="more-account-avatar-placeholder" accent={profile?.theme_color} />}
      <span className="more-account-copy"><strong>{displayName}</strong><small>@{username || 'usuario'}</small></span>
      <svg className="more-account-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m8 10 4-4 4 4M8 14l4 4 4-4"/></svg>
    </button>
    <nav className="more-menu-links" aria-label="Más opciones">
      <Link className="more-menu-link" to="/settings">Ajustes</Link>
      <button className="more-menu-link" type="button" aria-disabled="true">Guardados</button>
      <Link className="more-menu-link" to="/groups">Grupos</Link>
      <Link className="more-menu-link" to="/invite">Invitar</Link>
      <a className="more-menu-link more-menu-support" href="https://ko-fi.com/mixel34" target="_blank" rel="noopener noreferrer" aria-label="Apoyar en Ko-fi (se abre en una pestaña nueva)">
        <SiKofi className="more-menu-kofi-icon" aria-hidden="true" />
        <span>Apoyar</span>
        <svg className="more-menu-external-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M14 4h6v6M20 4l-9 9"/><path d="M18 13v6a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h6"/></svg>
      </a>
    </nav>
    <div className="more-menu-divider" />
    <nav className="more-menu-legal-links" aria-label="Información legal">
      <Link to="/privacy">Privacidad</Link>
      <Link to="/terms">Términos</Link>
      <Link to="/community-guidelines">Normas de la comunidad</Link>
      <Link to="/credits">Créditos</Link>
    </nav>
  </>
}

export default function Layout() {
  const { user, profile, signOut, accounts, rememberCurrentAccount, switchAccount } = useAuth()
  const location = useLocation()
  const navigate = useNavigate()
  const [moreOpen, setMoreOpen] = useState(false)
  const [switchingAccountId, setSwitchingAccountId] = useState(null)
  const [unreadCount, setUnreadCount] = useState(0)
  const [listsOpen, setListsOpen] = useState(false)
  const menuRef = useRef(null)
  const moreButtonRef = useRef(null)
  const moreMenuContentRef = useRef(null)
  const mobileNavRef = useRef(null)
  const mobileTopbarRef = useRef(null)
  const [moreMenuPosition, setMoreMenuPosition] = useState({ left: 256, bottom: 14 })
  const isDesktop = typeof window !== 'undefined' && window.innerWidth > 960

  useEffect(() => {
    const transitionDetailNavigation = event => {
      if (!isStandalonePwa() || typeof document.startViewTransition !== 'function' || event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return
      const anchor = event.target.closest?.('a[href]')
      if (!anchor || anchor.target || anchor.hasAttribute('download')) return
      try {
        const destination = new URL(anchor.href, window.location.href)
        if (destination.origin !== window.location.origin || !isPwaTransitionRoute(destination.pathname)) return
        event.preventDefault()
        navigatePwaRoute(navigate, `${destination.pathname}${destination.search}${destination.hash}`)
      } catch {}
    }

    document.addEventListener('click', transitionDetailNavigation, true)
    return () => document.removeEventListener('click', transitionDetailNavigation, true)
  }, [navigate])

  useEffect(() => {
    const standaloneQuery = window.matchMedia('(display-mode: standalone), (display-mode: fullscreen)')
    const landscapeQuery = window.matchMedia('(orientation: landscape)')
    const updateOrientationLock = () => {
      const isInstalledPwa = standaloneQuery.matches || navigator.standalone === true
      document.body.classList.toggle('pwa-landscape-lock', isInstalledPwa && landscapeQuery.matches)
      if (isInstalledPwa) screen.orientation?.lock?.('portrait').catch(() => {})
    }
    updateOrientationLock()
    standaloneQuery.addEventListener?.('change', updateOrientationLock)
    landscapeQuery.addEventListener?.('change', updateOrientationLock)
    return () => {
      standaloneQuery.removeEventListener?.('change', updateOrientationLock)
      landscapeQuery.removeEventListener?.('change', updateOrientationLock)
      document.body.classList.remove('pwa-landscape-lock')
    }
  }, [])

  const username = profile?.username
  const profilePath = username ? `/profile/${username}` : (user ? '/onboarding' : '/profile')
  const spacesPath = user && !profile ? '/onboarding' : '/spaces'
  const image = (hasCustomAvatar(profile?.avatar_url) && profile.avatar_url) || (hasCustomAvatar(profile?.profile_picture) && profile.profile_picture) || null
  const handleSignOut = async () => { setMoreOpen(false); await signOut(); navigate('/login') }
  const addAccount = async () => {
    await rememberCurrentAccount()
    setMoreOpen(false)
    navigate('/login?addAccount=1')
  }
  const changeAccount = async accountId => {
    setSwitchingAccountId(accountId)
    try {
      const accountProfile = await switchAccount(accountId)
      const username = accountProfile?.username
      sessionStorage.setItem('geeksphere.account-switched-toast', username ? `@${username}` : '')
      window.location.assign(username ? `/profile/${encodeURIComponent(username)}` : '/onboarding')
    } catch (error) {
      console.error('No se pudo cambiar de cuenta:', error)
      setSwitchingAccountId(null)
    }
  }
  const moreMenu = <MoreMenu profile={profile} image={image} username={username} userId={user?.id} accounts={accounts} onSwitchAccount={changeAccount} onAddAccount={addAccount} switchingAccountId={switchingAccountId} accentColor={getVisibleAccentColor(profile?.theme_color || 'var(--brand-primary)')} onSignOut={handleSignOut} />
  const toggleMoreMenu = () => {
    if (moreOpen) { setMoreOpen(false); return }
    if (isDesktop && moreButtonRef.current) {
      const rect = moreButtonRef.current.getBoundingClientRect()
      setMoreMenuPosition({ left: rect.left, bottom: window.innerHeight - rect.top + 10 })
    }
    setMoreOpen(true)
  }

  const loadUnread = useCallback(async () => {
    if (!user?.id) return
    const [allUnread, followUnread, followRows] = await Promise.all([
      supabase.from('notifications').select('id', { count: 'exact', head: true }).eq('user_id', user.id).eq('is_read', false),
      supabase.from('notifications').select('id', { count: 'exact', head: true }).eq('user_id', user.id).eq('is_read', false).eq('type', 'follow'),
      supabase.from('notifications').select('actor_id').eq('user_id', user.id).eq('is_read', false).eq('type', 'follow').limit(1000),
    ])
    const uniqueFollowActors = new Set((followRows.data || []).map(row => row.actor_id).filter(Boolean)).size
    setUnreadCount(Math.max(0, (allUnread.count || 0) - (followUnread.count || 0) + uniqueFollowActors))
  }, [user?.id])

  useEffect(() => {
    setMoreOpen(false)
  }, [location.pathname])

  useEffect(() => {
    if (new URLSearchParams(location.search).get('createlist') === 'true') {
      setListsOpen(true)
      navigate(location.pathname, { replace: true })
    }
  }, [location.pathname, location.search, navigate])

  useEffect(() => {
    loadUnread()
    if (!user?.id) return undefined
    const channel = createPostgresChannel(supabase, `sidebar-notifications-${user.id}`).on('postgres_changes', { event: '*', schema: 'public', table: 'notifications', filter: `user_id=eq.${user.id}` }, loadUnread).subscribe()
    return () => { supabase.removeChannel(channel) }
  }, [user?.id, loadUnread])

  useEffect(() => {
    const handlePointer = event => {
      const inMobileNav = mobileNavRef.current?.contains(event.target)
      const inMobileTopbar = mobileTopbarRef.current?.contains(event.target)
      const inMoreMenu = menuRef.current?.contains(event.target) || moreMenuContentRef.current?.contains(event.target)
      if (!inMobileNav && !inMobileTopbar && !inMoreMenu) setMoreOpen(false)
    }
    const handleEscape = event => { if (event.key === 'Escape') setMoreOpen(false) }
    document.addEventListener('pointerdown', handlePointer)
    document.addEventListener('keydown', handleEscape)
    return () => { document.removeEventListener('pointerdown', handlePointer); document.removeEventListener('keydown', handleEscape) }
  }, [])

  const active = path => location.pathname === path || (path !== '/home' && location.pathname.startsWith(path))
  const isAuthEntry = ['/login', '/register', '/forgot-password', '/confirm-email', '/update-password'].includes(location.pathname)
  const isProfilePage = location.pathname === '/profile' || /^\/profile\/[^/]+$/.test(location.pathname)
  const isWorkPage = /^\/(game|anime)\/[^/]+(\/reviews)?$/.test(location.pathname)
  const mobileNavIndex = active('/home') ? 0 : active('/search') ? 1 : active('/share') ? 2 : active('/spaces') ? 3 : -1

  return (
    <div className="layout" style={{ '--profile-theme-color': profile?.theme_color || 'var(--brand-primary)', '--profile-accent-visible': getVisibleAccentColor(profile?.theme_color || '#14b8a6'), '--profile-accent-text': getAccentTextColor(profile?.theme_color || '#14b8a6') }}>
      <aside className="app-sidebar" aria-label="Navegación principal">
        <Link className="sidebar-brand" to="/home" aria-label="GeekSphere, inicio">
          <span className="sidebar-brand-mark"><img src="/icons/logo.png" alt="" onError={event => { event.currentTarget.style.display = 'none' }} /></span>
          <span className="sidebar-brand-name">GeekSphere</span>
        </Link>

        <div className={`sidebar-top-space ${!user ? 'guest-sidebar-top-space' : ''}`} />
        {!user ? (
          <>
            <nav className="sidebar-nav guest-sidebar-nav" aria-label="Navegación para visitantes">
              <Link className={`sidebar-link ${active('/home') ? 'active current-page' : ''}`} to="/home" aria-current={active('/home') ? 'page' : undefined}><Icon name="home"/><span>Inicio</span></Link>
              <Link className={`sidebar-link ${active('/search') ? 'active current-page' : ''}`} to="/search" aria-current={active('/search') ? 'page' : undefined}><Icon name="search"/><span>Buscar</span></Link>
              <Link className={`sidebar-link ${isAuthEntry ? 'active current-page' : ''}`} to="/register" aria-current={isAuthEntry ? 'page' : undefined}><Icon name="user"/><span>Únete</span></Link>
            </nav>
            <nav className="guest-legal-links" aria-label="Información legal">
              <Link to="/terms">Términos</Link><Link to="/privacy">Privacidad</Link><Link to="/community-guidelines">Normas</Link>
            </nav>
          </>
        ) : <>
        <nav className="sidebar-nav">
          <Link className={`sidebar-link ${active('/home') ? 'active current-page' : ''}`} to="/home" aria-label="Inicio" aria-current={active('/home') ? 'page' : undefined}><Icon name="home"/><span className="sidebar-label" style={active('/home') ? { fontWeight: 800 } : undefined}>Inicio</span></Link>
          <Link className={`sidebar-link ${active('/spaces') ? 'active current-page' : ''}`} to={spacesPath} aria-label="Espacios" aria-current={active('/spaces') ? 'page' : undefined}><Icon name="spaces"/><span className="sidebar-label" style={active('/spaces') ? { fontWeight: 800 } : undefined}>Espacios</span></Link>
          <Link className={`sidebar-link ${active('/search') ? 'active current-page' : ''}`} to="/search" aria-label="Buscar" aria-current={active('/search') ? 'page' : undefined}><Icon name="search"/><span>Buscar</span></Link>
          <Link className={`sidebar-link ${active('/share') ? 'active current-page' : ''}`} to="/share" aria-label="Compartir" aria-current={active('/share') ? 'page' : undefined}><Icon name="share"/><span>Compartir</span></Link>
          <Link className={`sidebar-link ${active('/activity') ? 'active current-page' : ''}`} to="/activity" aria-label="Actividad" aria-current={active('/activity') ? 'page' : undefined}>
            <Icon name="activity"/><span>Actividad</span>{unreadCount > 0 && <span className="sidebar-unread">{unreadCount > 99 ? '99+' : unreadCount}</span>}
          </Link>
        </nav>

        <Link className={`sidebar-link sidebar-profile ${isProfilePage ? 'active current-page' : ''}`} to={profilePath} aria-label="Mi perfil" aria-current={isProfilePage ? 'page' : undefined}>
          {image ? <img className="sidebar-avatar" src={image} alt=""/> : <DefaultAvatar className="sidebar-avatar" accent={profile?.theme_color} />}
          <span className="sidebar-label" style={isProfilePage ? { fontWeight: 800 } : undefined}>Mi perfil</span>
        </Link>
        <div className="sidebar-bottom-space" />
        <div className="sidebar-popover-anchor more-anchor" ref={menuRef}>
          <button ref={moreButtonRef} className="sidebar-link more-link" type="button" aria-label="Más" aria-expanded={moreOpen} onClick={toggleMoreMenu}><Icon name="more"/><span>Más</span></button>
          {moreOpen && !isDesktop && <section className="sidebar-popover more-popover" aria-label="Más opciones">{moreMenu}</section>}
        </div>
        </>}
        <InstallApp className="sidebar-install" />
      </aside>

      <header className="mobile-topbar" ref={mobileTopbarRef}>
        <Link className="mobile-brand" to="/home" aria-label="GeekSphere, inicio">
          <img src="/icons/logo.png" alt="" />
          <span>GeekSphere</span>
        </Link>
        <div className="mobile-topbar-actions">
          <InstallApp className="topbar-install" />
          {user && <div className="mobile-topbar-anchor">
            <Link className={`mobile-topbar-button ${active('/activity') ? 'active' : ''}`} to="/activity" aria-label="Notificaciones" aria-current={active('/activity') ? 'page' : undefined}>
              <Icon name="activity" />
              {unreadCount > 0 && <i className="mobile-topbar-unread-dot" />}
            </Link>
          </div>}
          {user && <div className="mobile-topbar-anchor">
            <button className={`mobile-topbar-button ${moreOpen ? 'active' : ''}`} type="button" aria-label="Abrir menú" aria-expanded={moreOpen} onClick={toggleMoreMenu}><Icon name="more"/></button>
            {moreOpen && <section className="sidebar-popover mobile-topbar-popover mobile-topbar-menu" aria-label="Menú">{moreMenu}</section>}
          </div>}
        </div>
      </header>

      <nav className="mobile-bottom-nav" ref={mobileNavRef} aria-label="Navegación principal">
        {!user ? <div className="guest-mobile-actions">
          <Link to="/home" aria-label="Inicio"><Icon name="home"/><span>Inicio</span></Link>
          <Link to="/search" aria-label="Buscar"><Icon name="search"/><span>Buscar</span></Link>
          <Link className={isAuthEntry ? 'active' : ''} aria-current={isAuthEntry ? 'page' : undefined} to="/register"><Icon name="user"/><span>Únete</span></Link>
        </div> : <>
        <div className="mobile-nav-dock">
          {mobileNavIndex >= 0 && <span className="mobile-nav-indicator" style={{ '--active-index': mobileNavIndex }} aria-hidden="true" />}
          <Link className={`mobile-nav-item ${active('/home') ? 'active' : ''}`} to="/home" aria-label="Inicio" aria-current={active('/home') ? 'page' : undefined}><Icon name="home"/></Link>
          <Link className={`mobile-nav-item ${active('/search') ? 'active' : ''}`} to="/search" aria-label="Buscar" aria-current={active('/search') ? 'page' : undefined} onClick={() => setMoreOpen(false)}><Icon name="search"/></Link>
          <Link className={`mobile-nav-item mobile-share-item ${active('/share') ? 'active' : ''}`} to="/share" aria-label="Compartir" aria-current={active('/share') ? 'page' : undefined} onClick={() => setMoreOpen(false)}><Icon name="share"/></Link>
          <Link className={`mobile-nav-item ${active('/spaces') ? 'active' : ''}`} to={spacesPath} aria-label="Espacios" aria-current={active('/spaces') ? 'page' : undefined}><Icon name="spaces"/></Link>
        </div>
        <Link className={`mobile-profile-link ${isProfilePage ? 'active' : ''}`} to={profilePath} state={{ fromBottomNav: true }} aria-label="Mi perfil" aria-current={isProfilePage ? 'page' : undefined}>
          {image ? <img className="mobile-nav-avatar" src={image} alt=""/> : <DefaultAvatar className="mobile-nav-avatar" accent={profile?.theme_color} />}
        </Link>
        </>}
      </nav>

      <main className={`main ${['/terms', '/privacy', '/community-guidelines'].includes(location.pathname) ? 'legal-main' : ''} ${location.pathname === '/onboarding' ? 'onboarding-main' : ''} ${location.pathname === '/invite' ? 'invite-main' : ''} ${isProfilePage ? 'profile-main' : ''} ${isWorkPage ? 'work-main' : ''} ${['/discover/anime', '/discover/games', '/discover/lists'].includes(location.pathname) ? 'discover-works-main' : ''} ${location.pathname === '/discover/spaces' || location.pathname === '/spaces/explore' ? 'spaces-explore-main' : ''} ${location.pathname === '/spaces' ? 'my-spaces-main' : ''} ${/^\/reviews\/[^/]+/.test(location.pathname) ? 'review-detail-main' : ''} ${/^\/posts\/[^/]+$/.test(location.pathname) ? 'post-detail-main' : ''} ${/^\/lists\/[^/]+$/.test(location.pathname) ? 'list-detail-main' : ''} ${location.pathname === '/share' ? 'share-main' : ''}`}><Outlet /></main>

      {listsOpen && <ListsEntryModal onClose={() => setListsOpen(false)} />}
      {moreOpen && isDesktop && createPortal(
        <section ref={moreMenuContentRef} className="sidebar-popover more-popover more-popover-desktop" style={moreMenuPosition} aria-label="Más opciones">
          {moreMenu}
        </section>,
        document.body
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { getUserLibrary } from '../lib/libraryService'
import { getWorkById } from '../lib/workPageService'
import ReviewLikeButton from './ReviewLikeButton'
import SpoilerNotice from './reviews/SpoilerNotice'
import { useAuth } from '../context/AuthContext'
import './LibraryGrid.css'

export default function LibraryGrid({ profile, userId, username, wishlist = [] }) {
    const { user, profile: myProfile, updateProfile } = useAuth()
    const [loading, setLoading] = useState(true)
    const [recentReviews, setRecentReviews] = useState([])
    const [diaryMonths, setDiaryMonths] = useState([])
    const [revealedSpoilers, setRevealedSpoilers] = useState({})
    const [expandedReviews, setExpandedReviews] = useState({})

    const isOwnProfile = user?.id === userId;

    const toggleExpand = (e, id) => {
        e.preventDefault()
        setExpandedReviews(prev => ({ ...prev, [id]: !prev[id] }))
    }

    const getWorkYear = (work, type) => {
        if (!work.release_date) return '';
        if (type === 'game') {
            if (typeof work.release_date === 'number') {
                return new Date(work.release_date * 1000).getFullYear();
            }
            return new Date(work.release_date).getFullYear();
        } else {
            return new Date(work.release_date).getFullYear();
        }
    }

    const toggleSpoiler = (id) => {
        setRevealedSpoilers(prev => ({ ...prev, [id]: true }))
    }

    useEffect(() => {
        if (!userId) return

        const fetchActivity = async () => {
            setLoading(true)
            try {
                // Fetch all logs
                const logs = await getUserLibrary(userId)

                // Fetch populated data
                const populatedLogs = await Promise.all(logs.map(async (log) => {
                    const workDetails = await getWorkById(log.work_type, parseInt(log.work_id))
                    return {
                        ...log,
                        work: workDetails
                    }
                }))

                const validLogs = populatedLogs.filter(log => log.work !== null)

                // 1. Reseñas Destacadas
                const allReviews = validLogs
                    .filter(log => log.review_text && log.review_text.trim() !== '')
                    .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

                let displayedReviews = [];
                const pinnedId = isOwnProfile ? myProfile?.pinned_review_id : profile?.pinned_review_id;
                const pinnedReview = pinnedId ? allReviews.find(r => r.id === pinnedId) : null;

                if (pinnedReview) {
                    displayedReviews.push({ ...pinnedReview, isPinned: true });
                    const others = allReviews.filter(r => r.id !== pinnedId);
                    if (others.length > 0) displayedReviews.push(others[0]);
                } else {
                    displayedReviews = allReviews.slice(0, 2);
                }

                setRecentReviews(displayedReviews)

                // 2. Diary Grouped By Month (using finished_date, fallback to created_at)
                const monthGroups = {}
                validLogs.forEach(log => {
                    const dateObj = new Date(log.finished_date || log.created_at)
                    const shortMonth = dateObj.toLocaleDateString('es-ES', { month: 'short' }).toUpperCase().substring(0, 3)
                    const yearStr = dateObj.getFullYear()
                    const monthKey = `${shortMonth}-${yearStr}`

                    if (!monthGroups[monthKey]) {
                        monthGroups[monthKey] = {
                            id: monthKey,
                            shortMonth,
                            year: yearStr,
                            dateForSort: new Date(dateObj.getFullYear(), dateObj.getMonth(), 1),
                            entries: []
                        }
                    }
                    monthGroups[monthKey].entries.push({
                        ...log,
                        day: dateObj.getDate()
                    })
                })

                // Sort months descending and take top 2
                const sortedMonths = Object.values(monthGroups)
                    .sort((a, b) => b.dateForSort - a.dateForSort)
                    .slice(0, 2)

                // Sort entries within each month by day descending
                sortedMonths.forEach(m => {
                    m.entries.sort((a, b) => b.day - a.day)
                })

                setDiaryMonths(sortedMonths)

            } catch (err) {
                console.error('Error fetching activity:', err)
            } finally {
                setLoading(false)
            }
        }

        fetchActivity()
    }, [userId])

    if (loading) {
        return (
            <div className="profile-activity-skeleton" aria-label="Cargando actividad del perfil" aria-busy="true">
                <section className="profile-activity-skeleton-column">
                    <span className="profile-activity-skeleton-heading" />
                    {[0, 1].map(index => <div className="profile-review-skeleton" key={index} aria-hidden="true"><i className="is-poster" /><span><i /><i /><i /><i /></span></div>)}
                </section>
                <section className="profile-activity-skeleton-column">
                    <span className="profile-activity-skeleton-heading is-short" />
                    {[0, 1, 2].map(index => <div className="profile-diary-skeleton" key={index} aria-hidden="true"><i className="is-cover" /><span><i /><i /></span></div>)}
                </section>
                <section className="profile-activity-skeleton-wishlist" aria-hidden="true"><span className="profile-activity-skeleton-heading is-short" /><div>{[0, 1, 2, 3, 4].map(index => <i key={index} />)}</div></section>
            </div>
        )
    }

    if (recentReviews.length === 0 && diaryMonths.length === 0) {
        return (
            <div className="activity-empty">
                <p>No hay actividad reciente en el diario.</p>
            </div>
        )
    }

    const renderStars = (rating) => {
        if (!rating) return null;
        const stars = [];
        for (let i = 1; i <= 5; i++) {
            let fill = "transparent";
            if (rating >= i) fill = "var(--profile-accent-visible, var(--brand-primary))";
            else if (rating === i - 0.5) fill = "url(#halfStarSmall)";
            stars.push(
                <svg key={i} viewBox="0 0 24 24" width="14" height="14">
                    <defs>
                        <linearGradient id="halfStarSmall">
                            <stop offset="50%" stopColor="var(--profile-accent-visible, var(--brand-primary))" />
                            <stop offset="50%" stopColor="transparent" stopOpacity="1" />
                        </linearGradient>
                    </defs>
                    <path 
                        d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"
                        fill={fill}
                        stroke="var(--profile-accent-visible, var(--brand-primary))"
                        strokeWidth="1.5"
                        strokeLinejoin="round"
                    />
                </svg>
            )
        }
        return <div className="activity-stars">{stars}</div>
    }

    return (
        <>
        <div className="profile-activity-container" style={{ display: 'grid', gridTemplateColumns: 'var(--grid-cols, 5fr 3fr)', gap: 'var(--grid-gap, 3rem)', width: '100%', alignItems: 'start' }}>
            {/* LEFT COLUMN: RECENT REVIEWS */}
            <div className="activity-col activity-reviews" style={{ display: 'flex', flexDirection: 'column', minWidth: 0 }}>
                <div className="activity-col-header">
                    <h3>Reseñas Destacadas</h3>
                    {username && <Link to={`/profile/${username}/reviews`} className="activity-view-all">Ver todas</Link>}
                </div>

                {recentReviews.length === 0 ? (
                    <div className="activity-empty-box">Aún no hay Reseñas.</div>
                ) : (
                    <div className="reviews-list">
                        {recentReviews.map(log => (
                            <div key={log.id} className="review-card" style={{ position: 'relative' }}>
                                {log.isPinned && (
                                    <div style={{ position: 'absolute', top: '8px', right: '8px', zIndex: 10, color: 'var(--profile-accent-visible, var(--brand-primary))' }} title="Reseña destacada">
                                        <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 17v5"/><path d="M5 17h14v-1.76a2 2 0 0 0-1.11-1.79l-1.78-.9A2 2 0 0 1 15 10.68V6a3 3 0 0 0-3-3 3 3 0 0 0-3 3v4.68a2 2 0 0 1-1.11 1.79l-1.78.9A2 2 0 0 0 5 15.24Z"/></svg>
                                    </div>
                                )}
                                <Link to={`/${log.work_type}/${log.work_id}`} className="review-poster-link">
                                    <div className="review-poster" style={{ backgroundImage: `url(${log.work_type === 'game' ? log.work.cover_url : log.work.image_url})` }}></div>
                                </Link>
                                <div className="review-content">
                                    <div className="review-header">
                                        <Link to={`/reviews/${log.id}`} className="review-title">
                                            {log.work_type === 'game' ? log.work.name : log.work.title}
                                        </Link>
                                        <span className="review-year">
                                            {getWorkYear(log.work, log.work_type)}
                                        </span>
                                    </div>
                                    <div className="review-metadata">
                                        {renderStars(log.rating)}
                                        {log.finished_date && (
                                            <span className="review-finished-date">
                                                Finished {new Date(log.finished_date).toLocaleDateString('es-ES', { day: '2-digit', month: 'short', year: 'numeric' })}
                                            </span>
                                        )}
                                    </div>
                                    <p className="review-text">
                                        {log.contains_spoiler && !revealedSpoilers[log.id] ? (
                                            <SpoilerNotice
                                                text={expandedReviews[log.id] || log.review_text.length <= 250
                                                    ? `${log.review_text}${expandedReviews[log.id] && log.review_text.length > 250 ? ' less' : ''}`
                                                    : `${log.review_text.substring(0, 250)}... more`}
                                                onReveal={() => toggleSpoiler(log.id)}
                                            />
                                        ) : (
                                            <>
                                                {expandedReviews[log.id] || log.review_text.length <= 250 
                                                    ? log.review_text 
                                                    : `${log.review_text.substring(0, 250)}... `}
                                                {log.review_text.length > 250 && (
                                                    <a href="#" className="review-more-btn" onClick={(e) => toggleExpand(e, log.id)}>
                                                        {expandedReviews[log.id] ? 'less' : 'more'}
                                                    </a>
                                                )}
                                            </>
                                        )}
                                    </p>
                                    <ReviewLikeButton entryId={log.id} />
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* RIGHT COLUMN: DIARY */}
            <div className="activity-col activity-diary" style={{ display: 'flex', flexDirection: 'column', minWidth: 0 }}>
                <div className="activity-col-header">
                    <h3>Diario</h3>
                    {username && <Link to={`/profile/${username}/diary`} className="activity-view-all">Ver diario</Link>}
                </div>

                {diaryMonths.length === 0 ? (
                    <div className="activity-empty-box">Aún no hay entradas en el diario.</div>
                ) : (
                    <div className="diary-list">
                        {diaryMonths.map(month => (
                            <div key={month.id} className="diary-month-group">
                                <div className="diary-month-header">
                                    <div className="diary-month-calendar">
                                        <div className="calendar-rings"><span></span><span></span><span></span></div>
                                        <div className="calendar-body">{month.shortMonth}</div>
                                    </div>
                                    <span className="diary-month-year">{month.year}</span>
                                </div>
                                <div className="diary-entries">
                                    {month.entries.map(log => (
                                        <div key={log.id} className="diary-entry">
                                            <div className="diary-day">{log.day}</div>
                                            <Link to={`/${log.work_type}/${log.work_id}`} className="diary-entry-poster">
                                                <div className="diary-micro-poster" style={{ backgroundImage: `url(${log.work_type === 'game' ? log.work.cover_url : log.work.image_url})` }}></div>
                                            </Link>
                                            <div className="diary-entry-info">
                                                <div className="diary-entry-header">
                                                    <Link to={`/${log.work_type}/${log.work_id}`} className="diary-entry-title">
                                                        {log.work_type === 'game' ? log.work.name : log.work.title}
                                                    </Link>
                                                    <span className="diary-entry-year">
                                                        {getWorkYear(log.work, log.work_type)}
                                                    </span>
                                                </div>
                                                {renderStars(log.rating)}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>

        {/* WISHLIST — below both columns, centered */}
        {wishlist && wishlist.length > 0 && (
            <div className="profile-wishlist-section">
                <div className="activity-col-header">
                    <h3>Lista de Deseos</h3>
                    {username && <Link to={`/profile/${username}/wishlist`} className="activity-view-all">Ver más</Link>}
                </div>
                <div className="wishlist-poster-stack">
                    {wishlist.slice(0, 10).map(item => (
                        <Link
                            key={`${item.type}-${item.id}`}
                            to={`/${item.type}/${item.id}`}
                            className="wishlist-stack-item"
                            title={item.title}
                        >
                            <img src={item.image_url} alt={item.title} />
                            <div className="wishlist-stack-overlay">
                                <span>{item.title}</span>
                            </div>
                        </Link>
                    ))}
                    {wishlist.length > 10 && (
                        <Link to={`/profile/${username}/wishlist`} className="wishlist-stack-more">
                            +{wishlist.length - 10} más
                        </Link>
                    )}
                </div>
            </div>
        )}
        </>
    )
}

import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './MoreContentCards.css';

function readableAccentText(color) {
  const match = String(color || '').match(/^#([\da-f]{3}|[\da-f]{6})$/i);
  if (!match) return '#fff';
  let hex = match[1];
  if (hex.length === 3) hex = [...hex].map(char => char + char).join('');
  const channels = [0, 2, 4].map(index => parseInt(hex.slice(index, index + 2), 16) / 255);
  const luminance = channels.map(value => value <= .04045 ? value / 12.92 : ((value + .055) / 1.055) ** 2.4)
    .reduce((sum, value, index) => sum + value * [0.2126, 0.7152, 0.0722][index], 0);
  return luminance > .42 ? '#111' : '#fff';
}

function listImages(value, result = [], seen = new Set()) {
  if (!value || typeof value !== 'object' || seen.has(value) || result.length >= 4) return result;
  seen.add(value);
  const url = value.image_url || value.cover_url || value.cover?.url;
  if (typeof url === 'string' && url && !result.includes(url)) result.push(url);
  for (const child of Array.isArray(value) ? value : Object.values(value)) {
    listImages(child, result, seen);
    if (result.length >= 4) break;
  }
  return result;
}

function MorePostCard({ post, accent }) {
  const [imageFailed, setImageFailed] = useState(false);
  const sensitiveOnly = post.is_sensitive && !post.contains_spoiler;
  const image = !post.is_sensitive && !post.contains_spoiler && Array.isArray(post.media)
    ? post.media.find(media => media?.url)?.url
    : null;
  const preview = post.contains_spoiler
    ? `Spoiler${post.spoiler_work_title ? ` de ${post.spoiler_work_title}` : ''}`
    : post.is_sensitive ? 'Contenido sensible' : post.body || 'Publicación';

  return <Link
    to={`/posts/${post.id}`}
    className={`more-author-post-card${image && !imageFailed ? ' has-image' : ''}${imageFailed ? ' is-image-error' : ''}${sensitiveOnly ? ' is-sensitive' : ''}`}
    style={{ '--more-author-accent': accent || 'var(--brand-primary)', '--more-author-text': readableAccentText(accent) }}
    aria-label={imageFailed ? 'No se pudo cargar la imagen' : preview}
  >
    {image && !imageFailed && <img src={image} alt="" loading="lazy" onError={() => setImageFailed(true)} />}
    {imageFailed ? <span className="more-author-post-error">No se pudo cargar la imagen</span>
      : sensitiveOnly
        ? <svg className="more-author-post-sensitive" viewBox="0 0 24 24" role="img" aria-label="Contenido sensible"><path d="M3 3 21 21"/><path d="M10.6 10.6a2 2 0 0 0 2.8 2.8"/><path d="M9.9 5.2A11.3 11.3 0 0 1 12 5c5.5 0 9.5 4.5 10 7-.2 1.1-1.2 2.6-2.6 3.9"/><path d="M6.6 6.6C3.9 8.2 2.2 10.6 2 12c.5 2.5 4.5 7 10 7 1.2 0 2.3-.2 3.3-.6"/></svg>
        : !image && <span className="more-author-post-copy">{preview}</span>}
  </Link>;
}

function MoreListCard({ list, accent }) {
  const images = listImages(list.content);
  return <Link to={`/lists/${list.id}`} className={`more-author-list-card${images.length ? ' has-artwork' : ''}`} style={{ '--more-author-accent': accent || 'var(--brand-primary)' }} aria-label={`Lista: ${list.title || 'Lista'}`}>
    <div className={`more-author-list-cover${images.length ? '' : ' is-empty'}`}>
      {images.length ? <div className={`more-author-list-art art-count-${images.length}`}>
        {images.map((image, index) => <img key={`${image}-${index}`} src={image} alt="" loading="lazy" />)}
      </div> : <div className={`more-author-list-abstract type-${list.list_type || 'tierlist'}`} aria-hidden="true">
        {[0, 1, 2].map((row, index) => <i key={row} style={{ '--cover-row-accent': `color-mix(in srgb, var(--more-author-accent) ${28 + index * 12}%, #303038)` }} />)}
      </div>}
    </div>
  </Link>;
}

export function normalizeMoreContent({ posts = [], lists = [], limit = 3 } = {}) {
  const items = [
    ...posts.map(post => ({ type: 'post', data: post, created_at: post.created_at, key: `post:${post.id}` })),
    ...lists.map(list => ({ type: 'list', data: list, created_at: list.created_at, key: `list:${list.id}` })),
  ].sort((a, b) => (Date.parse(b.created_at || '') || 0) - (Date.parse(a.created_at || '') || 0));
  const selected = [];
  const selectedTypes = new Set();
  for (const item of items) {
    if (!selectedTypes.has(item.type)) {
      selected.push(item);
      selectedTypes.add(item.type);
      if (selected.length === limit) return selected;
    }
  }
  const selectedKeys = new Set(selected.map(item => item.key));
  return [...selected, ...items.filter(item => !selectedKeys.has(item.key))].slice(0, limit);
}

export default function MoreContentCards({ items = [], accent, className = 'more-author-post-grid' }) {
  return <div className={className}>
    {items.map(item => item.type === 'list'
      ? <MoreListCard key={item.key} list={item.data} accent={accent} />
      : <MorePostCard key={item.key} post={item.data} accent={accent} />)}
  </div>;
}

import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../context/AuthContext'
import DefaultAvatar from './DefaultAvatar'
import './RecommendationCard.css'

export default function RecommendationCard({ recommendation, onAddToLibrary }) {
    const { user, profile } = useAuth()
    const navigate = useNavigate()
    const [isAdding, setIsAdding] = useState(false)

    const { work_id, media_type, score, reasons, title, image_url } = recommendation

    // Determine link based on media type
    const detailsLink = media_type === 'game'
        ? `/game/${work_id}`
        : `/anime/${work_id}`

    const handleAddToLibrary = async (status = 'wishlist') => {
        if (isAdding) return
        if (!user) {
            navigate('/register')
            return
        }
        if (!profile) {
            navigate('/onboarding')
            return
        }

        setIsAdding(true)
        try {
            if (onAddToLibrary) {
                await onAddToLibrary(recommendation, status)
            }
        } catch (error) {
            console.error('Error adding to library:', error)
        } finally {
            setIsAdding(false)
        }
    }

    // Determine score color
    const getScoreClass = () => {
        if (score >= 80) return 'high'
        if (score >= 60) return 'medium'
        return 'low'
    }

    return (
        <div className="recommendation-card">
            <Link to={detailsLink} className="recommendation-link">
                <div className="recommendation-image">
                    {image_url ? (
                        <img src={image_url} alt={title || 'Recommendation'} />
                    ) : (
                        <div className="recommendation-placeholder">
                            {media_type === 'anime' ? <img src="/icons/anime.png" alt="📺" style={{ width: '40px', height: '40px', opacity: 0.5 }} /> : <img src="/icons/videogame.png" alt="🎮" style={{ width: '40px', height: '40px', opacity: 0.5 }} />}
                        </div>
                    )}

                    {/* Social Source Avatar (instead of score) */}
                    {reasons && reasons[0]?.type === 'following' && reasons[0]?.user && (
                        <div className="recommendation-social-avatar" title={`Recomendado por ${reasons[0].user.username}`}>
                            {reasons[0].user.avatar_url
                                ? <img src={reasons[0].user.avatar_url} alt={reasons[0].user.username} />
                                : <DefaultAvatar accent={reasons[0].user.theme_color} title={reasons[0].user.username} />}
                        </div>
                    )}
                </div>

                <div className="recommendation-content">
                    <h3 className="recommendation-title">
                        {title || 'Sin título'}
                    </h3>

                    {reasons && reasons.length > 0 && (
                        <div className="recommendation-reasons">
                            {reasons.map((reason, i) => (
                                <div key={i} className="reason-item" title={reason.text}>
                                    <span className="reason-icon">
                                        {reason.icon === '✅' ? (
                                            <img src="/icons/check.png" alt="✅" style={{ width: '14px', height: '14px', verticalAlign: 'middle' }} />
                                        ) : reason.icon === '📋' ? (
                                            <img src="/icons/checklist.png" alt="📋" style={{ width: '14px', height: '14px', verticalAlign: 'middle' }} />
                                        ) : reason.icon === '🔥' ? (
                                            <img src="/icons/fire.gif" alt="🔥" style={{ width: '14px', height: '14px', verticalAlign: 'middle' }} />
                                        ) : reason.icon === '💯' ? (
                                            <img src="/icons/crown.png" alt="💯" style={{ width: '14px', height: '14px', verticalAlign: 'middle' }} />
                                        ) : reason.icon === '⭐' ? (
                                            <img src="/icons/star.png" alt="⭐" style={{ width: '14px', height: '14px', verticalAlign: 'middle' }} />
                                        ) : reason.icon === '🤝' ? (
                                            <img src="/icons/wishlist.png" alt="🤝" style={{ width: '14px', height: '14px', verticalAlign: 'middle' }} />
                                        ) : reason.icon}
                                    </span>
                                    <span className="reason-text">{reason.text}</span>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </Link >

            <div className="recommendation-actions">
                <button
