/* ── Single toast card ── */
function ToastItem({ title, message, type = 'info', icon, exiting, onDismiss }) {
    const resolvedIcon = icon ?? DEFAULT_ICONS[type] ?? DEFAULT_ICONS.info

    return (
        <div
            className={`toast-card${exiting ? ' exiting' : ''}`}
            data-type={type}
            role={type === 'error' ? 'alert' : 'status'}
            aria-atomic="true"
        >
            <div className="toast-icon-wrap" aria-hidden="true">
                {resolvedIcon}
            </div>

            <div className="toast-body">
                <div className="toast-title">{title}</div>
                {message && <div className="toast-message">{message}</div>}
            </div>

            <button type="button" className="toast-dismiss" onClick={onDismiss} aria-label="Cerrar notificación">
                <IconX />
            </button>

        </div>
    )
}

/* ── Provider ── */
export function ToastProvider({ children }) {
    const [toasts, setToasts] = useState([])

    const dismiss = useCallback((id) => {
        setToasts(prev => prev.map(t => t.id === id ? { ...t, exiting: true } : t))
        setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 180)
    }, [])

    const toast = useCallback(({ title, message, type = 'info', icon, duration = 2000 } = {}) => {
        const id = ++_id
        setToasts(prev => [...prev, { id, title, message, type, icon, exiting: false }])
        if (duration > 0) {
            setTimeout(() => dismiss(id), duration)
        }
        return id
    }, [dismiss])

    useEffect(() => {
        const accountLabel = sessionStorage.getItem('geeksphere.account-switched-toast')
        if (accountLabel === null) return
        sessionStorage.removeItem('geeksphere.account-switched-toast')
        toast({ title: `Ahora estás en ${accountLabel || 'tu cuenta'}`, type: 'success', duration: 2000 })
    }, [toast])

    return (
        <ToastContext.Provider value={{ toast, dismiss }}>
            {children}
            {createPortal(
                <div className="toast-container" aria-label="Notificaciones">
                    {toasts.map(t => (
                        <ToastItem
                            key={t.id}
                            {...t}
                            onDismiss={() => dismiss(t.id)}
                        />
                    ))}
                </div>,
                document.body
            )}
        </ToastContext.Provider>
    )
}

/* ── Hook ── */
export function useToast() {
    const ctx = useContext(ToastContext)
    if (!ctx) throw new Error('useToast debe usarse dentro de <ToastProvider>')
    return ctx
}

import { useState, useEffect } from 'react'
import { getUserTierlists } from '../../lib/socialDiscoveryService'
import { searchGames } from '../../lib/gameService'
import { searchAnime } from '../../lib/animeService'
import LoadingSpinner from '../LoadingSpinner'

export function ChatShareModal({ isOpen, onClose, onSelect, userId }) {
    if (!isOpen) return null

    const [activeTab, setActiveTab] = useState('tierlist')
    const [loading, setLoading] = useState(false)
    const [items, setItems] = useState([])
    const [searchQuery, setSearchQuery] = useState('')
    const [debouncedQuery, setDebouncedQuery] = useState('')
    const [error, setError] = useState(null)

    // Debounce search
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedQuery(searchQuery)
        }, 500)
        return () => clearTimeout(timer)
    }, [searchQuery])

    // Fetch data based on tab
    useEffect(() => {
        setError(null)

        const fetchData = async () => {
            setLoading(true)
            try {
                let data = []
                if (activeTab === 'tierlist') {
                    if (!userId) {
                        setError('Usuario no identificado')
                        setItems([])
                        return
                    }
                    data = await getUserTierlists(userId)
                } else if (activeTab === 'game') {
                    if (debouncedQuery.length >= 2) {
                        data = await searchGames(debouncedQuery)
                    }
                } else if (activeTab === 'anime') {
                    if (debouncedQuery.length >= 2) {
                        data = await searchAnime(debouncedQuery)
                    }
                }
                setItems(data || [])
            } catch (err) {
                console.error('Error fetching share items:', err)
                setError('Error al cargar los datos')
                setItems([])
            } finally {
                setLoading(false)
            }
        }

        fetchData()
    }, [activeTab, userId, debouncedQuery])

    const handleSelect = (item) => {
        let tag = ''
        let type = ''
        let extra = ''

        if (activeTab === 'tierlist') {
            type = 'TIERLIST'
            tag = `[TIERLIST|${item.id}|${item.name || item.title}|${item.cover_url || ''}]`
        } else if (activeTab === 'game') {
            type = 'WORK'
            extra = 'game'
            tag = `[WORK|${item.id}|${item.name || item.title}|${item.cover_url || item.image_url || ''}|game]`
        } else if (activeTab === 'anime') {
            type = 'WORK'
            extra = 'anime'
            tag = `[WORK|${item.id}|${item.name || item.title}|${item.cover_url || item.image_url || ''}|anime]`
        }

        onSelect({
            tag,
            type,
            id: item.id,
            title: item.name || item.title,
            image: item.cover_url || item.image_url,
            extra
        })
        onClose()
    }

    return (
        <div className="share-modal-overlay" onClick={onClose}>
            <div className="share-modal-content" onClick={e => e.stopPropagation()}>
                <div className="share-modal-header">
                    <h3>Compartir contenido</h3>
                    <button onClick={onClose} className="close-btn">✕</button>
                </div>

                <div className="share-tabs">
                    <button
                        className={`tab-btn ${activeTab === 'tierlist' ? 'active' : ''}`}
                        onClick={() => { setActiveTab('tierlist'); setSearchQuery('') }}
                    >
                        <img src="/icons/tierlist.png" alt="📊" style={{ width: '16px', height: '16px', verticalAlign: 'middle', marginRight: '6px' }} /> Tierlists
                    </button>
                    <button
                        className={`tab-btn ${activeTab === 'game' ? 'active' : ''}`}
                        onClick={() => { setActiveTab('game'); setSearchQuery('') }}
                    >
                        <img src="/icons/videogame.png" alt="🎮" style={{ width: '16px', height: '16px', marginRight: '6px' }} /> Juegos
                    </button>
                    <button
                        className={`tab-btn ${activeTab === 'anime' ? 'active' : ''}`}
                        onClick={() => { setActiveTab('anime'); setSearchQuery('') }}
                    >
                        <img src="/icons/anime.png" alt="📺" style={{ width: '16px', height: '16px', marginRight: '6px' }} /> Anime
                    </button>
                </div>

                {(activeTab === 'game' || activeTab === 'anime') && (
                    <div className="share-search">
                        <input
                            type="text"
                            placeholder={activeTab === 'game' ? 'Buscar juego...' : 'Buscar anime...'}
                            value={searchQuery}
                            onChange={e => setSearchQuery(e.target.value)}
                            autoFocus
                        />
                    </div>
                )}

                <div className="share-list">
                    {error ? (
                        <div className="error-state">{error}</div>
                    ) : loading ? (
                        <div className="loading-container">
                            <LoadingSpinner />
                        </div>
                    ) : items.length > 0 ? (
                        items.map(item => (
                            <div key={item.id} className="share-item" onClick={() => handleSelect(item)}>
                                <div className="share-item-img">
                                    {item.cover_url || item.image_url ? (
                                        <img src={item.cover_url || item.image_url} alt="" />
                                    ) : (
                                        <div className="placeholder-img">
                                            {activeTab === 'tierlist' ? <img src="/icons/tierlist.png" alt="📊" style={{ width: '24px', height: '24px', opacity: 0.7 }} /> : activeTab === 'anime' ? <img src="/icons/anime.png" alt="📺" style={{ width: '24px', height: '24px', opacity: 0.7 }} /> : <img src="/icons/videogame.png" alt="🎮" style={{ width: '24px', height: '24px', opacity: 0.7 }} />}
                                        </div>
                                    )}
                                </div>
                                <div className="share-item-info">
                                    <h4>{item.name || item.title}</h4>
                                    {item.category && <span>{item.category}</span>}
                                </div>
                            </div>
                        ))
                    ) : (
                        <div className="empty-state">
                            {(activeTab === 'game' || activeTab === 'anime') && searchQuery.length < 2
                                ? 'Escribe para buscar'
                                : activeTab === 'tierlist'
                                    ? 'No tienes tierlists'
                                    : 'No se encontraron resultados'}
                        </div>
                    )}
                </div>
            </div>
        </div>
    )
}

import { useState, useEffect } from 'react'
import { createPortal } from 'react-dom'
import { createReview, updateReview } from '../../lib/reviewService'
import { useAuth } from '../../context/AuthContext'
import './QuickReviewModal.css'

export default function QuickReviewModal({
    workId,
    workType,
    workTitle,
    imageUrl,
    existingReview,
    onClose,
    onSaved
}) {
    const { user, profile, updateProfile } = useAuth()
    const [rating, setRating] = useState(existingReview?.rating || 0)
    const [hoverRating, setHoverRating] = useState(0)
    const [content, setContent] = useState(existingReview?.content || '')
    const [isSpoiler, setIsSpoiler] = useState(existingReview?.is_spoiler || false)
    const [isSubmitting, setIsSubmitting] = useState(false)

    const handleSubmit = async (e) => {
        e.preventDefault()
        setIsSubmitting(true)
        try {
            if (existingReview) {
                await updateReview(existingReview.id, {
                    title: existingReview.title || workTitle,
                    content,
                    rating,
                    isSpoiler
                })
            } else {
                await createReview({
                    workId,
                    workType,
                    title: workTitle,
                    content,
                    rating,
                    isSpoiler,
                    userId: user.id
                })
            }

            // Remove from wishlist if it's there
            if (profile && profile.wishlist) {
                const wishlistIndex = profile.wishlist.findIndex(i => String(i.id) === String(workId) && i.type === workType);
                if (wishlistIndex >= 0) {
                    const newWishlist = [...profile.wishlist];
                    newWishlist.splice(wishlistIndex, 1);
                    await updateProfile({ wishlist: newWishlist });
                }
            }

            onSaved()
        } catch (error) {
            console.error(error)
            alert('Error al guardar la reseña')
        } finally {
            setIsSubmitting(false)
        }
    }

    return createPortal((
        <div className="modal-overlay quick-review-overlay" onClick={onClose}>
            <div className="modal" style={{ maxWidth: '480px' }} onClick={e => e.stopPropagation()}>
                <div className="modal-header">
                    <h2>Reseña: {workTitle}</h2>
                    <button className="modal-close" onClick={onClose}>×</button>
                </div>
                <div className="modal-body" style={{ display: 'flex', gap: '1rem', alignItems: 'flex-start' }}>
                    {imageUrl && (
                        <div style={{ flexShrink: 0, width: '80px' }}>
                            <img 
                                src={imageUrl} 
                                alt={workTitle} 
                                style={{ width: '100%', borderRadius: '4px', aspectRatio: '3/4', objectFit: 'cover' }} 
                            />
                            <div style={{ 
                                marginTop: '0.5rem', 
                                textAlign: 'center', 
                                fontSize: '0.7rem', 
                                background: 'var(--bg-tertiary)', 
                                padding: '2px 4px', 
                                borderRadius: '4px',
                                color: 'var(--text-secondary)'
                            }}>
                                {workType === 'game' ? 'Juego' : 'Anime'}
                            </div>
                        </div>
                    )}
                    
                    <form onSubmit={handleSubmit} style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                        <div>
                            <div style={{ display: 'flex', gap: '4px', cursor: 'pointer' }} onMouseLeave={() => setHoverRating(0)}>
                                {[1, 2, 3, 4, 5].map(star => (
                                    <svg
                                        key={star}
                                        width="28" height="28" viewBox="0 0 24 24"
                                        fill={(hoverRating || rating) >= star ? '#fbbf24' : 'transparent'}
                                        stroke="#fbbf24" strokeWidth="2"
                                        strokeLinecap="round" strokeLinejoin="round"
                                        onMouseEnter={() => setHoverRating(star)}
                                        onClick={() => setRating(star)}
                                    >
                                        <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
                                    </svg>
                                ))}
                            </div>
                            <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                                {rating > 0 ? `${rating} estrellas` : 'Sin calificación'}
                            </span>
                        </div>

                        <textarea
                            className="input"
                            placeholder={`Tu opinión sobre ${workTitle}... (Opcional)`}
                            rows={4}
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                            style={{ resize: 'vertical' }}
                        />

                        <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '0.9rem', color: 'var(--text-primary)' }}>
                            <input
                                type="checkbox"
                                checked={isSpoiler}
                                onChange={(e) => setIsSpoiler(e.target.checked)}
                            />
