                        </label>

                        <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end', marginTop: '0.5rem' }}>
                            <button type="button" className="btn btn-ghost" onClick={onClose} disabled={isSubmitting}>
                                Cancelar
                            </button>
                            <button type="submit" className="btn btn-primary" disabled={isSubmitting}>
                                {isSubmitting ? 'Guardando...' : 'Guardar reseña'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    ), document.body)
}

import { useState, useEffect } from 'react'
import { useAuth } from '../../context/AuthContext'
import { toggleReaction, getReviewComments, postReviewComment, deleteReview } from '../../lib/reviewService'
import { formatRelativeDate } from '../../lib/formatRelativeDate'
import { Link } from 'react-router-dom'
import DefaultAvatar from '../DefaultAvatar'
import './Reviews.css'

export default function ReviewCard({ review, myReaction, onReactionUpdate, onEdit, onDelete }) {
    const { user } = useAuth()
    const [showSpoiler, setShowSpoiler] = useState(!review.is_spoiler)
    const [comments, setComments] = useState([])
    const [showComments, setShowComments] = useState(false)
    const [replying, setReplying] = useState(false)
    const [replyText, setReplyText] = useState('')
    const [isDeleting, setIsDeleting] = useState(false)

    const isOwner = user && user.id === review.user_id

    // Optimistic reaction UI
    const [optimisticCounts, setOptimisticCounts] = useState({
        good_point: review.count_good_point || 0,
        interesting: review.count_interesting || 0,
        strong_opinion: review.count_strong_opinion || 0
    })
    const [currentReaction, setCurrentReaction] = useState(myReaction)

    useEffect(() => {
        setOptimisticCounts({
            good_point: review.count_good_point || 0,
            interesting: review.count_interesting || 0,
            strong_opinion: review.count_strong_opinion || 0
        })
        setCurrentReaction(myReaction)
    }, [review, myReaction])

    const handleDelete = async () => {
        if (!window.confirm('¿Seguro que quieres borrar tu review?')) return

        setIsDeleting(true)
        try {
            await deleteReview(review.id)
            if (onDelete) onDelete()
        } catch (err) {
            console.error('Error deleting review:', err)
            setIsDeleting(false)
        }
    }

    const handleReaction = async (type) => {
        if (!user) return // TODO: Trigger login?

        const oldReaction = currentReaction
        const oldCounts = { ...optimisticCounts }

        // Optimistic Update
        let newReaction = null
        if (oldReaction === type) {
            // Untoggle
            setOptimisticCounts(prev => ({ ...prev, [type]: Math.max(0, prev[type] - 1) }))
            setCurrentReaction(null)
        } else {
            // Toggle/Swap
            setOptimisticCounts(prev => ({
                ...prev,
                [oldReaction]: oldReaction ? Math.max(0, prev[oldReaction] - 1) : prev[oldReaction],
                [type]: prev[type] + 1
            }))
            setCurrentReaction(type)
            newReaction = type
        }

        try {
            await toggleReaction(review.id, type, user.id)
            if (onReactionUpdate) onReactionUpdate()
        } catch (err) {
            // Revert
            setOptimisticCounts(oldCounts)
            setCurrentReaction(oldReaction)
            console.error('Error reaction', err)
        }
    }

    const handleLoadComments = async () => {
        if (showComments) {
            setShowComments(false)
            return
        }
        try {
            const data = await getReviewComments(review.id)
            setComments(data || [])
            setShowComments(true)
        } catch (err) {
            console.error(err)
        }
    }

    const handlePostReply = async (e) => {
        e.preventDefault()
        if (!replyText.trim()) return

        try {
            const newComment = await postReviewComment(review.id, replyText.trim(), user.id)
            setComments(prev => [...prev, newComment])
            setReplyText('')
            setReplying(false)
            setShowComments(true) // Ensure open
        } catch (err) {
            console.error(err)
        }
    }

    const renderStars = (rating) => {
        return (
            <div className="review-rating-display">
                {[1, 2, 3, 4, 5].map(star => (
                    <span
                        key={star}
                        className={`review-star ${star <= rating ? 'filled' : ''}`}
                    >
                        ★
                    </span>
                ))}
            </div>
        )
    }

    if (isDeleting) return null // Or a spinner/fading out

    return (
        <div className="review-card">
            <div className="review-card-header">
                <div className="review-user-block">
                    {review.profiles ? (
                        <Link to={`/profile/${review.profiles.username}`}>
                            {review.profiles.avatar_url
                                ? <img src={review.profiles.avatar_url} alt={review.profiles.username} className="review-author-avatar" />
                                : <DefaultAvatar accent={review.profiles.theme_color} className="review-author-avatar" />}
                        </Link>
                    ) : (
                        <DefaultAvatar className="review-author-avatar" />
                    )}
                    <div className="review-meta-text">
                        <span className="review-author-name">
                            {review.profiles?.display_name || 'Usuario'}
                        </span>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.8rem' }}>
                            {isOwner && (
                                <div className="review-owner-actions" style={{ display: 'flex', gap: '0.5rem', fontSize: '0.85rem' }}>
                                    <button
                                        onClick={() => onEdit && onEdit(review)}
                                        style={{ background: 'none', border: 'none', color: 'var(--text-secondary)', cursor: 'pointer', textDecoration: 'underline' }}
                                    >
                                        Editar
                                    </button>
                                    <button
                                        onClick={handleDelete}
                                        style={{ background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', textDecoration: 'underline' }}
                                    >
                                        Borrar
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                <div className="review-card-rating-meta">
                    <time className="review-date" dateTime={review.created_at}>
                        {formatRelativeDate(review.created_at)}
                    </time>
                    {renderStars(review.rating)}
                </div>
            </div>

            {review.title && <h3 className="review-title">{review.title}</h3>}

            <div className="review-body">
                <div className={!showSpoiler ? 'review-spoiler-blur' : ''}>
                    {review.content}
                </div>

                {!showSpoiler && (
                    <button className="spoiler-reveal-btn" onClick={() => setShowSpoiler(true)}>
                        <img src="/icons/lupa.png" alt="👁️" style={{ width: '16px', height: '16px', verticalAlign: 'middle', marginRight: '6px' }} /> Ver Spoiler
                    </button>
                )}
            </div>

            <div className="review-actions-bar">
                <div
                    className={`reaction-chip ${currentReaction === 'good_point' ? 'active' : ''}`}
                    onClick={() => handleReaction('good_point')}
                >
                    👍 <span className="reaction-label">Buen punto</span>
                    {optimisticCounts.good_point > 0 && <span className="reaction-count">{optimisticCounts.good_point}</span>}
                </div>

                <div
                    className={`reaction-chip ${currentReaction === 'interesting' ? 'active' : ''}`}
                    onClick={() => handleReaction('interesting')}
                >
                    💡 <span className="reaction-label">Interesante</span>
                    {optimisticCounts.interesting > 0 && <span className="reaction-count">{optimisticCounts.interesting}</span>}
                </div>

                <div
                    className={`reaction-chip ${currentReaction === 'strong_opinion' ? 'active' : ''}`}
                    onClick={() => handleReaction('strong_opinion')}
                >
                    <img src="/icons/fire.gif" alt="🔥" style={{ width: '16px', height: '16px', verticalAlign: 'middle', marginRight: '4px' }} /> <span className="reaction-label">Opinión fuerte</span>
                    {optimisticCounts.strong_opinion > 0 && <span className="reaction-count">{optimisticCounts.strong_opinion}</span>}
                </div>

                <button className="reply-action-btn" onClick={handleLoadComments}>
                    <img src="/icons/dialog.png" alt="💬" style={{ width: '16px', height: '16px', verticalAlign: 'middle', marginRight: '6px' }} /> {comments.length > 0 ? `${comments.length} Respuestas` : 'Responder'}
                </button>
            </div>

            {/* Comments Section */}
            {showComments && (
                <div className="review-comments-container">
                    {comments.map(c => (
                        <div key={c.id} className="comment-bubble">
                            <div className="comment-header">
                                <Link to={`/profile/${c.profiles?.username}`} style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', textDecoration: 'none' }}>
                                    {c.profiles?.avatar_url
                                        ? <img src={c.profiles.avatar_url} alt="" className="comment-avatar" />
                                        : <DefaultAvatar accent={c.profiles?.theme_color} className="comment-avatar" />}
                                    <span className="comment-author-name">{c.profiles?.display_name}</span>
                                </Link>
                                <span style={{ opacity: 0.5, fontSize: '0.8rem' }}>
                                    {new Date(c.created_at).toLocaleDateString()}
                                </span>
                            </div>
                            <div className="comment-content">{c.content}</div>
                        </div>
                    ))}

                    {user && (
                        <div className="comment-input-wrapper">
                            <input
                                type="text"
                                className="modern-input"
                                placeholder="Escribe una respuesta..."
                                value={replyText}
                                onChange={e => setReplyText(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && handlePostReply(e)}
                            />
                            <button
                                className="btn-submit"
                                style={{ padding: '0.5rem 1rem', fontSize: '0.9rem' }}
                                onClick={handlePostReply}
                            >
                                Enviar
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    )
}

import { useState, useEffect } from 'react'
import { getReviews, getMyReactions } from '../../lib/reviewService'
import { useAuth } from '../../context/AuthContext'
import ReviewCard from './ReviewCard'
import ReviewForm from './ReviewForm'
import LoadingSpinner from '../LoadingSpinner'
import './Reviews.css'

export default function ReviewList({ workId, workType, refreshTrigger = 0, showWriteButton = true, onEditReview }) {
    const { user } = useAuth()
    const [reviews, setReviews] = useState([])
    const [loading, setLoading] = useState(false)
    const [sortBy, setSortBy] = useState('recent') // recent, rating_desc, reactions
    const [showForm, setShowForm] = useState(false)
    const [myReactions, setMyReactions] = useState({})
    const [page, setPage] = useState(0)
    const [hasMore, setHasMore] = useState(true)
    const LIMIT = 10

    useEffect(() => {
        // When sort or work changes, reset everything
        setPage(0)
        setHasMore(true)
        loadReviews(true)
    }, [workId, workType, sortBy, refreshTrigger])

    const loadReviews = async (reset = false) => {
        setLoading(true)
        try {
            const currentPage = reset ? 0 : page
            const data = await getReviews(workId, workType, sortBy, currentPage, LIMIT)

            if (data.length < LIMIT) {
                setHasMore(false)
            }

            if (reset) {
                setReviews(data || [])
            } else {
                setReviews(prev => [...prev, ...data])
            }

            // Also fetch my reactions if user is logged in
            if (user && data && data.length > 0) {
                const reactionMap = await getMyReactions(data.map(r => r.id), user.id)
                setMyReactions(prev => reset ? reactionMap : { ...prev, ...reactionMap })
            }
        } catch (err) {
            console.error(err)
        } finally {
            setLoading(false)
        }
    }

    const loadMore = async () => {
        if (loading || !hasMore) return
        const nextPage = page + 1
        setPage(nextPage) // Update UI state
        setLoading(true)

        try {
            const data = await getReviews(workId, workType, sortBy, nextPage, LIMIT)

            if (data.length < LIMIT) {
                setHasMore(false)
            }

            setReviews(prev => [...prev, ...data])

            if (user && data && data.length > 0) {
                const reactionMap = await getMyReactions(data.map(r => r.id), user.id)
                setMyReactions(prev => ({ ...prev, ...reactionMap }))
            }
        } catch (err) {
            console.error(err)
            setPage(prev => prev - 1) // Rollback on error
        } finally {
            setLoading(false)
        }
    }

    const handleReviewAdded = async () => {
        setPage(0)
        setHasMore(true)
        await loadReviews(true)
        window.scrollTo({ top: document.getElementById('reviews-anchor').offsetTop, behavior: 'smooth' })
    }

    // Deletions are handled by reloading data
    const handleReviewDeleted = async () => {
        setPage(0)
        setHasMore(true)
        await loadReviews(true)
    }

    // Callback to refresh reactions when user interacts
    const handleReactionUpdate = async () => {
        // Silently reload to ensure counts are accurate eventually?
    }

    return (
        <div id="reviews-anchor" className="reviews-section">
            <div className="reviews-header">
                <h2>Reseñas y Opiniones</h2>
                {user && showWriteButton && (
                    <button className="btn btn-primary" onClick={() => setShowForm(true)}>
                        ✎ Escribir Review
                    </button>
                )}
            </div>

            <div className="reviews-controls">
                <button
                    className={`sort-btn ${sortBy === 'recent' ? 'active' : ''}`}
                    onClick={() => setSortBy('recent')}
                >
                    Más recientes
                </button>
                <button
                    className={`sort-btn ${sortBy === 'rating_desc' ? 'active' : ''}`}
                    onClick={() => setSortBy('rating_desc')}
                >
                    Mejor valoradas
                </button>
                <button
                    className={`sort-btn ${sortBy === 'reactions' ? 'active' : ''}`}
                    onClick={() => setSortBy('reactions')}
                >
                    Más reacciones
                </button>
            </div>

            <div className="reviews-list-container">
                {reviews.length === 0 && !loading ? (
                    <div className="empty-state" style={{ padding: '2rem', textAlign: 'center', color: 'var(--text-muted)' }}>
                        <p>No hay reseñas todavía. ¡Sé el primero en opinar!</p>
                    </div>
                ) : (
                    <>
                        <div className="reviews-list">
                            {reviews.map(review => (
                                <ReviewCard
                                    key={review.id}
                                    review={review}
                                    myReaction={myReactions[review.id]}
                                    onReactionUpdate={handleReactionUpdate}
                                    onEdit={onEditReview}
                                    onDelete={handleReviewDeleted}
                                />
                            ))}
                        </div>

                        {hasMore && (
                            <div className="reviews-load-more" style={{ textAlign: 'center', marginTop: '1.5rem' }}>
                                <button
                                    className="btn btn-secondary"
                                    onClick={loadMore}
                                    disabled={loading}
                                >
                                    {loading ? 'Cargando...' : 'Cargar más reseñas'}
                                </button>
                            </div>
                        )}

                        {loading && reviews.length > 0 && (
                            <div style={{ margin: '1rem auto', display: 'flex', justifyContent: 'center' }}>
                                <LoadingSpinner />
                            </div>
                        )}
                    </>
                )}

                {loading && reviews.length === 0 && (
                    <div style={{ margin: '2rem auto', display: 'flex', justifyContent: 'center' }}>
                        <LoadingSpinner />
                    </div>
                )}
            </div>

            {showForm && (
                <ReviewForm
                    workId={workId}
                    workType={workType}
                    onClose={() => setShowForm(false)}
                    onReviewAdded={handleReviewAdded}
                />
            )}
        </div>
    )
}

import { createContext, useContext, useState, useEffect, useCallback } from 'react'
import { supabase } from '../lib/supabase'
import { invitationFromSearch, readInvitation, rememberInvitation, setInvitationFollow } from '../lib/invitations'

const AuthContext = createContext({})
const ACCOUNTS_KEY = 'geeksphere.saved-accounts'

function readSavedAccounts() {
    try { return JSON.parse(localStorage.getItem(ACCOUNTS_KEY) || '[]') } catch { return [] }
}

export const useAuth = () => useContext(AuthContext)

export function AuthProvider({ children }) {
    const [user, setUser] = useState(null)
    const [profile, setProfile] = useState(null)
    const [loading, setLoading] = useState(true)
    const [accounts, setAccounts] = useState(readSavedAccounts)

    const saveAccount = useCallback((session, accountProfile) => {
        if (!session?.user) return
        const entry = {
            id: session.user.id,
            email: session.user.email || '',
            session,
            profile: accountProfile || null,
        }
        setAccounts(previous => {
            const next = [entry, ...previous.filter(account => account.id !== entry.id)]
            localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(next))
            return next
        })
    }, [])

    const forgetSavedAccount = useCallback(accountId => {
        if (!accountId) return
        setAccounts(previous => {
            const next = previous.filter(account => account.id !== accountId)
            localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(next))
            return next
        })
    }, [])

    const rememberCurrentAccount = useCallback(async () => {
        const { data } = await supabase.auth.getSession()
        if (!data.session) return
        const { data: accountProfile, error } = await supabase.from('profiles').select('*').eq('id', data.session.user.id).maybeSingle()
        if (error) {
            console.warn('No se pudo comprobar si la cuenta terminó el onboarding:', error)
            return
        }
        if (accountProfile) saveAccount(data.session, accountProfile)
        else forgetSavedAccount(data.session.user.id)
    }, [saveAccount, forgetSavedAccount])

    const switchAccount = useCallback(async accountId => {
        const chosen = readSavedAccounts().find(account => account.id === accountId)
        if (!chosen?.session) throw new Error('No se encontró una sesión guardada para esa cuenta')
        await rememberCurrentAccount()
        const { error } = await supabase.auth.setSession({
            access_token: chosen.session.access_token,
            refresh_token: chosen.session.refresh_token,
        })
        if (error) throw error
        return chosen.profile || null
    }, [rememberCurrentAccount])

    const removeAccount = useCallback(async accountId => {
        const { data } = await supabase.auth.getSession()
        if (data.session?.user?.id === accountId) await supabase.auth.signOut()
        forgetSavedAccount(accountId)
    }, [forgetSavedAccount])

    useEffect(() => {
        const syncAccounts = event => {
            if (event.key === ACCOUNTS_KEY) setAccounts(readSavedAccounts())
        }
        window.addEventListener('storage', syncAccounts)
        return () => window.removeEventListener('storage', syncAccounts)
    }, [])

    useEffect(() => {
        // ONLY use onAuthStateChange - it handles INITIAL_SESSION automatically
        const { data: { subscription } } = supabase.auth.onAuthStateChange(
            async (event, session) => {
                console.log('🔔 Auth event:', event, session?.user?.id || 'no user')

                if (event === 'INITIAL_SESSION') {
                    // This is the first event - session from storage
                    if (session?.user) {
                        console.log('📦 Restored session for:', session.user.id)
                        setUser(session.user)
                        if (sessionStorage.getItem('geeksphere.add-account-pending') === '1') {
                            sessionStorage.removeItem('geeksphere.add-account-pending')
                            setTimeout(async () => {
                                const { data } = await supabase.from('profiles').select('*').eq('id', session.user.id).maybeSingle()
                                saveAccount(session, data)
                            }, 0)
                        }
                        // Use setTimeout to avoid Supabase deadlock
                        setTimeout(() => loadProfile(session.user.id), 0)
                    } else {
                        console.log('👻 No stored session')
                        setLoading(false)
                    }
                } else if (event === 'SIGNED_IN') {
                    console.log('✅ Signed in:', session.user.id)
                    setUser(session.user)
                    if (sessionStorage.getItem('geeksphere.add-account-pending') === '1') {
                        sessionStorage.removeItem('geeksphere.add-account-pending')
                        setTimeout(async () => {
                            const { data } = await supabase.from('profiles').select('*').eq('id', session.user.id).maybeSingle()
                            saveAccount(session, data)
                        }, 0)
                    }
                    setTimeout(() => loadProfile(session.user.id), 0)
                } else if (event === 'SIGNED_OUT') {
                    console.log('🚪 Signed out')
                    setUser(null)
                    setProfile(null)
                    setLoading(false)
                } else if (event === 'TOKEN_REFRESHED') {
                    console.log('🔄 Token refreshed')
                    // Just update user, don't reload profile
                    if (session?.user) {
                        setUser(session.user)
                        setAccounts(previous => {
                            const existing = previous.find(account => account.id === session.user.id)
                            if (!existing) return previous
                            const next = [{ ...existing, session }, ...previous.filter(account => account.id !== session.user.id)]
                            localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(next))
                            return next
                        })
                    }
                }
            }
        )

        return () => subscription.unsubscribe()
    }, [saveAccount])

    const loadProfile = async (userId) => {
        if (!userId) return null

        try {
            const { data, error } = await supabase
                .from('profiles')
                .select('*')
                .eq('id', userId)
                .maybeSingle()

            if (error) {
                console.error('❌ Profile error:', error)
                return null
            }

            if (data) {
                console.log('📋 Profile loaded:', data.username)
                setProfile(data)
            } else {
                console.log('👻 No profile found, user needs onboarding')
                setProfile(null)
            }
            return data
        } catch (err) {
            console.error('💥 loadProfile error:', err)
            return null
        } finally {
            setLoading(false)
        }
    }

    const signUp = async (email, password, username, invitation = readInvitation() || invitationFromSearch(window.location.search)) => {
        const normalizedEmail = email.trim()

        // Check if username is already taken
        const { data: existingUser } = await supabase
            .from('profiles')
            .select('username')
            .ilike('username', username)
            .maybeSingle()
            
        if (existingUser) {
            throw new Error('Ese nombre de usuario ya está cogido. ¡Prueba con otro!')
        }

        const { data, error } = await supabase.auth.signUp({
            email: normalizedEmail,
            password,
            options: {
                data: { username, ...(invitation ? { invitation_code: invitation.code, invitation_auto_follow: invitation.autoFollow !== false } : {}) },
                // Attribution is persisted by the signup trigger, including cross-browser confirmation.
                emailRedirectTo: `${window.location.origin}/confirm-email`
            }
        })

        if (error) {
            if (/already registered|already exists/i.test(error.message)) {
                throw new Error('Este correo ya está registrado. Inicia sesión o recupera tu contraseña.')
            }
            throw error
        }

        // Supabase hides whether an email exists when email confirmations are enabled.
        // In that case it returns a user with no identities instead of an error.
        if (data.user && Array.isArray(data.user.identities) && data.user.identities.length === 0) {
            throw new Error('Este correo ya está registrado. Inicia sesión o recupera tu contraseña.')
        }

        return data
    }

    const signIn = async (email, password) => {
        const { data, error } = await supabase.auth.signInWithPassword({
            email,
            password
        })

        if (error) throw error
        return data
    }

    const signInWithProvider = async (provider, { addAccount = false, invitation = readInvitation() || invitationFromSearch(window.location.search) } = {}) => {
        if (addAccount) sessionStorage.setItem('geeksphere.add-account-pending', '1')
        if (invitation) {
            rememberInvitation(invitation)
            setInvitationFollow(invitation.autoFollow)
            if (!readInvitation()) throw new Error('Tu navegador no permite guardar la invitación. Usa el registro con correo para conservararla o permite el almacenamiento del sitio.')
        }
        const { data, error } = await supabase.auth.signInWithOAuth({
            provider,
            options: {
                // Preserve the existing allowlisted callback URL; OAuth returns to this browser.
                redirectTo: `${window.location.origin}/onboarding`,
                scopes: provider === 'google' ? 'openid email profile' : undefined
            }
        })
        if (error) {
            throw error
        }
        return data
    }

    const resetPassword = async (email) => {
        const { error } = await supabase.auth.resetPasswordForEmail(email, {
            redirectTo: window.location.origin + '/update-password',
        })
        if (error) throw error
    }

    const signOut = async () => {
        const { data } = await supabase.auth.getSession()
        const currentUserId = data.session?.user?.id
        if (currentUserId) {
            const { data: accountProfile, error } = await supabase
                .from('profiles')
                .select('id')
                .eq('id', currentUserId)
                .maybeSingle()
            if (!error && !accountProfile) forgetSavedAccount(currentUserId)
            else if (error) console.warn('No se pudo comprobar el perfil antes de cerrar sesión:', error)
        }
        await supabase.auth.signOut()
    }

    const updateProfile = async (updates) => {
        if (!user) throw new Error('No user')

        const { data, error } = await supabase
            .from('profiles')
            .update(updates)
            .eq('id', user.id)
            .select()
            .single()

        if (error) throw error
        setProfile(data)
        return data
    }

    return (
        <AuthContext.Provider value={{
            supabase,
            user,
            profile,
            loading,
            signUp,
            signIn,
            signInWithProvider,
            signOut,
            resetPassword,
            updateProfile,
            refreshProfile: () => loadProfile(user?.id),
            accounts,
            rememberCurrentAccount,
            switchAccount,
            removeAccount,
            saveAccount
        }}>
            {children}
        </AuthContext.Provider>
    )
}

export function getAccentTextColor(color) {
    const hexMatch = /^#([\da-f]{3}|[\da-f]{6})$/i.exec(color || '')
    let channels = null

    if (hexMatch) {
        const hex = hexMatch[1].length === 3
            ? [...hexMatch[1]].map(channel => parseInt(channel + channel, 16))
            : [0, 2, 4].map(index => parseInt(hexMatch[1].slice(index, index + 2), 16))
        channels = hex.map(channel => channel / 255)
    } else {
        const rgbMatch = /^rgba?\(([^)]+)\)$/i.exec(color || '')
        if (rgbMatch) {
            channels = rgbMatch[1].split(/[\s,\/]+/).slice(0, 3).map(channel => {
                const value = parseFloat(channel)
                return channel.includes('%') ? value / 100 : value / 255
            })
        }
    }

    if (!channels || channels.length !== 3 || channels.some(channel => !Number.isFinite(channel))) return '#000'
    const luminance = channels.reduce((total, channel, index) => {
        const linear = channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4
        return total + linear * [0.2126, 0.7152, 0.0722][index]
    }, 0)
    return luminance > 0.179 ? '#000' : '#fff'
}

function parseRgb(color) {
    const hexMatch = /^#([\da-f]{3}|[\da-f]{6})$/i.exec(color || '')
    if (hexMatch) {
        const hex = hexMatch[1].length === 3
            ? [...hexMatch[1]].map(channel => parseInt(channel + channel, 16))
            : [0, 2, 4].map(index => parseInt(hexMatch[1].slice(index, index + 2), 16))
        return hex
    }

    const rgbMatch = /^rgba?\(([^)]+)\)$/i.exec(color || '')
    if (!rgbMatch) return null
    const channels = rgbMatch[1].split(/[\s,\/]+/).slice(0, 3).map(channel => {
        const value = parseFloat(channel)
        return channel.includes('%') ? Math.round(value * 2.55) : Math.round(value)
    })
    return channels.length === 3 && channels.every(channel => Number.isFinite(channel) && channel >= 0 && channel <= 255)
        ? channels
        : null
}

function toHex([red, green, blue]) {
    return `#${[red, green, blue].map(channel => Math.round(channel).toString(16).padStart(2, '0')).join('')}`
}

function mixColors(first, second, amount) {
    return toHex(first.map((channel, index) => channel * (1 - amount) + second[index] * amount))
}

// Use an opaque sRGB color for both the page's top surface and Android chrome.
export function getSystemBarColor(accent) {
    return mixColors([16, 16, 20], parseRgb(accent) || [20, 184, 166], 0.08)
}

function contrastRatio(first, second) {
    const luminance = color => parseRgb(color).reduce((total, channel, index) => {
        const value = channel / 255
        const linear = value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4
        return total + linear * [0.2126, 0.7152, 0.0722][index]
    }, 0)
    const values = [luminance(first), luminance(second)].sort((a, b) => b - a)
    return (values[0] + 0.05) / (values[1] + 0.05)
}

function readableText(background) {
    const light = '#f2f3f4'
    const dark = '#08090a'
    return contrastRatio(light, background) >= contrastRatio(dark, background) ? light : dark
}

function readableTextAcross(backgrounds) {
    const light = '#f2f3f4'
    const dark = '#08090a'
    const lightMinimum = Math.min(...backgrounds.map(background => contrastRatio(light, background)))
    const darkMinimum = Math.min(...backgrounds.map(background => contrastRatio(dark, background)))
    return lightMinimum >= darkMinimum ? light : dark
}

function readableSecondaryText(backgrounds) {
    const preferred = parseRgb('#aab2b9')
    const white = parseRgb('#f2f3f4')
    for (let amount = 0.15; amount <= 1; amount += 0.05) {
        const candidate = mixColors(preferred, white, amount)
        if (backgrounds.every(background => contrastRatio(candidate, background) >= 4.5)) return candidate
    }
    return '#f2f3f4'
}

function readableProfileAccent(accent, backgrounds) {
    const existingVisible = getVisibleAccentColor(accent)
    if (parseRgb(existingVisible) && backgrounds.every(background => contrastRatio(existingVisible, background) >= 4.5)) {
        return existingVisible
    }
    const accentRgb = parseRgb(accent)
    const white = [255, 255, 255]
    for (let amount = 0.08; amount <= 1; amount += 0.04) {
        const candidate = mixColors(accentRgb, white, amount)
        if (backgrounds.every(background => contrastRatio(candidate, background) >= 4.5)) return candidate
    }
    return '#ffffff'
}

// Palette is scoped by the caller to the profile page. Blend the two identity
// colors first, then keep the result close to the app's dark canvas.
export function getProfilePalette(bannerColor, accentColor) {
    const accent = parseRgb(accentColor || '') ? accentColor : '#14b8a6'
    const accentRgb = parseRgb(accent)
    const bannerChannels = (Array.isArray(bannerColor) ? bannerColor : [bannerColor])
        .map(color => parseRgb(color || ''))
        .filter(Boolean)
    const bannerRgb = bannerChannels.length
        ? bannerChannels[0].map((_, index) => Math.round(bannerChannels.reduce((sum, channels) => sum + channels[index], 0) / bannerChannels.length))
        : parseRgb(accent)
    const identity = mixColors(bannerRgb, accentRgb, 0.5)
    const identityRgb = parseRgb(identity)
    const canvas = mixColors([8, 8, 8], identityRgb, 0.19)
    const canvasRgb = parseRgb(canvas)
    const surface = mixColors(canvasRgb, identityRgb, 0.16)
    const raised = mixColors(canvasRgb, identityRgb, 0.25)
    const accentSurface = mixColors(parseRgb('#101313'), accentRgb, 0.34)
    const bannerSecondary = bannerChannels[1] || bannerRgb
    const bannerTint = mixColors(canvasRgb, bannerSecondary, 0.2)
    const bannerGlow = mixColors(canvasRgb, parseRgb(bannerTint), 0.58)
    const accentHover = mixColors(accentRgb, [255, 255, 255], 0.12)
    const profileBackgrounds = [canvas, bannerGlow, surface, raised, accentSurface]
    const profileAccentVisible = readableProfileAccent(accent, profileBackgrounds)

    return {
        '--profile-accent-color': accent,
        '--profile-accent-hover': accentHover,
        '--profile-accent-dark': mixColors(accentRgb, [0, 0, 0], 0.22),
        '--profile-theme-color': accent,
        '--profile-accent-visible': profileAccentVisible,
        '--profile-accent-text': getAccentTextColor(accent),
        '--profile-accent-hover-text': readableText(accentHover),
        '--profile-page-bg': canvas,
        '--profile-banner-tint': bannerTint,
        '--profile-surface': surface,
        '--profile-surface-raised': raised,
        '--profile-accent-surface': accentSurface,
        '--profile-page-text': readableTextAcross([canvas, bannerGlow, accentSurface]),
        '--profile-surface-text': readableText(surface),
        '--profile-raised-text': readableText(raised),
        '--profile-accent-surface-text': readableText(accentSurface),
        '--profile-secondary-text': readableSecondaryText(profileBackgrounds),
        '--profile-page-border': mixColors(canvasRgb, accentRgb, 0.34),
        '--profile-shadow-tint': mixColors(canvasRgb, accentRgb, 0.22)
    }
}

export function getVisibleAccentColor(color) {
    const accent = color || '#14b8a6'
    return getAccentTextColor(accent) === '#fff'
        ? `color-mix(in srgb, ${accent} 80%, #fff)`
        : accent
}

