                                >
                                    {sending ? 'Enviando...' : 'Enviar solicitud'}
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    )
}

import { useEffect, useRef, useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import SEO from '../components/SEO'
import './Auth.css'

export default function ConfirmEmail() {
    const { supabase, loading, saveAccount, user } = useAuth()
    const navigate = useNavigate()
    const [continuing, setContinuing] = useState(false)
    const [error, setError] = useState('')
    const autoContinueStarted = useRef(false)

    const handleContinue = async () => {
        if (loading || continuing) return
        setContinuing(true)
        setError('')
        try {
            const { data: { user }, error: sessionError } = await supabase.auth.getUser()
            if (sessionError || !user) throw new Error('No encontramos una sesión iniciada para la cuenta confirmada. Abre el enlace del correo en este navegador.')

            const pendingEmail = sessionStorage.getItem('geeksphere.pending-signup-email')
            if (pendingEmail && pendingEmail !== user.email?.toLowerCase()) {
                throw new Error('La sesión activa pertenece a otra cuenta. Abre el enlace de confirmación en este navegador para continuar con la cuenta nueva.')
            }
            if (!user.email_confirmed_at && !user.confirmed_at) {
                throw new Error('Primero confirma tu correo desde el enlace que te enviamos.')
            }

            const { data: profile, error: profileError } = await supabase
                .from('profiles')
                .select('id, username')
                .eq('id', user.id)
                .maybeSingle()
            if (profileError) throw profileError

            const { data: { session } } = await supabase.auth.getSession()
            if (session?.user?.id === user.id) saveAccount(session, profile)

            sessionStorage.removeItem('geeksphere.pending-signup-email')
            sessionStorage.removeItem('geeksphere.add-account-pending')
            if (!profile) navigate('/onboarding', { replace: true })
            else navigate(profile.username ? `/profile/${encodeURIComponent(profile.username)}` : '/home', { replace: true })
        } catch (err) {
            setError(err.message || 'No se pudo continuar. Inténtalo de nuevo.')
            setContinuing(false)
        }
    }

    useEffect(() => {
        if (loading || !user || (!user.email_confirmed_at && !user.confirmed_at) || autoContinueStarted.current) return
        autoContinueStarted.current = true
        handleContinue()
    }, [loading, user?.id])

    return (
        <div className="auth-page auth-register-page auth-flow-page">
            <SEO title="Confirma tu correo" description="Confirma tu cuenta de GeekSphere." />
            <div className="register-composition">
                <header className="register-hero">
                    <Link to="/home" className="register-mark" aria-label="Volver a GeekSphere"><img src="/icons/logo.png" alt="" /></Link>
                    <h1>Tu esfera de gustos,<br /><span>en un solo lugar.</span></h1>
                </header>

                <section className="register-form-section auth-flow-section" aria-labelledby="confirm-email-title">
                    <span className="auth-flow-success-icon auth-flow-mail-icon" aria-hidden="true">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/></svg>
                    </span>
                    <div className="auth-form-heading register-heading">
                        <h2 id="confirm-email-title">Confirma tu correo</h2>
                        <p>Te hemos enviado un enlace para confirmar tu cuenta y empezar a usar GeekSphere.</p>
                    </div>

                    <p className="auth-flow-note"><strong>¿No encuentras el correo?</strong> Mira en spam o correo no deseado. Si aún no llega, espera unos minutos.</p>
                    {error && <div className="auth-error" role="alert">{error}</div>}
                    <button type="button" className="auth-submit" onClick={handleContinue} disabled={loading || continuing}>{loading ? 'Comprobando sesión…' : continuing ? 'Continuando…' : 'Ya lo he confirmado'}</button>
                    {!loading && !continuing && <div className="auth-card-footer"><span>¿No tienes una sesión confirmada?</span><Link to="/login">Inicia sesión</Link></div>}
                </section>
            </div>
        </div>
    )
}

import { createPostgresChannel } from '../lib/postgresChannel'
import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import DefaultAvatar from '../components/DefaultAvatar'
import {
    getPendingRequests,
    getConnections,
    respondToRequest
} from '../lib/socialDiscoveryService'
import { supabase } from '../lib/supabase'
import LoadingSpinner from '../components/LoadingSpinner'
import './Connections.css'

export default function Connections() {
    const { user } = useAuth()
    const [pendingRequests, setPendingRequests] = useState([])
    const [connections, setConnections] = useState([])
    const [loading, setLoading] = useState(true)
    const [activeTab, setActiveTab] = useState('connections') // 'connections' | 'requests'

    useEffect(() => {
        if (user) {
            loadData()

            // Subscribe to new requests
            const channel = createPostgresChannel(supabase, `requests:${user.id}`)
                .on(
                    'postgres_changes',
                    {
                        event: 'INSERT',
                        schema: 'public',
                        table: 'connection_requests',
                        filter: `target_id=eq.${user.id}`
                    },
                    (payload) => {
                        console.log('New request!', payload)
                        loadData() // Reload to get full details
                    }
                )
                .subscribe()

            return () => {
                supabase.removeChannel(channel)
            }
        }
    }, [user])

    const loadData = async () => {
        try {
            setLoading(true)
            const [requests, conns] = await Promise.all([
                getPendingRequests(user.id),
                getConnections(user.id)
            ])
            setPendingRequests(requests)
            setConnections(conns)

            // Auto switch tab if requests exist and no connections
            if (requests.length > 0 && conns.length === 0) {
                setActiveTab('requests')
            }
        } catch (error) {
            console.error('Error loading connections:', error)
        } finally {
            setLoading(false)
        }
    }

    const handleRespond = async (requestId, accept) => {
        try {
            await respondToRequest(requestId, accept)

            // Update UI optimistically
            setPendingRequests(prev => prev.filter(r => r.id !== requestId))

            if (accept) {
                // Ideally reload connections to get the new one
                loadData()
            }
        } catch (error) {
            console.error('Error responding:', error)
            alert('Error al procesar la solicitud')
        }
    }

    if (loading) {
        return <div className="connections-loading"><LoadingSpinner /></div>
    }

    return (
        <div className="connections-page">
            <div className="container">
                <header className="connections-header">
                    <h1 className="page-title">Conexiones</h1>

                    <div className="tabs">
                        <button
                            className={`tab-btn ${activeTab === 'connections' ? 'active' : ''}`}
                            onClick={() => setActiveTab('connections')}
                        >
                            👥 Mis Conexiones ({connections.length})
                        </button>
                        <button
                            className={`tab-btn ${activeTab === 'requests' ? 'active' : ''}`}
                            onClick={() => setActiveTab('requests')}
                        >
                            📬 Solicitudes
                            {pendingRequests.length > 0 && (
                                <span className="badge-count">{pendingRequests.length}</span>
                            )}
                        </button>
                    </div>
                </header>

                {activeTab === 'requests' && (
                    <div className="requests-list">
                        {pendingRequests.length === 0 ? (
                            <div className="empty-state">
                                <p>No tienes solicitudes pendientes.</p>
                                <Link to="/discover" className="btn btn-primary btn-sm">Descubrir personas</Link>
                            </div>
                        ) : (
                            pendingRequests.map(request => (
                                <div key={request.id} className="request-card">
                                    <div className="request-user-info">
                                        <div className="request-avatar">
                                            {request.requester.avatar_url ? (
                                                <img src={request.requester.avatar_url} alt="" />
                                            ) : <DefaultAvatar accent={request.requester.theme_color} />}
                                        </div>
                                        <div className="request-details">
                                            <h3>{request.requester.display_name}</h3>
                                            <div className="affinity-badge-small">
                                                {request.affinity_score}% Afinidad
                                            </div>
                                            {request.message && (
                                                <div className="request-message">
                                                    "{request.message}"
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    {/* Snapshot of common works */}
                                    {request.common_works_snapshot?.length > 0 && (
                                        <div className="request-common-works">
                                            <span>En común:</span>
                                            <div className="works-mini-list">
                                                {request.common_works_snapshot.slice(0, 3).map((w, i) => (
                                                    <span key={i} className="work-chip">{w.name}</span>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    <div className="request-actions">
                                        <button
                                            className="btn btn-secondary btn-sm"
                                            onClick={() => handleRespond(request.id, false)}
                                        >
                                            Rechazar
                                        </button>
                                        <button
                                            className="btn btn-primary btn-sm"
                                            onClick={() => handleRespond(request.id, true)}
                                        >
                                            Aceptar
                                        </button>
                                        <Link to={`/compare/${request.requester.user_id}`} className="btn btn-ghost btn-sm">
                                            Ver Perfil
                                        </Link>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                )}

                {activeTab === 'connections' && (
                    <div className="connections-grid">
                        {connections.length === 0 ? (
                            <div className="empty-state">
                                <p>Aún no tienes conexiones.</p>
                                <p className="empty-subtitle">¡Busca personas con gustos similares en Descubrir!</p>
                                <Link to="/discover" className="btn btn-primary">Ir a Descubrir</Link>
                            </div>
                        ) : (
                            connections.map(conn => (
                                <Link key={conn.id} to={`/chat/${conn.id}`} className="connection-card">
                                    <div className="connection-avatar">
                                        {conn.otherUser?.avatar_url ? (
                                            <img src={conn.otherUser.avatar_url} alt="" />
                                        ) : <DefaultAvatar accent={conn.otherUser?.theme_color} />}
                                    </div>
                                    <div className="connection-info">
                                        <h3>{conn.otherUser?.display_name}</h3>
                                        <span className="connection-status">@{conn.otherUser?.username}</span>
                                        <div className="connection-meta">
                                            <span className="affinity-text"><img src="/icons/star.png" alt="✨" style={{ width: '14px', height: '14px', verticalAlign: 'middle', marginRight: '4px' }} /> {conn.affinity_score}% Afinidad</span>
                                        </div>
                                    </div>
                                    <div className="connection-action">
                                        <img src="/icons/dialog.png" alt="💬" style={{ width: '20px', height: '20px', opacity: 0.7 }} />
                                    </div>
                                </Link>
                            ))
                        )}
                    </div>
                )}
            </div>
        </div>
    )
}

