export default function CreateTierlist() {
    const { user } = useAuth()
    const navigate = useNavigate()
    const { id } = useParams()

    const [activeTemplate, setActiveTemplate] = useState('tierlist')
    const [title, setTitle] = useState('')
    const [description, setDescription] = useState('')
    const [visibility, setVisibility] = useState('public')
    const [mediaType, setMediaType] = useState('game')
    const [parentId, setParentId] = useState(null)
    const [activeItem, setActiveItem] = useState(null)

    const [tiers, setTiers] = useState({ pool: [] })

    useEffect(() => {
        const searchParams = new URLSearchParams(window.location.search)
        const forkId = searchParams.get('fork')

        if (id) {
            fetchTierlist(id, false)
        } else if (forkId) {
            fetchTierlist(forkId, true)
        }
    }, [id])

    const fetchTierlist = async (tierlistId, isFork = false) => {
        try {
            const { data, error } = await supabase
                .from('tierlists')
                .select(`
                    *,
                    tierlist_items (*)
                `)
                .eq('id', tierlistId)
                .single()

            if (error) throw error

            if (isFork) {
                setTitle(`Mi versión de ${data.title}`)
                setDescription('')
                setVisibility('public')
                setActiveTemplate(data.list_type || 'tierlist')
                setMediaType(data.media_type || 'game')
                setParentId(tierlistId)

                const poolItems = []

                if (data.content && Object.keys(data.content).length > 0) {
                    Object.values(data.content).flat().forEach(item => {
                        if (!poolItems.some(i => i.id === item.id)) {
                            poolItems.push({ ...item })
                        }
                    })
                } else {
                    (data.tierlist_items || []).forEach(item => {
                        const game = {
                            id: item.media_id,
                            name: item.title,
                            image_url: item.image_url,
                            genres: Array.isArray(item.tags) ? item.tags.join(', ') : (item.tags || '')
                        }
                        if (!poolItems.some(i => i.id === game.id)) {
                            poolItems.push(game)
                        }
                    })
                }

                const initialTiers = { pool: poolItems }
                TEMPLATES[data.list_type || 'tierlist'].rows.forEach(row => {
                    initialTiers[row] = []
                })
                setTiers(initialTiers)

            } else {
                setTitle(data.title)
                setDescription(data.description || '')
                setVisibility(data.visibility)
                setActiveTemplate(data.list_type || 'tierlist')
                setMediaType(data.media_type || 'game')
                setParentId(data.parent_id)

                if (data.content && Object.keys(data.content).length > 0) {
                    setTiers(data.content)
                } else {
                    const loadedTiers = { pool: [] }
                    TEMPLATES[data.list_type || 'tierlist'].rows.forEach(row => { loadedTiers[row] = [] })
                    const sortedItems = (data.tierlist_items || []).sort((a, b) => a.position - b.position)

                    sortedItems.forEach(item => {
                        const game = {
                            id: item.media_id,
                            name: item.title,
                            image_url: item.image_url,
                            genres: Array.isArray(item.tags) ? item.tags.join(', ') : (item.tags || '')
                        }

                        if (loadedTiers[item.tier]) {
                            loadedTiers[item.tier].push(game)
                        } else {
                            loadedTiers.pool.push(game)
                        }
                    })
                    setTiers(loadedTiers)
                }
            }
        } catch (error) {
            console.error('Error loading tierlist:', error)
            setError('Error al cargar la tierlist')
        }
    }

    useEffect(() => {
        if (!id && !tiers.pool?.length && !window.location.search.includes('fork')) {
            const initialTiers = { pool: tiers.pool || [] }
            TEMPLATES[activeTemplate].rows.forEach(row => {
                initialTiers[row] = tiers[row] || []
            })
            setTiers(initialTiers)
        } else if (!id && !window.location.search.includes('fork')) {
            setTiers(prev => {
                const newTiers = { pool: prev.pool }
                TEMPLATES[activeTemplate].rows.forEach(r => newTiers[r] = prev[r] || [])
                return newTiers
            })
        }
    }, [activeTemplate])

    useEffect(() => {
        setSearchQuery('')
        setSearchResults([])
        setIsSearching(false)
    }, [mediaType])

    const [searchQuery, setSearchQuery] = useState('')
    const [searchResults, setSearchResults] = useState([])
    const [isSearching, setIsSearching] = useState(false)

    const [saving, setSaving] = useState(false)
    const [error, setError] = useState('')

    const sensors = useSensors(
        useSensor(PointerSensor, {
            activationConstraint: {
                distance: 3,
            },
        })
    )

    useEffect(() => {
        const timeoutId = setTimeout(async () => {
            if (searchQuery.trim().length >= 3) {
                setIsSearching(true)
                let results = []
                if (mediaType === 'game') {
                    results = await searchGames(searchQuery)
                } else {
                    results = await searchAnime(searchQuery)
                }
                setSearchResults(results)
                setIsSearching(false)
            } else {
                setSearchResults([])
            }
        }, 500)

        return () => clearTimeout(timeoutId)
    }, [searchQuery])

    const addToPool = (game) => {
        const exists = Object.values(tiers).flat().some(g => g.id === game.id)
        if (exists) return

        setTiers(prev => ({
            ...prev,
            pool: [...prev.pool, game]
        }))
    }

    const removeFromTier = (gameId) => {
        setTiers(prev => {
            const newTiers = { ...prev }
            const currentRows = [...TEMPLATES[activeTemplate].rows, 'pool']

            for (const row of currentRows) {
                if (prev[row]) {
                    newTiers[row] = prev[row].filter(g => g.id !== gameId)
                }
            }
            return newTiers
        })
    }

    const findContainer = (id) => {
        if (id in tiers) {
            return id
        }
        return Object.keys(tiers).find((key) => tiers[key]?.some(g => g.id.toString() === id.toString()))
    }

    const handleDragOver = (event) => {
        const { active, over } = event
        const overId = over?.id
        const activeId = active.id.toString()

        if (!overId || active.id === overId) return

        const activeContainer = findContainer(activeId)
        const overContainer = findContainer(overId)

        if (!activeContainer || !overContainer) return

        if (activeContainer !== overContainer) {
            setTiers((prev) => {
                const activeItems = prev[activeContainer]
                const overItems = prev[overContainer]
                const activeIndex = activeItems.findIndex(g => g.id.toString() === activeId)
                const overIndex = prev[overContainer].some(g => g.id.toString() === overId.toString())
                    ? overItems.findIndex(g => g.id.toString() === overId.toString())
                    : overItems.length + 1

                let newIndex
                if (tiers[overContainer].find(g => g.id.toString() === overId.toString())) {
                    const overItemIndex = overItems.findIndex(g => g.id.toString() === overId.toString())
                    const isBelowOverItem =
                        over &&
                        active.rect.current.translated &&
                        active.rect.current.translated.top > over.rect.top + over.rect.height;

                    const modifier = isBelowOverItem ? 1 : 0;
                    newIndex = overItemIndex >= 0 ? overItemIndex + modifier : overItems.length + 1;
                } else {
                    newIndex = overItems.length + 1
                }

                return {
                    ...prev,
                    [activeContainer]: [
                        ...prev[activeContainer].filter((item) => item.id.toString() !== active.id.toString())
                    ],
                    [overContainer]: [
                        ...prev[overContainer].slice(0, newIndex),
                        activeItems[activeIndex],
                        ...prev[overContainer].slice(newIndex, prev[overContainer].length)
                    ]
                }
            })
        }
    }

    const handleDragEnd = (event) => {
        const { active, over } = event

        setActiveItem(null)

        if (!over) return

        const activeId = active.id.toString()
        const overId = over.id.toString()
        const currentRows = [...TEMPLATES[activeTemplate].rows, 'pool']

        let activeTier = null
        let activeGame = null
        for (const [tier, games] of Object.entries(tiers)) {
            if (!games) continue
            const game = games.find(g => g.id.toString() === activeId)
            if (game) {
                activeTier = tier
                activeGame = game
                break
            }
        }

        if (!activeGame || !activeTier) return

        if (currentRows.includes(overId)) {
            if (activeTier !== overId) {
                setTiers(prev => ({
                    ...prev,
                    [activeTier]: prev[activeTier].filter(g => g.id.toString() !== activeId),
                    [overId]: [...(prev[overId] || []), activeGame]
                }))
            }
            return
        }

        let overTier = null
        for (const [tier, games] of Object.entries(tiers)) {
            if (!games) continue
            if (games.find(g => g.id.toString() === overId)) {
                overTier = tier
                break
            }
        }

        if (overTier) {
            if (activeTier === overTier) {
                const oldIndex = tiers[overTier].findIndex(g => g.id.toString() === activeId)
                const newIndex = tiers[overTier].findIndex(g => g.id.toString() === overId)

                setTiers(prev => ({
                    ...prev,
                    [overTier]: arrayMove(prev[overTier], oldIndex, newIndex)
                }))
            } else {
                setTiers(prev => ({
                    ...prev,
                    [activeTier]: prev[activeTier].filter(g => g.id.toString() !== activeId),
                    [overTier]: [...(prev[overTier] || []), activeGame]
                }))
            }
        }
    }

    const handleSave = async () => {
        if (!title.trim()) {
            setError('El título es obligatorio')
            return
        }

        const totalItems = Object.values(tiers).flat().length
        if (totalItems === 0) {
            setError('Añade al menos un juego a la tierlist')
            return
        }

        setSaving(true)
        setError('')

        try {
            const content = { ...tiers }

            let tierlistId = id

            if (id) {
                const { error: updateError } = await supabase
                    .from('tierlists')
                    .update({
                        title,
                        description,
                        list_type: activeTemplate,
                        visibility,
                        content,
                        updated_at: new Date()
                    })
                    .eq('id', id)

                if (updateError) throw updateError
            } else {
                const { data: newTierlist, error: createError } = await supabase
                    .from('tierlists')
                    .insert({
                        user_id: user.id,
                        title,
                        description,
                        list_type: activeTemplate,
                        media_type: mediaType,
                        visibility,
                        parent_id: parentId,
                        content
                    })
                    .select()
                    .single()

                if (createError) throw createError
                tierlistId = newTierlist.id
            }

            navigate(`/tierlist/${tierlistId}`)
        } catch (err) {
            console.error('Error saving tierlist:', err)
            const errorMessage = err.message || (typeof err === 'object' ? JSON.stringify(err) : String(err))
            setError(`Error al guardar: ${errorMessage}`)
        } finally {
            setSaving(false)
        }
    }

    const getHighResImage = (url) => {
        if (!url) return null
        let finalUrl = url.startsWith('//') ? `https:${url}` : url
        return finalUrl.replace(/t_[a-z0-9_]+/, 't_cover_big')
    }

    const totalItems = Object.values(tiers).flat().length

    return (
        <div className="ctl-page">

            {/* ═══════════════════════════════
                STICKY EDITOR BAR
            ═══════════════════════════════ */}
            <div className="ctl-editor-bar">
                <div className="ctl-editor-inner">

                    {/* Back */}
                    <button type="button" className="editor-icon-back" aria-label="Volver" onClick={() => navigateBackOrHome(navigate)}>
                        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6" /></svg>
                    </button>

                    {/* Title input */}
                    <input
                        type="text"
                        className="ctl-title-input"
                        placeholder={`Título de ${TEMPLATES[activeTemplate].label.toLowerCase()}...`}
                        value={title}
                        onChange={(e) => setTitle(e.target.value)}
                        maxLength={100}
                    />

                    {/* Controls */}
                    <div className="ctl-bar-controls">
                        {/* Media type */}
                        {!id && (
                            <div className="ctl-toggle">
                                <button
                                    className={`ctl-toggle-opt ${mediaType === 'game' ? 'active' : ''}`}
                                    onClick={() => {
                                        if (Object.values(tiers).flat().length > 0) {
                                            if (window.confirm('Cambiar el tipo vaciará la lista. ¿Seguro?')) {
                                                setMediaType('game')
                                                setTiers({ pool: [] })
                                            }
                                        } else {
                                            setMediaType('game')
                                        }
                                    }}
                                >
                                    <img src="/icons/videogame.png" alt="" style={{ width: '13px', height: '13px' }} />
                                    <span>Juegos</span>
                                </button>
                                <button
                                    className={`ctl-toggle-opt ${mediaType === 'anime' ? 'active' : ''}`}
                                    onClick={() => {
                                        if (Object.values(tiers).flat().length > 0) {
                                            if (window.confirm('Cambiar el tipo vaciará la lista. ¿Seguro?')) {
                                                setMediaType('anime')
                                                setTiers({ pool: [] })
                                            }
                                        } else {
                                            setMediaType('anime')
                                        }
                                    }}
                                >
                                    <img src="/icons/anime.png" alt="" style={{ width: '13px', height: '13px' }} />
                                    <span>Anime</span>
                                </button>
                            </div>
                        )}

                        {/* Template */}
                        <div className="ctl-toggle">
                            {Object.values(TEMPLATES).map(template => (
                                <button
                                    key={template.id}
                                    className={`ctl-toggle-opt ${activeTemplate === template.id ? 'active' : ''}`}
                                    onClick={() => setActiveTemplate(template.id)}
                                >
                                    {template.label}
                                </button>
                            ))}
                        </div>

                        {/* Save */}
                        <button className="ctl-save-btn" onClick={handleSave} disabled={saving}>
                            {saving ? (
                                <>
                                    <div className="ctl-save-spinner" />
                                    <span>Guardando...</span>
                                </>
                            ) : (
                                <>
                                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                        <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z" />
                                        <polyline points="17 21 17 13 7 13 7 21" />
                                        <polyline points="7 3 7 8 15 8" />
                                    </svg>
                                    <span>Guardar</span>
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </div>

            {/* ═══════════════════════════════
                DESCRIPTION BAR
            ═══════════════════════════════ */}
            <div className="ctl-desc-bar">
                <div className="ctl-desc-inner">
                    <input
                        type="text"
                        className="ctl-desc-input"
                        placeholder="Añade una descripción breve (opcional)..."
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        maxLength={200}
                    />
                </div>
            </div>

            {/* Error */}
            {error && (
                <div className="ctl-error-bar">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <circle cx="12" cy="12" r="10" />
                        <line x1="12" y1="8" x2="12" y2="12" />
                        <line x1="12" y1="16" x2="12.01" y2="16" />
                    </svg>
                    {error}
                </div>
            )}

            {/* ═══════════════════════════════
                MAIN CONTENT
            ═══════════════════════════════ */}
            <div className="ctl-content">
                <div className="ctl-layout">

                    {/* ── LEFT: Tierlist Builder ── */}
                    <div className="ctl-builder">
                        <DndContext
                            sensors={sensors}
                            collisionDetection={pointerWithin}
                            onDragStart={(event) => {
                                const { active } = event
                                const activeId = active.id.toString()
                                const allItems = Object.values(tiers).flat()
                                const item = allItems.find(g => g.id.toString() === activeId)
                                setActiveItem(item)
                            }}
                            onDragOver={handleDragOver}
                            onDragEnd={handleDragEnd}
                            onDragCancel={() => setActiveItem(null)}
                        >
                            {/* Tier rows */}
                            <div className="ctl-tierlist">
                                {TEMPLATES[activeTemplate].rows.map(tier => (
                                    <div key={tier} className="tier-row">
                                        <div
                                            className="tier-label"
                                            id={tier}
                                            style={{
                                                backgroundColor: TEMPLATES[activeTemplate].colors[tier],
                                                fontSize: activeTemplate === 'ranking' ? '1.2rem' : undefined
                                            }}
                                        >
                                            {tier}
                                        </div>
                                        <SortableContext
                                            items={tiers[tier]?.map(g => g.id.toString()) || []}
                                            strategy={rectSortingStrategy}
                                        >
                                            <DroppableTier id={tier}>
                                                {tiers[tier]?.map(game => (
                                                    <SortableItem
                                                        key={game.id}
                                                        game={game}
                                                        onRemove={removeFromTier}
                                                    />
                                                ))}
                                                {(!tiers[tier] || tiers[tier].length === 0) && (
                                                    <div className="tier-placeholder">Arrastra aquí</div>
                                                )}
                                            </DroppableTier>
                                        </SortableContext>
                                    </div>
                                ))}
                            </div>

                            {/* Pool — separated */}
                            <div className="ctl-pool">
                                <div className="ctl-pool-header">
                                    <span className="ctl-pool-label">
                                        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                            <rect x="3" y="3" width="18" height="18" rx="2" /><path d="M9 9h6M9 12h6M9 15h4" />
                                        </svg>
                                        Sin clasificar
                                    </span>
                                    {tiers.pool?.length > 0 && (
                                        <span className="ctl-pool-count">{tiers.pool.length}</span>
                                    )}
                                </div>
                                <SortableContext
                                    items={tiers.pool?.map(g => g.id.toString()) || []}
                                    strategy={rectSortingStrategy}
                                >
                                    <DroppableTier id="pool">
                                        {tiers.pool?.map(game => (
                                            <SortableItem
                                                key={game.id}
                                                game={game}
                                                onRemove={removeFromTier}
                                            />
                                        ))}
                                        {(!tiers.pool || tiers.pool.length === 0) && (
                                            <div className="tier-placeholder">
                                                Busca y añade elementos — luego arrástralos a los tiers
                                            </div>
                                        )}
                                    </DroppableTier>
                                </SortableContext>
                            </div>

                            <DragOverlay>
                                {activeItem ? (
                                    <div className="tier-item dragging-preview">
                                        {(activeItem.image_url || activeItem.cover_url) ? (
                                            <img
                                                src={activeItem.image_url || activeItem.cover_url}
                                                alt={activeItem.name}
                                                className="tier-item-img"
                                                draggable={false}
                                            />
                                        ) : (
                                            <span className="tier-item-emoji">
                                                <img src="/icons/videogame.png" alt="🎮" style={{ width: '32px', height: '32px' }} draggable={false} />
                                            </span>
                                        )}
                                    </div>
                                ) : null}
                            </DragOverlay>
                        </DndContext>
                    </div>

                    {/* ── RIGHT: Search Panel ── */}
                    <div className="ctl-search-panel">
                        <div className="ctl-panel-header">
                            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                <line x1="12" y1="5" x2="12" y2="19" /><line x1="5" y1="12" x2="19" y2="12" />
                            </svg>
                            <span>Añadir {mediaType === 'anime' ? 'Anime' : 'Juegos'}</span>
                            {totalItems > 0 && (
                                <span className="ctl-panel-count">{totalItems} añadidos</span>
                            )}
                        </div>

                        <div className="ctl-search-wrap">
                            <svg className="ctl-search-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                <circle cx="11" cy="11" r="8" /><path d="m21 21-4.35-4.35" />
                            </svg>
                            <input
                                type="text"
                                className="ctl-search-input"
                                placeholder={mediaType === 'anime' ? 'Naruto, One Piece...' : 'Elden Ring, Zelda...'}
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                            />
                            {isSearching && <div className="ctl-spinner" />}
                        </div>

                        <div className="ctl-results">
                            {searchResults.map(game => {
                                const isAdded = Object.values(tiers).flat().some(g => g.id === game.id)
                                return (
                                    <button
                                        key={game.id}
                                        className={`ctl-result-item ${isAdded ? 'is-added' : ''}`}
                                        onClick={() => !isAdded && addToPool(game)}
                                        disabled={isAdded}
                                        title={game.name}
                                    >
                                        <div className="ctl-result-thumb">
                                            {(game.image_url || game.cover_url) ? (
                                                <img
                                                    src={getHighResImage(game.image_url || game.cover_url)}
                                                    alt={game.name}
                                                />
                                            ) : (
                                                <div className="ctl-result-fallback">
                                                    {mediaType === 'game'
                                                        ? <img src="/icons/videogame.png" alt="" style={{ width: '22px', height: '22px' }} />
                                                        : <img src="/icons/anime.png" alt="" style={{ width: '22px', height: '22px' }} />
                                                    }
                                                </div>
                                            )}
                                        </div>
                                        <div className="ctl-result-info">
                                            <span className="ctl-result-name">{game.name}</span>
                                            {game.release_date && (
                                                <span className="ctl-result-year">{game.release_date.substring(0, 4)}</span>
                                            )}
                                        </div>
                                        <div className={`ctl-result-btn ${isAdded ? 'added' : ''}`}>
                                            {isAdded ? (
                                                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                                    <polyline points="20 6 9 17 4 12" />
                                                </svg>
                                            ) : (
                                                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                                    <line x1="12" y1="5" x2="12" y2="19" /><line x1="5" y1="12" x2="19" y2="12" />
                                                </svg>
                                            )}
                                        </div>
                                    </button>
                                )
                            })}

                            {!isSearching && searchQuery.length >= 3 && searchResults.length === 0 && (
                                <div className="ctl-empty">
                                    <span className="ctl-empty-icon">🔍</span>
                                    <p>Sin resultados</p>
                                    <small>Prueba con otro nombre</small>
                                </div>
                            )}

                            {!searchQuery && (
                                <div className="ctl-empty">
                                    <span className="ctl-empty-icon">{mediaType === 'anime' ? '🎬' : '👾'}</span>
                                    <p>Busca para añadir</p>
                                    <small>Escribe al menos 3 caracteres</small>
                                </div>
                            )}
                        </div>
                    </div>

                </div>
            </div>
        </div>
    )
}

import React, { useEffect, useMemo, useState } from 'react'
import { createPortal } from 'react-dom'
import { Link } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import {
  createCustomItemGroup,
  getCustomItemGroups,
} from '../lib/customItemGroupService'
import { getUserTemplates } from '../lib/listService'
import './CustomItemGroups.css'

const isCustomTemplateItem = item => {
  const id = String(item?.id || '')
  return id.startsWith('custom-') || id.startsWith('custom_') || id.startsWith('group-') || Boolean(item?.source_group_id)
}
const getTemplateItems = template => (template?.default_items || []).filter(isCustomTemplateItem).map((item, index) => ({
  ...item,
  id: String(item.id || `custom-import-${template.id}-${index}`),
  name: item.name || item.title || `Elemento ${index + 1}`,
  image_url: item.image_url || item.cover_url || item.imageUrl || '',
  cover_url: item.cover_url || item.image_url || item.imageUrl || '',
}))
const getTemplateCoverUrls = template => (template?.cover_items?.length ? template.cover_items : template?.default_items || [])
  .map(item => typeof item === 'string' ? item : item?.image_url || item?.cover_url || item?.cover?.url)
  .filter(Boolean).slice(0, 4)

function GroupArtwork({ group }) {
  const items = group.items?.slice(0, 4) || []
  return <span className="groups-art" aria-hidden="true">
    {items.length ? items.map((item, index) => item.image_url || item.cover_url
      ? <img key={item.id || index} src={item.image_url || item.cover_url} alt="" loading="lazy" />
      : <i key={item.id || index}>{item.name?.slice(0, 1)?.toUpperCase()}</i>)
      : <span>{group.name?.slice(0, 1)?.toUpperCase() || 'G'}</span>}
  </span>
}

export default function CustomItemGroups() {
  const { user } = useAuth()
  const [groups, setGroups] = useState({ mine: [], public: [], saved: [] })
  const [query, setQuery] = useState('')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [createOpen, setCreateOpen] = useState(false)
  const [createDraft, setCreateDraft] = useState({ name: '', description: '', visibility: 'private', sourceTemplateId: '' })
  const [userTemplates, setUserTemplates] = useState([])
  const [templatesLoading, setTemplatesLoading] = useState(false)
  const [templatePickerOpen, setTemplatePickerOpen] = useState(false)
  const [templateQuery, setTemplateQuery] = useState('')
  const [creating, setCreating] = useState(false)

  const reload = async (showLoading = true) => {
    if (!user?.id) return
    if (showLoading) setLoading(true)
    try {
      setGroups(await getCustomItemGroups(user.id))
      setError('')
    } catch (loadError) {
      setError(loadError.message || 'No se pudieron cargar los grupos.')
    } finally { setLoading(false) }
  }

  useEffect(() => { reload() }, [user?.id])

  useEffect(() => {
    if (!createOpen) return undefined
    const closeOnEscape = event => {
      if (event.key !== 'Escape') return
      if (templatePickerOpen) setTemplatePickerOpen(false)
      else setCreateOpen(false)
    }
    document.addEventListener('keydown', closeOnEscape)
    return () => document.removeEventListener('keydown', closeOnEscape)
  }, [createOpen, templatePickerOpen])

  const publicGroups = useMemo(() => {
    const search = query.trim().toLocaleLowerCase()
    if (!search) return groups.public
    return groups.public.filter(group => [group.name, group.description, ...(group.items || []).map(item => item.name)]
      .some(value => value?.toLocaleLowerCase().includes(search)))
  }, [groups.public, query])
  const templatesWithItems = useMemo(() => userTemplates.filter(template => getTemplateItems(template).length > 0), [userTemplates])
  const filteredTemplates = useMemo(() => {
    const search = templateQuery.trim().toLocaleLowerCase()
    return search ? templatesWithItems.filter(template => template.title?.toLocaleLowerCase().includes(search)) : templatesWithItems
  }, [templatesWithItems, templateQuery])

  const openCreate = async () => {
    setCreateDraft({ name: '', description: '', visibility: 'private', sourceTemplateId: '' })
    setTemplateQuery('')
    setTemplatePickerOpen(false)
    setError('')
    setCreateOpen(true)
    setTemplatesLoading(true)
    try { setUserTemplates(await getUserTemplates(user.id)) }
    catch (loadError) { setError(loadError.message || 'No se pudieron cargar tus plantillas.') }
    finally { setTemplatesLoading(false) }
  }

  const createGroup = async event => {
    event.preventDefault()
    if (!createDraft.name.trim() || creating) return
    const sourceTemplate = userTemplates.find(template => String(template.id) === String(createDraft.sourceTemplateId))
    setCreating(true)
    setError('')
    try {
      await createCustomItemGroup({
        name: createDraft.name.trim(),
        description: createDraft.description.trim(),
        visibility: createDraft.visibility,
        items: sourceTemplate ? getTemplateItems(sourceTemplate) : [],
        owner_id: user.id,
      })
      setCreateOpen(false)
      setCreateDraft({ name: '', description: '', visibility: 'private', sourceTemplateId: '' })
      await reload(false)
    } catch (saveError) {
      setError(saveError.message || 'No se pudo crear el grupo.')
    } finally { setCreating(false) }
  }

  return <main className="custom-groups-page">
    <header className="custom-groups-header">
      <div>
        <h1>Tus grupos</h1>
        <p>Elementos que puedes reutilizar en tus plantillas.</p>
      </div>
      <button type="button" className="groups-create-button" onClick={openCreate}><span>＋</span> Crear grupo</button>
    </header>

    {error && !createOpen && <p className="groups-error" role="alert">{error}</p>}
    <section className="groups-owned-section" aria-label="Grupos creados por ti">
      {loading ? <p className="groups-empty">Cargando tus grupos…</p>
        : groups.mine.length ? <div className="groups-owned-grid">{groups.mine.map(group => <article className="groups-owned-tile" key={group.id}>
          <Link to={`/groups/${group.id}`} className="groups-owned-open" aria-label={`Abrir grupo ${group.name}`}><span className="groups-owned-artwork"><GroupArtwork group={group} /><span className={`groups-visibility ${group.visibility === 'public' ? 'is-public' : ''}`} role="img" aria-label={group.visibility === 'public' ? 'Público' : 'Privado'} title={group.visibility === 'public' ? 'Público' : 'Privado'}>{group.visibility === 'public' ? <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/></svg> : <svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 1 1 8 0v3"/></svg>}</span></span>
            <span className="groups-tile-copy"><strong>{group.name}</strong><small>{group.items?.length || 0} elementos</small></span>
          </Link>
        </article>)}</div>
          : <p className="groups-empty groups-owned-empty">Aún no has creado grupos. Crea uno para tener tus elementos a mano.</p>}
    </section>

    <section className="groups-public-section" aria-label="Explorar grupos" aria-live="polite">
      <div className="groups-discover-heading"><h2>Explorar</h2></div>
      <div className="groups-search-row">
        <label className="groups-search">
          <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="7.3"/><path d="m16.2 16.2 4.3 4.3"/></svg>
          <input type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar grupos..." aria-label="Buscar grupos" />
          {query && <button type="button" onClick={() => setQuery('')} aria-label="Borrar búsqueda">×</button>}
        </label>
      </div>
      {loading ? <p className="groups-empty">Cargando grupos…</p>
        : publicGroups.length ? <div className="groups-grid">{publicGroups.map(group => <article className="groups-public-tile" key={group.id}>
          <Link to={`/groups/${group.id}`} className="groups-public-open" aria-label={`Ver grupo ${group.name}`}>
            <GroupArtwork group={group} /><span className="groups-tile-copy"><strong>{group.name}</strong><small>{group.items?.length || 0} elementos</small></span>
          </Link>
        </article>)}</div>
          : <div className="groups-empty">{query ? 'No hay grupos públicos que coincidan con tu búsqueda.' : 'Todavía no hay grupos públicos.'}</div>}
    </section>

    {createOpen && createPortal(<div className="groups-create-overlay" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget && !creating) setCreateOpen(false) }}>
      <section className={`groups-create-dialog${templatePickerOpen ? ' is-template-picker' : ''}`} role="dialog" aria-modal="true" aria-labelledby="groups-create-title">
        <header className="groups-create-dialog-header">{templatePickerOpen && <button type="button" className="groups-create-back" onClick={() => setTemplatePickerOpen(false)} aria-label="Volver al formulario"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6" /></svg></button>}<h2 id="groups-create-title">{templatePickerOpen ? 'Importar desde una plantilla' : 'Crear grupo'}</h2><button type="button" onClick={() => { setCreateOpen(false); setTemplatePickerOpen(false) }} disabled={creating} aria-label="Cerrar">×</button></header>
        {!templatePickerOpen ? <form onSubmit={createGroup} className="groups-create-form">
          <label>Nombre<input autoFocus value={createDraft.name} onChange={event => setCreateDraft(current => ({ ...current, name: event.target.value }))} maxLength={80} placeholder="Ej.: Personajes de Mario Bros" required /></label>
          <label>Descripción<textarea value={createDraft.description} onChange={event => setCreateDraft(current => ({ ...current, description: event.target.value }))} maxLength={240} rows={3} placeholder="¿Qué tienen en común estos elementos?" /></label>
          <fieldset className="groups-visibility-field"><legend>Visibilidad</legend><div className={`groups-visibility-switch${createDraft.visibility === 'public' ? ' is-public' : ''}`} role="group" aria-label="Visibilidad del grupo"><button type="button" className={createDraft.visibility === 'private' ? 'active' : ''} aria-pressed={createDraft.visibility === 'private'} onClick={() => setCreateDraft(current => ({ ...current, visibility: 'private' }))}>Privado</button><button type="button" className={createDraft.visibility === 'public' ? 'active' : ''} aria-pressed={createDraft.visibility === 'public'} onClick={() => setCreateDraft(current => ({ ...current, visibility: 'public' }))}>Público</button></div></fieldset>
          <div className="groups-template-import"><span className="groups-import-label">Importar desde</span><button type="button" className="groups-template-trigger" onClick={() => { setTemplatePickerOpen(true); setTemplateQuery('') }}><span className="groups-template-plus">＋</span><span>{createDraft.sourceTemplateId ? userTemplates.find(template => String(template.id) === String(createDraft.sourceTemplateId))?.title : 'Añadir desde una plantilla'}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6" /></svg></button>{createDraft.sourceTemplateId && <small className="groups-create-hint">Se añadirán {getTemplateItems(userTemplates.find(template => String(template.id) === String(createDraft.sourceTemplateId))).length} elementos personalizados predefinidos.</small>}</div>
          {error && <p className="groups-error" role="alert">{error}</p>}
          <footer><button type="button" className="groups-create-cancel" onClick={() => setCreateOpen(false)} disabled={creating}>Cancelar</button><button type="submit" className="groups-create-submit" disabled={creating || !createDraft.name.trim()}>{creating ? 'Creando…' : 'Crear grupo'}</button></footer>
        </form> : <div className="groups-template-browse"><label className="groups-template-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="7.3"/><path d="m16.2 16.2 4.3 4.3"/></svg><input autoFocus type="search" value={templateQuery} onChange={event => setTemplateQuery(event.target.value)} placeholder="Buscar plantillas..." aria-label="Buscar tus plantillas" /></label><div className="groups-template-options" role="listbox" aria-label="Tus plantillas">{templatesLoading ? <p>Cargando plantillas…</p> : filteredTemplates.length ? <><button type="button" className="groups-template-none" role="option" aria-selected={!createDraft.sourceTemplateId} onClick={() => { setCreateDraft(current => ({ ...current, sourceTemplateId: '' })); setTemplatePickerOpen(false) }}>No importar elementos</button>{filteredTemplates.map(template => { const covers = getTemplateCoverUrls(template); return <button type="button" role="option" aria-selected={String(template.id) === String(createDraft.sourceTemplateId)} key={template.id} onClick={() => { setCreateDraft(current => ({ ...current, sourceTemplateId: String(template.id) })); setTemplatePickerOpen(false) }}><span className={`groups-template-option-art has-${covers.length}`} aria-hidden="true">{covers.length ? covers.map((cover, index) => <img key={`${cover}-${index}`} src={cover} alt="" loading="lazy" />) : <span>{template.title?.slice(0, 1)?.toUpperCase() || 'T'}</span>}</span><span className="groups-template-option-copy"><strong>{template.title || 'Plantilla sin título'}</strong><small>{getTemplateItems(template).length} elementos personalizados</small></span></button>})}</> : <p>{templatesWithItems.length ? 'No hay plantillas que coincidan.' : 'No tienes plantillas con elementos predefinidos.'}</p>}</div></div>}
      </section>
    </div>, document.body)}

  </main>
}

import { useState, useEffect, useCallback } from 'react'
import { Link } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import DefaultAvatar from '../components/DefaultAvatar'
import { supabase } from '../lib/supabase'
import { discoverSimilarUsers, calculateAffinityClient } from '../lib/socialDiscoveryService'
import { getRecommendations } from '../lib/recommendationService'
import { searchGames } from '../lib/gameService'
import { searchAnime } from '../lib/animeService'
import RecommendationCard from '../components/RecommendationCard'
import './Discover.css'

export default function Discover() {
    const { user, profile, refreshProfile } = useAuth()
    const [users, setUsers] = useState([])
    const [tierlists, setTierlists] = useState([])
    const [recommendations, setRecommendations] = useState([])
    const [searchResults, setSearchResults] = useState([])
    const [loading, setLoading] = useState(true)

    // UI State
    const [activeTab, setActiveTab] = useState('recommendations') // 'affinity' | 'tierlists' | 'recommendations'
    const [searchQuery, setSearchQuery] = useState('')
    const [debouncedQuery, setDebouncedQuery] = useState('')
    const [mediaFilter, setMediaFilter] = useState('game') // 'game' | 'anime' (Removed 'all')

    // Custom debounce since we might not have lodash
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedQuery(searchQuery)
        }, 500)

        return () => clearTimeout(timer)
    }, [searchQuery])

    useEffect(() => {
        if (user && profile) {
            // Only load data if strictly necessary (tab change or search)
            // Prevent reloading recommendations if they are already loaded
            if (activeTab === 'recommendations' && recommendations.length > 0 && !debouncedQuery && mediaFilter === 'all') {
                return
            }
            loadData()
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user, profile, activeTab, debouncedQuery, mediaFilter])

    const loadData = async () => {
        try {
            setLoading(true)

            // Always calculate recommendations in background (regardless of active tab)
            if (user && profile) {
                // Don't await if we want it truly background, but for now let's await to ensure consistency
                // or parallelize with other fetches
                const recsPromise = getRecommendations(user.id, profile, mediaFilter, { limit: 50 })
                    .then(recs => enrichRecommendations(recs))
                    .then(enriched => setRecommendations(enriched))
                    .catch(e => console.error('Background recs error:', e))

                // We won't await recsPromise here to let other data load faster, 
                // unless activeTab IS recommendations, but the user asked for "background context"
            }

            if (activeTab === 'affinity') {
                // Discover affine users
                const affineUsersList = await discoverSimilarUsers(user.id, profile)

                if (!affineUsersList) {
                    console.error('Error discovering affine users')
                } else {
                    // affineUsersList already has the structure we need

                    // Filter by search
                    if (debouncedQuery) {
                        const filtered = affineUsersList.filter(u =>
                            u.username?.toLowerCase().includes(debouncedQuery.toLowerCase()) ||
                            u.display_name?.toLowerCase().includes(debouncedQuery.toLowerCase())
                        )
                        setUsers(filtered)
                    } else {
                        setUsers(affineUsersList)
                    }
                }
            } else if (activeTab === 'recommendations') {
                // Check if user is searching
                if (debouncedQuery.trim().length > 0) {
                    // Global search for games/anime
                    await performGlobalSearch(debouncedQuery, mediaFilter)
                } else {
                    // Start calculation also here if not done, but the background one above handles it.
                    // If we want to ensure it's fresh/loaded:
                    if (recommendations.length === 0) {
                        const recs = await getRecommendations(user.id, profile, mediaFilter, { limit: 50 })
                        const enrichedRecs = await enrichRecommendations(recs)
                        setRecommendations(enrichedRecs)
                    }
                    setSearchResults([])
                }
            } else {
                // Get tierlists
                let query = supabase
                    .from('tierlists')
                    .select('*, likes_count')
                    .eq('visibility', 'public')
                    .order('created_at', { ascending: false })
                    .limit(50)

                if (debouncedQuery.trim().length > 0) {
                    query = query.ilike('title', `%${debouncedQuery}%`)
                }

                if (mediaFilter !== 'all') {
                    query = query.eq('media_type', mediaFilter)
                }

                const { data: rawTierlists, error: tierlistError } = await query

                if (tierlistError) console.error('Error fetching tierlists:', tierlistError)

                let enrichedTierlists = []
                if (rawTierlists && rawTierlists.length > 0) {
                    // Manually fetch profiles
                    const userIds = [...new Set(rawTierlists.map(t => t.user_id))]
                    const { data: profiles } = await supabase
                        .from('profiles')
                        .select('user_id, username, display_name, avatar_url, theme_color')
                        .in('user_id', userIds)

                    const profileMap = {}
                    profiles?.forEach(p => profileMap[p.user_id] = p)

                    enrichedTierlists = rawTierlists.map(t => ({
                        ...t,
                        profiles: profileMap[t.user_id]
                    }))
                }
                setTierlists(enrichedTierlists)
            }
        } catch (error) {
            console.error('Error:', error)
        } finally {
            setLoading(false)
        }
    }

    // Enrich recommendations with game/anime details
    const enrichRecommendations = async (recs) => {
        if (!recs || recs.length === 0) return []

        const gameIds = recs.filter(r => r.media_type === 'game' && !r.title).map(r => r.work_id)
        const animeIds = recs.filter(r => r.media_type === 'anime' && !r.title).map(r => r.work_id)

        const gamesMap = {}
        const animeMap = {}

        // Fetch games only if title is missing
        if (gameIds.length > 0) {
            const { data: games } = await supabase
                .from('games')
                .select('id, name, cover_url')
                .in('id', gameIds)

            games?.forEach(g => gamesMap[g.id] = g)
        }

        // Fetch anime only if title is missing
        if (animeIds.length > 0) {
            // Try matching by id OR mal_id to be safe
            const { data: anime } = await supabase
                .from('anime')
                .select('id, mal_id, title, image_url')
                .or(`id.in.(${animeIds.join(',')}),mal_id.in.(${animeIds.join(',')})`)

            anime?.forEach(a => {
                animeMap[a.id] = a
                if (a.mal_id) animeMap[a.mal_id] = a
            })
        }

        // Enrich each recommendation
        return recs.map(rec => {
            if (rec.media_type === 'game') {
                const gameData = gamesMap[rec.work_id]
                return {
                    ...rec,
                    title: rec.title || gameData?.name || 'Juego desconocido',
                    image_url: rec.image_url || gameData?.cover_url
                }
            } else {
                const animeData = animeMap[rec.work_id]
                return {
                    ...rec,
                    title: rec.title || animeData?.title || 'Anime desconocido',
                    image_url: rec.image_url || animeData?.image_url
                }
            }
        })
    }

    // Perform global search using APIs (IGDB/Jikan) with DB fallback
    const performGlobalSearch = async (query, mediaType) => {
        const results = []

        // Search games using gameService (IGDB API + DB)
        if (mediaType === 'game' || mediaType === 'all') {
            const games = await searchGames(query, 20)

            games.forEach(game => {
                results.push({
                    work_id: game.id,
                    media_type: 'game',
                    title: game.name,
                    image_url: game.cover_url || game.image_url,
                    score: null, // No score for search results
                    reasons: [{ type: 'search', icon: <img src="/icons/lupa.png" alt="🔍" style={{ width: '14px', height: '14px' }} />, text: 'Resultado de búsqueda' }]
                })
            })
        }

        // Search anime using animeService (Jikan API + DB)
        if (mediaType === 'anime' || mediaType === 'all') {
            const animeList = await searchAnime(query, 20)

            animeList.forEach(a => {
                results.push({
                    work_id: a.id,
                    media_type: 'anime',
                    title: a.title || a.name,
                    image_url: a.image_url || a.cover_url,
                    score: null, // No score for search results
                    reasons: [{ type: 'search', icon: <img src="/icons/lupa.png" alt="🔍" style={{ width: '14px', height: '14px' }} />, text: 'Resultado de búsqueda' }]
                })
            })
        }

        setSearchResults(results)
    }

    // Handle adding recommendation to library
    const handleAddToLibrary = async (recommendation, status = 'wishlist') => {
        if (!user || !profile) return

        try {
            const libraryKey = recommendation.media_type === 'game' ? 'library' : 'anime_library'
            const currentLibrary = profile[libraryKey] || []

            // Convert work_id to string for consistency
            const workId = String(recommendation.work_id)

            // Check if already exists
            const exists = currentLibrary.find(item => {
                const itemId = String(item.game_id || item.mal_id || item.id)
                return itemId === workId
            })

            if (exists) {
                alert('Este elemento ya está en tu biblioteca')
                return
            }

            const newEntry = {
                id: workId,
                [recommendation.media_type === 'game' ? 'game_id' : 'mal_id']: workId,
                title: recommendation.title,
                name: recommendation.title, // Add both title and name for compatibility
                image_url: recommendation.image_url,
                status: status,
                rating: null,
                added_at: new Date().toISOString()
            }

            const newLibrary = [...currentLibrary, newEntry]

            const { error } = await supabase
                .from('profiles')
                .update({ [libraryKey]: newLibrary })
                .eq('user_id', user.id)

            if (error) {
                console.error('Error adding to library:', error)
                alert('Error al añadir a la biblioteca')
            } else {
                // Remove from recommendations and search results
                setRecommendations(prev => prev.filter(r => String(r.work_id) !== workId))
                setSearchResults(prev => prev.filter(r => String(r.work_id) !== workId))

                // Refresh profile to update library
                if (refreshProfile) {
                    await refreshProfile()
                }

                // Show success message
                alert(`Añadido a tu ${recommendation.media_type === 'game' ? 'biblioteca de juegos' : 'biblioteca de anime'}`)
            }
        } catch (error) {
            console.error('Error in handleAddToLibrary:', error)
            alert('Error al añadir a la biblioteca')
        }
    }

    if (loading && users.length === 0 && tierlists.length === 0 && recommendations.length === 0 && searchResults.length === 0) {
        return (
            <div className="discover discover-loading" role="status" aria-busy="true" aria-label="Cargando contenido">
                <div className="container">
                    <div className="discover-header">
                        <div className="discover-skeleton discover-skeleton-title" />
                        <div className="discover-skeleton discover-skeleton-search" />
                    </div>
                    <div className="discover-skeleton-controls">
                        <div className="discover-skeleton discover-skeleton-tabs" />
                        <div className="discover-skeleton discover-skeleton-filters" />
                    </div>
                    <div className="discover-skeleton-grid" aria-hidden="true">
                        {Array.from({ length: 8 }, (_, index) => (
                            <div className="discover-skeleton-card" key={index}>
                                <div className="discover-skeleton discover-skeleton-poster" />
                                <div className="discover-skeleton discover-skeleton-line" />
                                <div className="discover-skeleton discover-skeleton-line short" />
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        )
    }

    return (
        <div className="discover">
            <div className="container">
                <div className="discover-header">
                    <h1 className="page-title">Descubrir</h1>

                    <div className="discover-actions-top">
                        <Link to="/connections" className="btn btn-secondary btn-sm">
                            📬 Solicitudes y Conexiones
                        </Link>
                    </div>

                    {/* Search Bar */}
                    <div className="search-bar">
                        {activeTab === 'recommendations' && <span className="search-hint">💡 Busca obras específicas o deja vacío para recomendaciones</span>}
                        <span className="search-icon"><img src="/icons/lupa.png" alt="🔍" style={{ width: '18px', height: '18px', opacity: 0.6 }} /></span>
                        <input
                            type="text"
                            placeholder={activeTab === 'affinity' ? "Buscar personas..." : activeTab === 'recommendations' ? "Buscar o dejar vacío para recomendaciones..." : "Buscar tierlists..."}
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                </div>

                <div className="discover-controls">
                    {/* Main Tabs */}
                    <div className="tabs input-group-segment">
                        <button
                            className={`tab-btn ${activeTab === 'tierlists' ? 'active' : ''}`}
                            onClick={() => setActiveTab('tierlists')}
                        >
                            <img src="/icons/checklist.png" alt="📋" style={{ width: '16px', height: '16px', verticalAlign: 'middle', marginRight: '6px' }} /> Tierlists
                        </button>
                        <button
                            className={`tab-btn ${activeTab === 'affinity' ? 'active' : ''}`}
                            onClick={() => setActiveTab('affinity')}
                        >
                            <img src="/icons/star.png" alt="✨" style={{ width: '16px', height: '16px', verticalAlign: 'middle', marginRight: '6px' }} /> Personas Afines
                        </button>
                        <button
                            className={`tab-btn ${activeTab === 'recommendations' ? 'active' : ''}`}
                            onClick={() => setActiveTab('recommendations')}
                        >
                            <img src="/icons/recom.png" alt="🎯" style={{ width: '16px', height: '16px', verticalAlign: 'middle', marginRight: '6px' }} /> Recomendaciones
                        </button>
                    </div>

                    {/* Media Filter (For Tierlists and Recommendations) */}
                    {(activeTab === 'tierlists' || activeTab === 'recommendations') && (
                        <div className="media-filters">
                            {/* 'Todo' removed as per request */}
                            <button
                                className={`filter-chip ${mediaFilter === 'game' ? 'active' : ''}`}
                                onClick={() => setMediaFilter('game')}
                            >
                                <img src="/icons/videogame.png" alt="🎮" style={{ width: '16px', height: '16px', marginRight: '6px' }} /> Juegos
                            </button>
                            <button
                                className={`filter-chip ${mediaFilter === 'anime' ? 'active' : ''}`}
                                onClick={() => setMediaFilter('anime')}
                            >
                                <img src="/icons/anime.png" alt="📺" style={{ width: '16px', height: '16px', marginRight: '6px' }} /> Anime
                            </button>
                        </div>
                    )}
                </div>

                {activeTab === 'affinity' && (
                    <div className="users-grid">
                        {users.length === 0 ? (
                            <div className="empty-state">
                                <p>No se encontraron personas</p>
                                {debouncedQuery ? (
                                    <p className="empty-subtitle">Intenta con otro nombre de usuario</p>
                                ) : (
                                    <p className="empty-subtitle">¡Prueba a añadir más tags o juegos favoritos a tu perfil!</p>
                                )}
                            </div>
                        ) : (
                            users.map(u => (
                                <div key={u.user_id} className="user-card-grid affinity-card-mode">
                                    <div className="user-card-header">
                                        <div className={`affinity-badge ${u.affinity >= 60 ? 'high' : u.affinity >= 30 ? 'medium' : 'low'}`}>
                                            {u.affinity}% Afinidad
                                        </div>
                                    </div>
                                    <div className="user-card-content">
                                        {u.avatar_url ? (
                                            <img src={u.avatar_url} alt="" className="user-card-avatar" />
                                        ) : (
                                            <DefaultAvatar className="user-card-avatar-placeholder" accent={u.theme_color} />
                                        )}
                                        <h3 className="user-card-name">{u.display_name}</h3>
                                        <span className="user-card-username">Identidad oculta hasta conectar</span>

                                        {/* Preview of matches */}
                                        <div className="matches-preview">
                                            {u.matches?.slice(0, 3).map((m, i) => (
                                                <span key={i} className="mini-match-pill" title={`${m.type}: ${m.value}`}>
                                                    {m.icon === '🎮' ? <img src="/icons/videogame.png" alt="🎮" style={{ width: '12px', height: '12px', verticalAlign: 'middle', marginRight: '2px' }} /> : m.icon === '📺' ? <img src="/icons/anime.png" alt="📺" style={{ width: '12px', height: '12px', verticalAlign: 'middle', marginRight: '2px' }} /> : m.icon} {m.value}
                                                </span>
                                            ))}
                                            {u.matches?.length > 3 && (
                                                <span className="mini-match-more">+{u.matches.length - 3}</span>
                                            )}
                                        </div>
                                    </div>
                                    <div className="user-card-actions">
                                        <Link
                                            to={`/compare/${u.user_id}`}
                                            className="btn btn-primary btn-full"
                                        >
                                            Ver compatibilidad
                                        </Link>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                )}

                {activeTab === 'tierlists' && (
                    <div className="tierlists-grid">
                        {tierlists.length === 0 ? (
                            <div className="empty-state">
                                <p>No hay tierlists que coincidan</p>
                            </div>
                        ) : (
                            tierlists.map(t => (
                                <Link key={t.id} to={`/tierlist/${t.id}`} className="tierlist-poster">
                                    <div className="poster-preview">
                                        {/* Collage of first 4 items if available, or placeholder */}
                                        {(() => {
                                            // Helper to find image
                                            let bg = null
                                            if (t.content) {
                                                const priorities = ['S', '#1', 'Top', 'God Tier', 'A', '#2', 'B', '#3', 'C', '#4', 'D', '#5', 'E', 'F']
                                                for (const key of priorities) {
                                                    if (t.content[key]?.[0]?.image_url) {
                                                        bg = t.content[key][0].image_url
                                                        break
                                                    }
                                                }
                                                if (!bg) {
                                                    for (const key in t.content) {
                                                        const row = t.content[key]
                                                        if (Array.isArray(row) && row.length > 0) {
                                                            const item = row.find(i => i.image_url)
                                                            if (item) { bg = item.image_url; break; }
                                                        }
                                                    }
                                                }
                                            }
                                            if (!bg && t.tierlist_items && t.tierlist_items.length > 0) {
                                                bg = t.tierlist_items.find(i => i.image_url)?.image_url
                                            }

                                            if (bg) {
                                                return <img src={bg} className="poster-cover" alt="" />
                                            }
                                            return (
                                                <div className="poster-placeholder">
                                                    {t.media_type === 'anime' ? <img src="/icons/anime.png" alt="📺" style={{ width: '40px', height: '40px', opacity: 0.8 }} /> : <img src="/icons/videogame.png" alt="🎮" style={{ width: '40px', height: '40px', opacity: 0.8 }} />}
                                                </div>
                                            )
                                        })()}
                                        <div className="poster-overlay">
                                            <span className="poster-type">
                                                {t.list_type === 'ranking' ? <><img src="/icons/medal.png" alt="🏆" style={{ width: '14px', height: '14px', verticalAlign: 'middle', marginRight: '4px' }} /> Ranking</> : <><img src="/icons/tierlist.png" alt="📊" style={{ width: '14px', height: '14px', verticalAlign: 'middle', marginRight: '4px' }} /> Tierlist</>}
                                            </span>
                                        </div>
                                    </div>
                                    <div className="poster-info">
                                        <h3 className="poster-title">{t.title}</h3>
                                        <div className="poster-meta">
                                            {t.profiles?.avatar_url ? (
                                                <img src={t.profiles.avatar_url} alt="" className="mini-avatar" />
                                            ) : (
                                                <DefaultAvatar className="mini-avatar placeholder" accent={t.profiles?.theme_color} />
                                            )}
                                            <span className="poster-author">@{t.profiles?.username}</span>
                                            <span className="poster-likes">❤️ {t.likes_count || 0}</span>
                                        </div>
                                    </div>
                                </Link>
                            ))
                        )}
                    </div>
                )}

                {activeTab === 'recommendations' && (
                    <div className="recommendations-container">
                        {/* Show search results if searching, otherwise show recommendations */}
                        {debouncedQuery.trim().length > 0 ? (
                            searchResults.length === 0 ? (
                                <div className="empty-state">
                                    <p>No se encontraron resultados</p>
                                    <p className="empty-subtitle">Intenta con otro nombre</p>
                                </div>
                            ) : (
                                <div className="recommendations-grid">
                                    {searchResults.map((result, i) => (
                                        <RecommendationCard
                                            key={`search_${result.media_type}_${result.work_id}_${i}`}
                                            recommendation={result}
                                            onAddToLibrary={handleAddToLibrary}
                                        />
                                    ))}
                                </div>
                            )
                        ) : recommendations.length === 0 ? (
                            <div className="empty-state">
                                <p>No hay recomendaciones disponibles</p>
                                {profile?.library?.length === 0 && profile?.anime_library?.length === 0 ? (
                                    <p className="empty-subtitle">¡Añade algunos juegos o animes a tu biblioteca para recibir recomendaciones personalizadas!</p>
                                ) : (
                                    <p className="empty-subtitle">Intenta añadir más contenido a tu perfil o espera a que más usuarios se unan</p>
                                )}
                            </div>
                        ) : (
                            (() => {
                                // Split recommendations into Social (Following) and General
                                const socialRecs = recommendations.filter(r => r.reasons && r.reasons.some(reason => reason.type === 'following'))
                                const generalRecs = recommendations.filter(r => !r.reasons || !r.reasons.some(reason => reason.type === 'following'))

                                // Helper to render grid
                                const renderGrid = (list, prefix) => (
                                    <div className="recommendations-grid">
                                        {list.map((rec, i) => (
                                            <RecommendationCard
                                                key={`${prefix}_${rec.media_type}_${rec.work_id}_${i}`}
                                                recommendation={rec}
                                                onAddToLibrary={handleAddToLibrary}
                                            />
                                        ))}
                                    </div>
                                )

                                if (socialRecs.length > 0) {
                                    return (
                                        <div className="recommendations-split-view">
                                            {/* General Recommendations First */}
                                            {generalRecs.length > 0 && (
                                                <div className="recommendation-section">
                                                    <h3 className="section-header">
                                                        <span className="section-icon"><img src="/icons/recom.png" alt="🎯" style={{ width: '20px', height: '20px', verticalAlign: 'middle' }} /></span>
                                                        Para ti
                                                    </h3>
                                                    {renderGrid(generalRecs, 'general')}
                                                </div>
                                            )}

                                            {/* Social Recommendations Second */}
                                            <div className="recommendation-section">
                                                <h3 className="section-header">
                                                    De las personas a las que sigues
                                                </h3>
                                                {renderGrid(socialRecs, 'social')}
                                            </div>
                                        </div>
                                    )
                                }

                                // Fallback to single grid if no social recs
                                return (
                                    <div className="recommendations-grid">
                                        {recommendations.map((rec, i) => (
                                            <RecommendationCard
                                                key={`rec_${rec.media_type}_${rec.work_id}_${i}`}
                                                recommendation={rec}
                                                onAddToLibrary={handleAddToLibrary}
                                            />
                                        ))}
                                    </div>
                                )
                            })()
                        )}
                    </div> // This closing div was for recommendations-grid, but we handle layout inside now for split view
                )}
            </div>
        </div>
    )
}

