    const [profilePosts, setProfilePosts] = useState([])
    const [profilePostsLoading, setProfilePostsLoading] = useState(false)
    const [profilePostsError, setProfilePostsError] = useState('')
    const [profilePostColumnCount, setProfilePostColumnCount] = useState(2)
    const profilePostsGridRef = useRef(null)

    const { toast } = useToast()
    const isOwnProfile = !username || username === myProfile?.username

    useEffect(() => {
        let active = true
        setBannerColors(null)
        if (profile?.banner_url) {
            extractBannerPalette(profile.banner_url).then(colors => {
                if (active) setBannerColors(colors)
            })
        }
        return () => { active = false }
    }, [profile?.id, profile?.banner_url])

    useEffect(() => {
        const layout = document.querySelector('.layout')
        if (!layout) return undefined
        const hasProfileColors = profile?.theme_color || profile?.banner_color || bannerColors
        const palette = hasProfileColors
            ? getProfilePalette(bannerColors || profile.banner_color || profile.theme_color, profile.theme_color || '#14b8a6')
            : null
        const background = palette?.['--profile-page-bg'] || '#080808'
        layout.style.setProperty('--profile-tail-bg', background)
        return () => layout.style.removeProperty('--profile-tail-bg')
    }, [profile?.id, profile?.theme_color, profile?.banner_color, bannerColors])

    useEffect(() => {
        let active = true
        if (!profile?.id) {
            setProfilePosts([])
            return () => { active = false }
        }
        setProfilePostsLoading(true)
        setProfilePostsError('')
        getPostsByUser(profile.id)
            .then(posts => { if (active) setProfilePosts(posts) })
            .catch(error => {
                console.error('No se pudieron cargar los posts del perfil:', error)
                if (active) setProfilePostsError('No se pudieron cargar las publicaciones.')
            })
            .finally(() => { if (active) setProfilePostsLoading(false) })
        return () => { active = false }
    }, [profile?.id])

    useEffect(() => {
        let active = true
        if (!profile?.id) {
            setUserLists([])
            setUserTemplates([])
            setProfileListsLoading(false)
            return () => { active = false }
        }
        setUserLists([])
        setUserTemplates([])
        setProfileListsLoading(true)
        import('../lib/listService.js').then(({ getUserLists, getUserTemplates }) => Promise.all([
            getUserLists(profile.id),
            getUserTemplates(profile.id),
        ])).then(([lists, templates]) => {
            if (!active) return
            setUserLists(lists || [])
            setUserTemplates(templates || [])
        }).catch(error => {
            console.error('No se pudieron cargar las listas del perfil:', error)
        }).finally(() => {
            if (active) setProfileListsLoading(false)
        })
        return () => { active = false }
    }, [profile?.id])

    useEffect(() => {
        const grid = profilePostsGridRef.current
        if (!grid || typeof ResizeObserver === 'undefined') return undefined
        const updateColumns = entries => {
            const width = entries[0]?.contentRect.width || grid.clientWidth
            const gap = parseFloat(window.getComputedStyle(grid).columnGap) || 18
            const isMobile = window.matchMedia('(max-width: 768px)').matches
            const postWidth = isMobile ? 180 : 230
            const minimumColumns = isMobile ? 2 : 1
            setProfilePostColumnCount(Math.max(minimumColumns, Math.floor((width + gap) / (postWidth + gap))))
        }
        const observer = new ResizeObserver(updateColumns)
        observer.observe(grid)
        return () => observer.disconnect()
    }, [profilePosts.length, activeProfileTab])

    const profilePostColumns = Array.from({ length: profilePostColumnCount }, () => ({ height: 0, posts: [] }))
    profilePosts.forEach(post => {
        const target = profilePostColumns.reduce((shortest, column, index, columns) =>
            column.height < columns[shortest].height ? index : shortest, 0)
        const estimatedHeight = 58 + (post.body ? Math.min(130, Math.ceil(post.body.length / 34) * 20) : 0) + (post.media?.length ? 150 : 0)
        profilePostColumns[target].posts.push(post)
        profilePostColumns[target].height += estimatedHeight + 10
    })

    const navigate = useNavigate()
    const [isScrolled, setIsScrolled] = useState(false)
    const isStandalonePwa = window.matchMedia('(display-mode: standalone), (display-mode: fullscreen)').matches || navigator.standalone === true
    const isOtherProfile = Boolean(username && username !== myProfile?.username)
    const isOwnProfileFromNav = isStandalonePwa && isOwnProfile && location.state?.fromBottomNav === true
    const [isClosingPwaProfile, setIsClosingPwaProfile] = useState(false)
    const handleProfileBack = () => {
        if (!isStandalonePwa || !isOtherProfile) return navigateBackOrHome(navigate)
        setIsClosingPwaProfile(true)
        window.setTimeout(() => navigateBackOrHome(navigate), 280)
    }

    useEffect(() => {
        if (!isStandalonePwa || !isOtherProfile) return undefined
        document.body.classList.add('pwa-visited-profile-open')
        return () => document.body.classList.remove('pwa-visited-profile-open')
    }, [isStandalonePwa, isOtherProfile])

    useEffect(() => {
        if (!selectedBadge) return undefined

        const previousOverflow = document.body.style.overflow
        const handleKeyDown = event => {
            if (event.key === 'Escape') setSelectedBadge(null)
        }

        document.body.style.overflow = 'hidden'
        document.addEventListener('keydown', handleKeyDown)
        return () => {
            document.body.style.overflow = previousOverflow
            document.removeEventListener('keydown', handleKeyDown)
        }
    }, [selectedBadge])

    useEffect(() => {
        document.body.classList.add('profile-no-main-header-on-mobile')

        const handleScroll = () => {
            setIsScrolled(window.scrollY > 300)
        }
        window.addEventListener('scroll', handleScroll)

        return () => {
            document.body.classList.remove('profile-no-main-header-on-mobile')
            window.removeEventListener('scroll', handleScroll)
        }
    }, [])

    useEffect(() => {
        if (audioRef.current) {
            audioRef.current.pause()
            audioRef.current = null
        }
        setIsPlaying(false)
        loadProfile()
        }, [username, myProfile])

    const getCollageImages = (content) => {
        let images = [];
        if (!content) return images;
        
        const addImg = (item) => {
            if (!item) return;
            const img = item.image_url || item.cover_url || (item.cover && item.cover.url);
            if (img && !images.includes(img)) {
                images.push(img);
            }
        };

        if (Array.isArray(content)) {
            // Ranking format
            for (const item of content) {
                addImg(item);
                if (images.length === 4) return images;
            }
        } else {
            // Tierlist or Grid format
            const priorities = ['S', '#1', 'Top', 'God Tier', 'A', '#2', 'B', '#3', 'C', '#4', 'D', '#5', 'E', 'F'];
            // Try priorities first
            for (const key of priorities) {
                if (content[key]) {
                    if (Array.isArray(content[key])) {
                        for (const item of content[key]) {
                            addImg(item);
                            if (images.length === 4) return images;
                        }
                    } else {
                        addImg(content[key]);
                        if (images.length === 4) return images;
                    }
                }
            }
            // Then any other row/cell
            for (const key in content) {
                if (!priorities.includes(key) && content[key]) {
                    if (Array.isArray(content[key])) {
                        for (const item of content[key]) {
                            addImg(item);
                            if (images.length === 4) return images;
                        }
                    } else {
                        addImg(content[key]);
                        if (images.length === 4) return images;
                    }
                }
            }
        }
        return images;
    }

    const loadProfile = async () => {
        try {
            setIsFollowing(false)
            setIsFollowedBy(false)
            let profileData, userId

            if (isOwnProfile) {
                profileData = myProfile
                userId = user?.id
            } else {
                const { data } = await supabase
                    .from('profiles').select('*')
                    .eq('username', username).single()
                profileData = data
                userId = data?.id
            }


            setProfile(profileData)
            if (profileData) {
                if (profileData.favorite_games && profileData.favorite_games.length > 0) {
                    setActiveFavTab('games')
                } else if (profileData.favorite_animes && profileData.favorite_animes.length > 0) {
                    setActiveFavTab('anime')
                }
            }

            if (!userId) { setLoading(false); return }

            if (!isOwnProfile && user) {
                const [followingResult, followedByResult] = await Promise.all([
                    supabase.from('follows').select('id')
                        .eq('follower_id', user.id).eq('following_id', userId).maybeSingle(),
                    supabase.from('follows').select('id')
                        .eq('follower_id', userId).eq('following_id', user.id).maybeSingle()
                ])
                setIsFollowing(!!followingResult.data)
                setIsFollowedBy(!!followedByResult.data)
            }
        } catch (err) {
            console.error('Error loading profile:', err)
        } finally {
            setLoading(false)
        }
    }

    const handleFollow = async () => {
        if (!user) {
            navigate('/register')
            return
        }
        if (!profile) {
            navigate('/onboarding')
            return
        }
        if (!myProfile) {
            navigate('/onboarding')
            return
        }
        try {
            if (isFollowing) {
                await supabase.from('follows').delete()
                    .eq('follower_id', user.id).eq('following_id', profile.id)
                setIsFollowing(false)
            } else {
                await supabase.from('follows').insert({ follower_id: user.id, following_id: profile.id })
                setIsFollowing(true)
            }
        } catch (err) { console.error('Follow error:', err) }
    }

    const followLabel = isFollowing
        ? isFollowedBy ? 'Amigos' : 'Siguiendo'
        : isFollowedBy ? 'Seguir también' : 'Seguir'

    useEffect(() => {
        return () => {
            if (audioRef.current) {
                audioRef.current.pause()
                audioRef.current = null
            }
        }
    }, [])

    const togglePlay = async () => {
        let songData = profile?.profile_song
        if (typeof songData === 'string') {
            try { songData = JSON.parse(songData) } catch (e) { return }
        }
        if (!songData) return

        if (!audioRef.current) {
            let finalUrl = songData.previewUrl;
            
            // Si es de Deezer y tenemos ID, pillamos la URL fresca porque la preview caduca
            if (songData.trackId && (songData.provider === 'deezer' || !songData.provider)) {
                try {
                    finalUrl = await new Promise((resolve) => {
                        const cbName = 'dzCb_' + Date.now() + Math.floor(Math.random()*1000);
                        const scriptId = 'dzScript_' + cbName;
                        window[cbName] = (data) => {
                            document.getElementById(scriptId)?.remove();
                            delete window[cbName];
                            resolve(data?.preview || songData.previewUrl);
                        };
                        const script = document.createElement('script');
                        script.id = scriptId;
                        script.src = `https://api.deezer.com/track/${songData.trackId}?output=jsonp&callback=${cbName}`;
                        document.body.appendChild(script);
                        setTimeout(() => resolve(songData.previewUrl), 3000);
                    });
                } catch(e) {}
            }

            if (!finalUrl) return;

            const audio = new Audio(finalUrl)
            audio.volume = 0.5
            
            // Sincronizar estado con eventos nativos
            audio.onplay = () => setIsPlaying(true)
            audio.onpause = () => setIsPlaying(false)
            audio.onended = () => {
                setIsPlaying(false)
                audio.currentTime = 0 // Reiniciar al acabar
                audio.volume = 0.5    // Restaurar volumen original
            }

            // Efecto de fade-out en los últimos 3 segundos para que no corte brusco
            audio.ontimeupdate = () => {
                if (!audio.duration) return
                const timeLeft = audio.duration - audio.currentTime
                if (timeLeft < 3 && timeLeft > 0) {
                    audio.volume = Math.max(0, (timeLeft / 3) * 0.5)
                }
            }

            audioRef.current = audio
        }

        if (audioRef.current.paused) {
            audioRef.current.play().catch(e => console.log('Auto-play blocked or error:', e))
        } else {
            audioRef.current.pause()
        }
    }

    const renderSongPlayer = (className) => {
        let parsedSong = null
        if (profile?.profile_song) {
            if (typeof profile.profile_song === 'object') parsedSong = profile.profile_song
            else if (typeof profile.profile_song === 'string') {
                try { parsedSong = JSON.parse(profile.profile_song) } catch (e) { /* ignore */ }
            }
        }
        if (!parsedSong?.previewUrl) return null

        return (
            <div className={`custom-song-pill ${className}`} onClick={togglePlay}>
                <div className={`song-cover-wrapper ${isPlaying ? 'playing' : ''}`}>
                    <img src={parsedSong.cover} alt="cover" className="song-cover" />
                    <div className="song-center-hole"></div>
                </div>
                <div className="song-info">
                    <div className="song-name-scroll">
                        <span>{parsedSong.name}</span>
                    </div>
                    <span className="song-artist">{parsedSong.artist}</span>
                </div>
                <button className="song-play-btn">
                    {isPlaying ? (
                        <svg viewBox="0 0 24 24" fill="currentColor" width="20" height="20">
                            <rect x="6" y="5" width="4" height="14" rx="1" />
                            <rect x="14" y="5" width="4" height="14" rx="1" />
                        </svg>
                    ) : (
                        <svg viewBox="0 0 24 24" fill="currentColor" width="20" height="20">
                            <path d="M8 5v14l11-7z" />
                        </svg>
                    )}
                </button>
            </div>
        )
    }

    if (loading) return isStandalonePwa && isOtherProfile ? null : <div className="profile-loading"><LoadingSpinner /></div>

    if (!profile) return (
        <div className="profile-error">
            <h2>Usuario no encontrado</h2>
            <Link to="/home" className="btn btn-primary">Volver al inicio</Link>
        </div>
    )

    const hasSocials = profile.social_links && Object.values(profile.social_links).some(Boolean)
    const profileAccent = profile.theme_color || '#14b8a6'
    const accentTextColor = getAccentTextColor(profileAccent)
    const visibleAccent = getVisibleAccentColor(profileAccent)
    const profileColors = profile.theme_color || profile.banner_color || bannerColors
        ? getProfilePalette(bannerColors || profile.banner_color || profile.theme_color, profileAccent)
        : {
            '--profile-accent-text': accentTextColor,
            '--profile-accent-visible': visibleAccent
        }

    return (
        <div className={`profile-page${profile.theme_color || profile.banner_color || bannerColors ? ' profile-themed' : ''}${isStandalonePwa && isOtherProfile ? ' pwa-visited-profile' : ''}${isClosingPwaProfile ? ' is-closing' : ''}`} style={{ ...profileColors, ...getProfileTypography(profile.name_font, profile.bio_font) }}>
            <SEO title={`${profile.display_name || profile.username} (@${profile.username})`} description={`Perfil de ${profile.display_name || profile.username} en GeekSphere.`} />

            {/* Mobile Topbar */}
            <div className={`profile-mobile-nav ${isScrolled ? 'scrolled' : ''}`}>
                {!isOwnProfileFromNav && <button className="profile-mobile-back" onClick={handleProfileBack}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                        <line x1="19" y1="12" x2="5" y2="12" />
                        <polyline points="12 19 5 12 12 5" />
                    </svg>
                </button>}
                <div className={`profile-mobile-mini-info ${isScrolled ? 'visible' : ''}`}>
                    <div className="profile-mobile-name-row">
                        {hasCustomAvatar(profile.avatar_url) ? (
                            <img className="profile-mobile-mini-avatar" src={profile.avatar_url} alt="" />
                        ) : (
                            <DefaultAvatar className="profile-mobile-mini-avatar profile-mobile-mini-avatar-placeholder" accent={profile.theme_color} />
                        )}
                        <span className="profile-mobile-name" style={{ fontFamily: getProfileFontStack(profile.name_font) }}>{profile.display_name}</span>
                    </div>
                    {!isOwnProfile && (
                        <button
                            className={`btn btn-primary profile-follow-button${isFollowing && isFollowedBy ? ' profile-friends-button' : ''}`}
                            style={{ padding: '4px 12px', fontSize: '0.8rem', minHeight: '28px', flexShrink: 0 }}
                            onClick={handleFollow}
                        >
                            {followLabel}
                        </button>
                    )}
                </div>
            </div>

            {/* ─── Banner ─── */}
            <div className="profile-banner">
                {profile.banner_url && (
                    <>
                        <img src={profile.banner_url} alt="" className="profile-banner-img" />
                        <div className="profile-banner-overlay" />
                    </>
                )}
            </div>

            {/* ─── Header card ─── */}
            <div className="profile-header-card">
                <div className="profile-header-inner">
                    {/* El avatar comparte el ancho centrado del contenido del perfil. */}
                    <div className="profile-avatar-wrapper">
                        {hasCustomAvatar(profile.avatar_url) ? (
                            <img
                                src={profile.avatar_url}
                                alt={profile.display_name}
                                className="profile-avatar"
                            />
                        ) : (
                            <DefaultAvatar className="profile-avatar-placeholder" accent={profile.theme_color} />
                        )}
                    </div>

                    {/* Fila 2: Identidad — nombre, @user, bio, stats, plataformas, socials */}
                    
                    
                    <div className={`profile-header-columns ${profile?.favorite_animes?.length || profile?.favorite_games?.length ? 'has-favorites' : 'without-favorites'}`}>
                        <div className={`profile-identity ${profile.location ? 'has-location' : 'no-location'}`}>
                            
                        <div className="profile-name-row" style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
                            <h1 className="profile-display-name" style={{ margin: 0, fontFamily: getProfileFontStack(profile.name_font) }}>{profile.display_name}</h1>
                            {profile.featured_badge && BADGES_MAP[profile.featured_badge] && (
                                <button
                                    type="button"
                                    className="profile-featured-badge"
                                    title={`Insignia destacada: ${BADGES_MAP[profile.featured_badge].title}`}
                                    aria-label={`Insignia destacada: ${BADGES_MAP[profile.featured_badge].title}`}
                                    aria-haspopup="dialog"
                                    onClick={() => setSelectedBadge(profile.featured_badge)}
                                    style={{ color: BADGES_MAP[profile.featured_badge].color }}
                                >
                                    {BADGES_MAP[profile.featured_badge].icon}
                                </button>
                            )}
                            {profile.pronouns && (
                                <span className={`profile-pronouns ${profile.featured_badge && BADGES_MAP[profile.featured_badge] ? '' : 'profile-pronouns-no-badge'}`}>{profile.pronouns}</span>
                            )}
                            <div className="profile-actions">
                                {isOwnProfile ? (
                                    <button onClick={() => navigate('/settings')} className="btn btn-secondary profile-edit-button">
                                        <IconEdit /> Editar perfil
                                    </button>
                                ) : (
                                    <button
                                        className={`btn profile-follow-button ${isFollowing ? 'btn-secondary' : 'btn-primary'}${isFollowing && isFollowedBy ? ' profile-friends-button' : ''}`}
                                        onClick={handleFollow}
                                    >
                                        {isFollowing
                                            ? <><IconUserCheck /> {followLabel}</>
                                            : <><IconUserPlus /> {followLabel}</>
                                        }
                                    </button>
                                )}
                            </div>
                        </div>

                        <div className="profile-meta-row" style={{ display: 'flex', alignItems: 'center', gap: '12px', color: 'var(--text-muted)' }}>
                            <p className="profile-username" style={{ margin: 0 }}>@{profile.username}</p>
                        </div>

                        {profile.location && (
                            <div className="profile-additional-info" style={{ display: 'flex', gap: '16px', color: 'var(--text-muted)', fontSize: '0.9rem', marginTop: '12px', marginBottom: '4px' }}>
                                <span style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                                    <IconMapPin /> {profile.location}
                                </span>
                            </div>
                        )}

                        {profile.bio && (
                            <div className="profile-bio markdown-content" style={{ fontFamily: profile.bio_font === 'inherit' ? getProfileFontStack(profile.name_font) : getProfileFontStack(profile.bio_font, 'sans') }}>
                                <ReactMarkdown remarkPlugins={[remarkGfm]}>{profile.bio}</ReactMarkdown>
                            </div>
                        )}

                        {hasSocials && (
                            <div className="profile-socials">
                                {Object.entries(profile.social_links).map(([platform, value]) => {
                                    if (!value) return null
                                    const href = getSocialLink(platform, value)
                                    return platform === 'discord' ? (
                                        <button
                                            key={platform}
                                            className="social-icon-btn"
                                            onClick={() => {
                                                navigator.clipboard.writeText(value)
                                                toast({
                                                    title: 'Discord copiado',
                                                    message: `${value} se ha copiado al portapapeles.`,
                                                    type: 'discord'
                                                })
                                            }}
                                            title={`Discord: ${value}`}
                                        >
                                            {SOCIAL_ICONS_MAP[platform]}
                                        </button>
                                    ) : (
                                        <a
                                            key={platform}
                                            href={href}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            className="social-icon-btn"
                                            title={platform}
                                        >
                                            {SOCIAL_ICONS_MAP[platform]}
                                        </a>
                                    )
                                })}
                            </div>
                        )}

                        {renderSongPlayer('profile-song-pill')}

                    </div>
                        
                                                <div className="profile-header-favorites">
                            <div className="profile-favorites-section">


                                
                                {(profile?.favorite_animes?.length > 0 || profile?.favorite_games?.length > 0) && (
                                    <div className="profile-favorites-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%', marginBottom: '12px' }}>
                                    <h3 className="profile-favorites-title" style={{ margin: 0, fontSize: '0.9rem', display: 'flex', alignItems: 'center', gap: '8px', fontFamily: 'var(--font-display)' }}>
                                        <>
                                            <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" aria-hidden="true">
                                                <path d="m12 2.8 2.86 5.8 6.4.93-4.63 4.51 1.09 6.37L12 17.4l-5.72 3.01 1.09-6.37-4.63-4.51 6.4-.93L12 2.8z" />
                                            </svg>
                                            FAVORITOS
                                        </>
                                    </h3>

                                    {(profile.favorite_animes?.length > 0 && profile.favorite_games?.length > 0) && (
                                        <div className={`fav-tab-switch ${activeFavTab === 'games' ? 'games-active' : ''}`}>
                                            <button 
                                                className={`tab-btn ${activeFavTab === 'anime' ? 'active' : ''}`}
                                                type="button"
                                                onClick={() => setActiveFavTab('anime')}
                                                title="Animes"
                                                aria-pressed={activeFavTab === 'anime'}
                                            >
                                                Anime
                                            </button>
                                            <button 
                                                className={`tab-btn ${activeFavTab === 'games' ? 'active' : ''}`}
                                                type="button"
                                                onClick={() => setActiveFavTab('games')}
                                                title="Videojuegos"
                                                aria-pressed={activeFavTab === 'games'}
                                            >
                                                Juegos
                                            </button>
                                        </div>
                                    )}
                                </div>
                                )}

                                
                                {activeFavTab === 'anime' && profile.favorite_animes && profile.favorite_animes.length > 0 && (
                                    <div className="profile-favorites-block">
                                        <div className={`profile-favorites-grid profile-favorites-grid--count-${profile.favorite_animes.length}`}>
                                            {profile.favorite_animes.map((a, idx) => (
                                                <div key={idx} className="profile-favorite-poster">
                                                    {a.cover_url ? <img src={a.cover_url} alt={a.title} /> : <div className="no-cover">{a.title}</div>}
                                                    <div className="profile-favorite-overlay">
                                                        <span>{a.title}</span>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                {activeFavTab === 'games' && profile.favorite_games && profile.favorite_games.length > 0 && (
                                    <div className="profile-favorites-block">
                                        <div className={`profile-favorites-grid profile-favorites-grid--count-${profile.favorite_games.length}`}>
                                            {profile.favorite_games.map((g, idx) => (
                                                <div key={idx} className="profile-favorite-poster">
                                                    {g.cover_url ? <img src={g.cover_url} alt={g.name} /> : <div className="no-cover">{g.name}</div>}
                                                    <div className="profile-favorite-overlay">
                                                        <span>{g.name}</span>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>

                    </div>
                </div>
            </div>

            {/* --- PROFILE SECTION TABS --- */}
            <div className="profile-section-tabs">
                {[
                    { id: 'actividad', label: 'Actividad' },
                    { id: 'posts', label: 'Posts' },
                    { id: 'tierlists', label: 'Tierlists' },
                ].map(tab => (
                    <button
                        key={tab.id}
                        className={`profile-section-tab ${activeProfileTab === tab.id ? 'active' : ''}`}
                        onClick={() => setActiveProfileTab(tab.id)}
                    >
                        {tab.label}
                    </button>
                ))}
            </div>

            <div className="profile-content">
                {activeProfileTab === 'actividad' && (
                    profile && <LibraryGrid profile={profile} userId={profile.id} username={profile.username} wishlist={profile.wishlist} />
                )}
                {activeProfileTab === 'posts' && (
                    <section className="profile-posts-section" aria-label={`Posts de ${profile?.display_name || profile?.username || 'este perfil'}`}>
                        {profilePostsLoading
                            ? <div className="profile-posts-grid profile-posts-grid-skeleton" aria-label="Cargando posts" aria-busy="true">
                                {[0, 1].map(column => <div className="profile-post-column" key={column}>
                                    {[0, 1, 2].map((card, index) => <article className="profile-post-skeleton" key={card} aria-hidden="true">
                                        <div className="profile-post-skeleton-header"><i className="is-avatar" /><i className="is-name" /><i className="is-time" /></div>
                                        {((column + index) % 2 === 0) && <i className="profile-post-skeleton-media" />}
                                        <span className="profile-post-skeleton-copy"><i /><i /><i /></span>
                                    </article>)}
                                </div>)}
                            </div>
                            : profilePostsError
                                ? <p className="profile-posts-state">{profilePostsError}</p>
                                : profilePosts.length
                                    ? <div className="profile-posts-grid" ref={profilePostsGridRef} style={{ '--profile-post-columns': profilePostColumnCount }}>
