                                                            <span style={{ fontSize: '0.65rem', color: 'var(--text-muted)' }}>Sin imagen</span>
                                                        </div>
                                                    )}
                                                </Link>
                                                <div className="review-content" style={{ display: 'flex', flexDirection: 'column', flex: 1, justifyContent: 'center' }}>
