                                                        </Link>
                                                    </div>
                                                    <div className="review-metadata" style={{ marginTop: '6px', marginBottom: '4px' }}>
                                                        <div className="search-list-tags">
                                                            {t.list_type && (
                                                                <span className={'search-list-tag type-' + t.list_type}>
                                                                    {t.list_type === 'tierlist' && <svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>}
                                                                    {t.list_type === 'ranking' && <svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>}
                                                                    {t.list_type === 'alignment' && <AlignmentIcon/>}{t.list_type === 'grid' && <svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/></svg>}
                                                                    {listTypeLabel(t.list_type)}
                                                                </span>
                                                            )}
                                                            {t.list_type !== 'ranking' && t.media_type && (
                                                                <span className={'search-list-tag media-' + t.media_type}>
                                                                    {t.media_type === 'game' && <svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="6" width="20" height="12" rx="2" ry="2"/><path d="M6 12h4"/><path d="M8 10v4"/><line x1="15" y1="13" x2="15.01" y2="13"/><line x1="18" y1="11" x2="18.01" y2="11"/></svg>}
                                                                    {t.media_type === 'anime' && <svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="7" width="20" height="15" rx="2" ry="2"/><polyline points="17 2 12 7 7 2"/></svg>}
                                                                    {t.media_type === 'game' ? 'Videojuegos' : t.media_type === 'anime' ? 'Anime' : t.media_type}
                                                                </span>
                                                            )}
                                                        </div>
                                                    </div>
                                                    <ListLikeButton listId={t.id} />
                                                </div>
                                            </div>
                                            );
                                        })
                                    })()}
                                </div>
                            )}
                        </div>

                        {/* RIGHT COLUMN: PLANTILLAS */}
                        <div className="activity-col activity-diary" style={{ display: 'flex', flexDirection: 'column', minWidth: 0 }}>
                            <div className="activity-col-header">
                                <h3>Plantillas</h3>
                                {profile?.username && <Link to={`/profile/${profile.username}/templates`} className="activity-view-all">Ver todas</Link>}
                            </div>
                            {profileListsLoading ? <div className="profile-template-skeleton" aria-label="Cargando plantillas" aria-busy="true">{[0, 1, 2, 3].map(index => <div className="profile-template-skeleton-row" key={index} aria-hidden="true"><i className="is-art" /><span><i /><i /></span></div>)}</div> : userTemplates.length === 0 ? (
                                <div className="activity-empty-box">Aún no hay plantillas creadas.</div>
                            ) : (
                                <div className="diary-entries" style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                                    {userTemplates.slice(0, 4).map(t => (
                                        <div key={t.id} className="diary-entry" style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
                                            <Link to={`/templates/${t.id}`} className="diary-entry-poster">
                                                <div className="diary-micro-poster" style={{ background: 'var(--bg-tertiary)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-secondary)' }}>
                                                    {t.list_type === 'tierlist' || !t.list_type ? <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg> : null}
                                                    {t.list_type === 'ranking' && <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>}
                                                    {t.list_type === 'alignment' && <AlignmentIcon/>}{t.list_type === 'grid' && <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/></svg>}
                                                </div>
                                            </Link>
                                            <div className="diary-entry-info">
                                                <div className="diary-entry-header">
                                                    <Link to={`/templates/${t.id}`} className="diary-entry-title">
                                                        {t.title}
                                                    </Link>
                                                </div>
                                                <div className="review-metadata" style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: '4px' }}>
                                                    <svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M23 21v-2a4 4 0 0 0-3-3.87"></path><path d="M16 3.13a4 4 0 0 1 0 7.75"></path></svg>
                                                    <span>{t.uses_count || 0}</span>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>

            <FollowsModal
                isOpen={followsModal.isOpen}
                onClose={() => setFollowsModal(prev => ({ ...prev, isOpen: false }))}
                type={followsModal.type}
                userId={profile.id}
                themeColor={profile.theme_color}
            />

            {selectedBadge && BADGES_MAP[selectedBadge] && createPortal(
                <div
                    className="profile-badge-modal-backdrop"
                    onClick={event => { if (event.target === event.currentTarget) setSelectedBadge(null) }}
                >
                    <section
                        className="profile-badge-modal"
                        role="dialog"
                        aria-modal="true"
                        aria-labelledby="profile-badge-modal-title"
                        style={{ '--badge-color': BADGES_MAP[selectedBadge].color }}
                    >
                        <button
                            type="button"
                            className="profile-badge-modal-close"
                            onClick={() => setSelectedBadge(null)}
                            aria-label="Cerrar información de insignia"
                        >
                            <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true">
                                <path d="m18 6-12 12M6 6l12 12" />
                            </svg>
                        </button>
                        <div className="profile-badge-modal-icon" aria-hidden="true">
                            {BADGES_MAP[selectedBadge].icon}
                        </div>
                        <span className="profile-badge-modal-kicker">Insignia de perfil</span>
                        <h2 id="profile-badge-modal-title">{BADGES_MAP[selectedBadge].title}</h2>
                        <p>{BADGES_MAP[selectedBadge].description}</p>
                        <div className="profile-badge-modal-footer">
                            <span className="profile-badge-modal-dot" />
                            Insignia de la comunidad
                        </div>
                    </section>
                </div>,
                document.body
            )}

            {searchParams.get('edit') === 'true' && (
                <EditProfile onClose={() => setSearchParams({})} />
            )}
        </div>
    )
}

import { useEffect, useState } from 'react'
import { Link, useLocation, useNavigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import SEO from '../components/SEO'
import AuthProviderButtons from '../components/AuthProviderButtons'
import { invitationFromSearch, readInvitation, rememberInvitation, setInvitationFollow } from '../lib/invitations'
import './Auth.css'

const STEPS = ['Perfil', 'Correo', 'Seguridad']

export default function Register() {
    const [step, setStep] = useState(1)
    const [username, setUsername] = useState('')
    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const [error, setError] = useState('')
    const [loading, setLoading] = useState(false)
    const [providerLoading, setProviderLoading] = useState('')
    const [showEmailForm, setShowEmailForm] = useState(false)
    const { signUp, signInWithProvider, rememberCurrentAccount } = useAuth()
    const location = useLocation()
    const navigate = useNavigate()
    const [invitation, setInvitation] = useState(() => {
        const incoming = invitationFromSearch(location.search)
        return readInvitation() || (incoming ? rememberInvitation(incoming) : null)
    })
    const addAccount = new URLSearchParams(location.search).get('addAccount') === '1'

    useEffect(() => {
        setShowEmailForm(false)
        setStep(1)
        setError('')
    }, [location.key])

    const handleNext = event => {
        event.preventDefault()
        setError('')
        if (step === 1) {
            if (username.length < 3) return setError('El nombre de usuario debe tener al menos 3 caracteres')
            if (username.length > 20) return setError('El nombre de usuario no puede superar los 20 caracteres')
            if (!/^[a-zA-Z0-9_]+$/.test(username)) return setError('El nombre solo puede contener letras, números y guiones bajos')
            setStep(2)
        } else if (step === 2) {
            if (!email.includes('@')) return setError('Introduce un correo válido')
            setStep(3)
        }
    }

    const handleSubmit = async event => {
        event.preventDefault()
        setError('')
        if (password.length < 6) return setError('La contraseña debe tener al menos 6 caracteres')
        setLoading(true)
        sessionStorage.setItem('geeksphere.pending-signup-email', email.trim().toLowerCase())
        if (addAccount) sessionStorage.setItem('geeksphere.add-account-pending', '1')
        try {
            const result = await signUp(email, password, username, invitation)
            if (addAccount && result?.session) await rememberCurrentAccount()
            navigate('/confirm-email')
        } catch (err) {
            sessionStorage.removeItem('geeksphere.pending-signup-email')
            if (addAccount) sessionStorage.removeItem('geeksphere.add-account-pending')
            setError(err.message || 'Error al registrarse')
            setLoading(false)
        }
    }

    const handleProvider = async provider => {
        setError('')
        setProviderLoading(provider)
        try {
            await signInWithProvider(provider, { addAccount, invitation })
        } catch (err) {
            setError(err.message || `No se pudo continuar con ${provider}`)
            setProviderLoading('')
        }
    }

    return (
        <div className="auth-page auth-register-page">
            <SEO title="Únete a GeekSphere" description="Únete a GeekSphere y empieza a organizar tus gustos en anime y videojuegos." />
            <div className="register-composition">
                <header className="register-hero">
                    <Link to="/home" className="register-mark" aria-label="Volver a GeekSphere"><img src="/icons/logo.png" alt="" /></Link>
                    <h1>Tu esfera de gustos,<br /><span>en un solo lugar.</span></h1>
                </header>
                <section className="register-form-section" aria-labelledby={showEmailForm ? 'register-title' : undefined} aria-label={!showEmailForm ? 'Opciones para unirse' : undefined}>
                    {showEmailForm && <div className="auth-form-heading register-heading">
                        {step === 1 && <h2 id="register-title">Crea tu perfil</h2>}
                        {step === 2 && <h2 id="register-title">Añade tu correo</h2>}
                        {step === 3 && <h2 id="register-title">Crea tu contraseña</h2>}
                    </div>}
                    {showEmailForm ? <>
                        <div className="register-progress" aria-label={`Paso ${step} de 3`}>
                            <div className="register-progress-track"><span style={{ width: `${(step / 3) * 100}%` }} /></div>
                            <div className="register-progress-labels">{STEPS.map((label, index) => <span className={index + 1 <= step ? 'active' : ''} key={label}>{label}</span>)}</div>
                        </div>
                        <button type="button" className="auth-back-to-options" onClick={() => { setError(''); setShowEmailForm(false) }}>← Otras opciones</button>
                    </> : null}
                    {error && <div className="auth-error" role="alert">{error}</div>}
                    {invitation && <div className="register-invitation">
                        <strong>{invitation.username ? `Te ha invitado @${invitation.username}` : 'Te unes con una invitación'}</strong>
                        <label><input type="checkbox" checked={invitation.autoFollow} onChange={event => {
                            const autoFollow = event.target.checked
                            setInvitationFollow(autoFollow)
                            setInvitation(previous => ({ ...previous, autoFollow }))
                        }} /><span>Seguir a quien me ha invitado al completar mi perfil. Podré dejar de seguirle cuando quiera.</span></label>
                    </div>}
                    {!showEmailForm ? <>
                        <AuthProviderButtons onProvider={handleProvider} loadingProvider={providerLoading} />
                        <div className="auth-divider"><span>o</span></div>
                        <button type="button" className="auth-email-toggle" onClick={() => { setError(''); setShowEmailForm(true) }}>Usar correo en su lugar</button>
                    </> : <form onSubmit={step === 3 ? handleSubmit : handleNext} className="auth-form register-form">
                        {step === 1 && <div className="input-group">
                            <label className="input-label" htmlFor="register-username">Nombre de usuario</label>
                            <input id="register-username" type="text" className="input auth-input" placeholder="Ej.: mikasa_42" value={username} onChange={event => setUsername(event.target.value.toLowerCase().slice(0, 20))} autoComplete="username" autoFocus maxLength={20} required />
                            <span className="register-field-hint">3–20 caracteres · letras, números y _</span>
                        </div>}
                        {step === 2 && <div className="input-group">
                            <label className="input-label" htmlFor="register-email">Correo electrónico</label>
                            <input id="register-email" type="email" className="input auth-input" placeholder="tu@correo.com" value={email} onChange={event => setEmail(event.target.value)} autoComplete="email" autoFocus required />
                            <span className="register-field-hint">Usaremos tu correo para verificar la cuenta.</span>
                        </div>}
                        {step === 3 && <div className="input-group">
                            <label className="input-label" htmlFor="register-password">Contraseña</label>
                            <input id="register-password" type="password" className="input auth-input" placeholder="Mínimo 6 caracteres" value={password} onChange={event => setPassword(event.target.value)} autoComplete="new-password" autoFocus required />
                            <span className="register-field-hint">Usa al menos 6 caracteres.</span>
                        </div>}
                        <div className="register-actions">
                            {step > 1 && <button type="button" className="auth-back" onClick={() => { setError(''); setStep(step - 1) }}>Atrás</button>}
                            <button type="submit" className="auth-submit" disabled={loading}>{loading ? 'Creando…' : step === 3 ? 'Crear cuenta' : 'Continuar'}</button>
                        </div>
                    </form>}
                    <div className="auth-card-footer"><span>¿Ya tienes cuenta?</span><Link to={`/login${addAccount ? '?addAccount=1' : ''}`}>Inicia sesión</Link></div>
                    <nav className="register-legal-links" aria-label="Documentos legales"><Link to="/terms">Términos</Link><Link to="/privacy">Privacidad</Link><Link to="/community-guidelines">Normas de comunidad</Link></nav>
                </section>
            </div>
        </div>
    )
}

import useSystemBarColor from '../hooks/useSystemBarColor'
import { useCallback, useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { FaFacebookF, FaRedditAlien, FaTelegram, FaWhatsapp, FaXTwitter } from 'react-icons/fa6'
import { Link, useNavigate, useParams } from 'react-router-dom'
