function ReviewStars({ rating }) {
  const value = rating == null ? 0 : Math.max(0, Math.min(5, Number(rating)))
  return <span className="review-detail-stars" aria-label={`${rating == null ? 'Sin nota' : `${value.toFixed(1)} de 5`} estrellas`}>
    <span className="review-detail-stars-icons">
      {Array.from({ length: 5 }, (_, index) => {
        const fill = Math.max(0, Math.min(1, value - index))
        const gradientId = `review-star-${index}`
        return <svg key={index} viewBox="0 0 24 24" aria-hidden="true">
          {fill > 0 && fill < 1 && <defs><linearGradient id={gradientId}><stop offset={`${fill * 100}%`} stopColor="var(--review-page-accent)"/><stop offset={`${fill * 100}%`} stopColor="transparent"/></linearGradient></defs>}
          <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" fill={fill === 1 ? 'var(--review-page-accent)' : fill > 0 ? `url(#${gradientId})` : 'none'} />
        </svg>
      })}
    </span>
    <strong>{rating == null ? '—' : value.toFixed(1)}</strong>
  </span>
}

function getReleaseYear(work, workType) {
  const release = workType === 'game'
    ? work?.release_date || work?.first_release_date
    : work?.release_date || work?.start_date
  if (!release) return null
  if (typeof release === 'number') {
    const date = new Date(release > 9999999999 ? release : release * 1000)
    return Number.isNaN(date.getTime()) ? null : date.getFullYear()
  }
  const value = String(release).trim()
  if (/^\d{4}$/.test(value)) return value
  const year = value.match(/^(\d{4})/)
  if (year) return year[1]
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? null : date.getFullYear()
}

function getReviewShareCover(url) {
  if (!url) return null
  let source = url.startsWith('//') ? `https:${url}` : url
  if (source.includes('images.igdb.com')) source = source.replace(/t_[a-z0-9_]+/i, 't_cover_big').replace(/t_thumb/i, 't_cover_big')
  if (/anilist\.co/i.test(source)) source = source.replace('/cover/medium/', '/cover/large/')
  return source
}

function ProfileAvatar({ profile, size = 'normal' }) {
  const name = profile?.display_name || profile?.username || 'Usuario'
  return <span className={`review-detail-avatar ${size}`} style={{ '--review-author-theme': profile?.theme_color || 'var(--brand-primary)' }}>
    {profile?.avatar_url ? <img src={profile.avatar_url} alt="" /> : <DefaultAvatar accent={profile?.theme_color} />}
  </span>
}

async function loadShareImage(source) {
  if (!source) return null
  try {
    const normalizedSource = new URL(source, window.location.href).href
    let blob
    try {
      const { data, error, response } = await supabase.functions.invoke('igdb-proxy', { body: { imageUrl: normalizedSource } })
      if (error) throw error
      const imageType = response?.headers?.get('x-image-content-type') || 'image/jpeg'
      blob = data instanceof Blob ? new Blob([data], { type: imageType }) : data ? new Blob([data], { type: imageType }) : null
    } catch {
      const response = await fetch(normalizedSource, { mode: 'cors', credentials: 'omit', referrerPolicy: 'no-referrer' })
      if (!response.ok) return null
      blob = await response.blob()
    }
    if (!blob?.type?.startsWith('image/')) return null
    const dataUrl = await new Promise((resolve, reject) => {
      const reader = new FileReader()
      reader.onload = () => resolve(reader.result)
      reader.onerror = reject
      reader.readAsDataURL(blob)
    })
    const image = new Image()
    await new Promise((resolve, reject) => {
      image.onload = resolve
      image.onerror = reject
      image.src = dataUrl
    })
    return image
  } catch { return null }
}

function wrapCanvasText(ctx, text, maxWidth) {
  const lines = []
  String(text || '').split(/\s+/).forEach(word => {
    if (!word) return
    if (ctx.measureText(word).width > maxWidth) {
      let fragment = ''
      for (const character of word) {
        const next = fragment + character
        if (fragment && ctx.measureText(next).width > maxWidth) {
          lines.push(fragment)
          fragment = character
        } else fragment = next
      }
      if (fragment) lines.push(fragment)
      return
    }
    const current = lines.at(-1)
    const candidate = current ? `${current} ${word}` : word
    if (current && ctx.measureText(candidate).width > maxWidth) lines.push(word)
    else if (current) lines[lines.length - 1] = candidate
    else lines.push(word)
  })
  return lines
}

function canvasRoundedRect(ctx, x, y, width, height, radius) {
  if (ctx.roundRect) {
    ctx.roundRect(x, y, width, height, radius)
    return
  }
  const r = Math.min(radius, width / 2, height / 2)
  ctx.moveTo(x + r, y)
  ctx.arcTo(x + width, y, x + width, y + height, r)
  ctx.arcTo(x + width, y + height, x, y + height, r)
  ctx.arcTo(x, y + height, x, y, r)
  ctx.arcTo(x, y, x + width, y, r)
  ctx.closePath()
}

function drawShareStar(ctx, x, y, radius, fillAmount, color) {
  const points = []
  for (let index = 0; index < 10; index += 1) {
    const angle = -Math.PI / 2 + index * Math.PI / 5
    const pointRadius = index % 2 === 0 ? radius : radius * .46
    points.push([x + Math.cos(angle) * pointRadius, y + Math.sin(angle) * pointRadius])
  }
  ctx.beginPath()
  points.forEach(([pointX, pointY], index) => index ? ctx.lineTo(pointX, pointY) : ctx.moveTo(pointX, pointY))
  ctx.closePath()
  ctx.strokeStyle = color
  ctx.lineWidth = 1.8
  ctx.stroke()
  if (fillAmount > 0) {
    ctx.save()
    ctx.clip()
    ctx.fillStyle = color
    ctx.fillRect(x - radius, y - radius, radius * 2 * Math.min(1, fillAmount), radius * 2)
    ctx.restore()
  }
}

async function createReviewShareImage({ authorName, username, avatarUrl, accent, workName, workYear, workType, coverUrl, rating, reviewText }) {
  await document.fonts?.ready
  const titleStyle = getComputedStyle(document.querySelector('.review-post-work-title') || document.body)
  const reviewStyle = getComputedStyle(document.querySelector('.review-post-text') || document.body)
  const headingStyle = getComputedStyle(document.querySelector('.review-post-review-heading') || document.body)
  const authorStyle = getComputedStyle(document.querySelector('.review-post-author-copy strong') || document.body)
  const brandStyle = getComputedStyle(document.querySelector('.sidebar-brand-name') || document.body)
  const accentProbe = document.createElement('span')
  accentProbe.style.color = accent
  document.body.appendChild(accentProbe)
  const canvasAccent = getComputedStyle(accentProbe).color || '#14b8a6'
  accentProbe.remove()
  const cover = await loadShareImage(coverUrl)
  const avatar = await loadShareImage(avatarUrl)
  const canvas = document.createElement('canvas')
  const width = 960
  const sideMargin = 58
  const coverX = sideMargin
  const coverY = 174
  const coverWidth = 270
  const coverHeight = 372
  const copyX = 365
  const copyWidth = width - copyX - sideMargin
  const completeReview = String(reviewText || '').trim()
  // Match the normal review preview length and keep the exported card at a fixed size.
  const review = completeReview.slice(0, 460)
  const measure = canvas.getContext('2d')
  const titleFamily = titleStyle.fontFamily || 'Arial, sans-serif'
  const reviewFamily = reviewStyle.fontFamily || 'Arial, sans-serif'
  const authorFamily = authorStyle.fontFamily || titleFamily
  const headingFamily = headingStyle.fontFamily || titleFamily
  const brandFamily = brandStyle.fontFamily || titleFamily
  measure.font = `400 25px ${reviewFamily}`
  const lines = wrapCanvasText(measure, review, copyWidth)
  const visibleLines = lines.slice(0, 8)
  const reviewIsTruncated = completeReview.length > review.length || lines.length > visibleLines.length
  const height = 900
  canvas.width = width
  canvas.height = height
  const ctx = canvas.getContext('2d')

  ctx.fillStyle = '#0a0a0a'
  ctx.fillRect(0, 0, width, height)
  if (cover) {
    ctx.save()
    ctx.filter = 'blur(74px)'
    ctx.globalAlpha = .32
    ctx.drawImage(cover, -80, -80, width + 160, height + 160)
    ctx.restore()
    ctx.fillStyle = 'rgba(5, 6, 9, .84)'
    ctx.fillRect(0, 0, width, height)
  }
  const glow = ctx.createRadialGradient(680, 110, 0, 680, 110, 600)
  glow.addColorStop(0, canvasAccent)
  glow.addColorStop(1, 'rgba(10,10,10,0)')
  ctx.globalAlpha = .16
  ctx.fillStyle = glow
  ctx.fillRect(0, 0, width, height)
  ctx.globalAlpha = 1

  const avatarX = sideMargin
  const avatarY = 57
  const avatarSize = 62
  if (avatar) {
    ctx.save()
    ctx.beginPath()
    ctx.arc(avatarX + avatarSize / 2, avatarY + avatarSize / 2, avatarSize / 2, 0, Math.PI * 2)
    ctx.clip()
    ctx.drawImage(avatar, avatarX, avatarY, avatarSize, avatarSize)
    ctx.restore()
  } else {
    ctx.fillStyle = 'rgba(255,255,255,.1)'
    ctx.beginPath()
    ctx.arc(avatarX + avatarSize / 2, avatarY + avatarSize / 2, avatarSize / 2, 0, Math.PI * 2)
    ctx.fill()
  }
  ctx.strokeStyle = canvasAccent
  ctx.lineWidth = 3
  ctx.beginPath()
  ctx.arc(avatarX + avatarSize / 2, avatarY + avatarSize / 2, avatarSize / 2 - 1.5, 0, Math.PI * 2)
  ctx.stroke()
  ctx.fillStyle = '#f4f4f5'
  ctx.font = `${authorStyle.fontWeight || 700} 24px ${authorFamily}`
  ctx.fillText(authorName || 'Usuario', avatarX + avatarSize + 20, 77, width - avatarX - avatarSize - 40)
  ctx.fillStyle = '#a1a1aa'
  ctx.font = `400 17px ${authorFamily}`
  ctx.fillText(`@${username || 'usuario'}`, avatarX + avatarSize + 20, 105, width - avatarX - avatarSize - 40)
  ctx.fillStyle = 'rgba(255,255,255,.12)'
  ctx.fillRect(sideMargin, 143, width - sideMargin * 2, 1)

  ctx.fillStyle = 'rgba(0,0,0,.32)'
  ctx.beginPath()
  canvasRoundedRect(ctx, coverX + 7, coverY + 10, coverWidth, coverHeight, 16)
  ctx.fill()
  if (cover) {
    ctx.save()
    ctx.translate(coverX + coverWidth / 2, coverY + coverHeight / 2)
    ctx.rotate(-.035)
    ctx.beginPath()
    canvasRoundedRect(ctx, -coverWidth / 2, -coverHeight / 2, coverWidth, coverHeight, 15)
    ctx.clip()
    const scale = Math.max(coverWidth / cover.width, coverHeight / cover.height)
    const drawWidth = cover.width * scale
    const drawHeight = cover.height * scale
    ctx.drawImage(cover, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight)
    ctx.restore()
  } else {
    ctx.fillStyle = 'rgba(255,255,255,.08)'
    ctx.beginPath()
    canvasRoundedRect(ctx, coverX, coverY, coverWidth, coverHeight, 15)
    ctx.fill()
  }

  const titleText = workName || 'Obra'
  let titleSize = 40
  const titleWeight = titleStyle.fontWeight || 700
  let titleLines
  do {
    ctx.font = `${titleWeight} ${titleSize}px ${titleFamily}`
    titleLines = wrapCanvasText(ctx, titleText, copyWidth)
    if (titleLines.length > 2 && titleSize > 30) titleSize -= 2
    else break
  } while (titleSize > 28)
  const titleWasClipped = titleLines.length > 2
  titleLines = titleLines.slice(0, 2)
  if (titleWasClipped && titleLines.length) {
    let last = titleLines[titleLines.length - 1]
    while (last && ctx.measureText(`${last}…`).width > copyWidth) last = last.slice(0, -1)
    titleLines[titleLines.length - 1] = `${last}…`
  }
  ctx.fillStyle = titleStyle.color || '#f5f5f5'
  ctx.font = `${titleWeight} ${titleSize}px ${titleFamily}`
  const titleLineHeight = Math.round(titleSize * 1.18)
  titleLines.forEach((line, index) => ctx.fillText(line, copyX, coverY + 48 + index * titleLineHeight))
  let metaY = coverY + 48 + titleLines.length * titleLineHeight
  if (workYear) {
    ctx.fillStyle = getComputedStyle(document.querySelector('.review-post-year') || document.body).color || '#b4b4bc'
    ctx.font = `500 22px ${reviewFamily}`
    ctx.fillText(String(workYear), copyX, metaY)
    metaY += 44
  }
  if (rating != null) {
    const numericRating = Math.max(0, Math.min(5, Number(rating)))
    for (let index = 0; index < 5; index += 1) drawShareStar(ctx, copyX + 15 + index * 39, metaY - 8, 14, Math.max(0, Math.min(1, numericRating - index)), canvasAccent)
    ctx.fillStyle = '#ededed'
    ctx.font = `700 20px ${reviewFamily}`
    ctx.fillText(numericRating.toFixed(1), copyX + 190, metaY)
    metaY += 55
  } else metaY += 8
  ctx.fillStyle = 'rgba(255,255,255,.13)'
  ctx.fillRect(copyX, metaY, copyWidth, 1)
  metaY += 36
  ctx.fillStyle = headingStyle.color || '#f4f4f5'
  ctx.font = `${headingStyle.fontWeight || 700} 22px ${headingFamily}`
  ctx.fillText(`Review de ${authorName || 'Usuario'}`, copyX, metaY)
  metaY += 38
  ctx.fillStyle = reviewStyle.color || '#d3d3d8'
  ctx.font = `${reviewStyle.fontWeight || 400} 25px ${reviewFamily}`
  visibleLines.forEach((line, index) => {
    let displayLine = line
    if (reviewIsTruncated && index === visibleLines.length - 1) {
      while (displayLine && ctx.measureText(`${displayLine}…`).width > copyWidth) displayLine = displayLine.slice(0, -1)
      displayLine = `${displayLine}…`
    }
    ctx.fillText(displayLine, copyX, metaY + index * 38)
  })

  const footerY = height - 68
  ctx.fillStyle = 'rgba(255,255,255,.12)'
  ctx.fillRect(sideMargin, footerY - 35, width - sideMargin * 2, 1)
  const logo = await loadShareImage('/icons/logo.png')
  const brand = 'GeekSphere'
  ctx.font = `750 25px ${brandFamily}`
  ctx.textAlign = 'right'
  ctx.textBaseline = 'middle'
  ctx.fillStyle = '#ffffff'
  const brandX = width - sideMargin
  const brandWidth = ctx.measureText(brand).width
  ctx.fillText(brand, brandX, footerY)
  if (logo) ctx.drawImage(logo, brandX - brandWidth - 48, footerY - 21, 42, 42)
  ctx.textAlign = 'left'
  ctx.textBaseline = 'alphabetic'

  return await new Promise((resolve, reject) => canvas.toBlob(blob => blob ? resolve(blob) : reject(new Error('No se pudo crear el PNG')), 'image/png'))
}

export default function ReviewDetail() {
  const { reviewId } = useParams()
  const navigate = useNavigate()
  const isStandalonePwa = window.matchMedia('(display-mode: standalone), (display-mode: fullscreen)').matches || navigator.standalone === true
  const [isExitingPwa, setIsExitingPwa] = useState(false)
  const handleBack = () => { if (!isStandalonePwa) return navigateBackOrHome(navigate); setIsExitingPwa(true); window.setTimeout(() => navigateBackOrHome(navigate), 280) }
  const { user, profile: currentProfile, updateProfile } = useAuth()
  const [review, setReview] = useState(null)
  const [loading, setLoading] = useState(true)
  const systemBarColor = useSystemBarColor(getVisibleAccentColor(review?.profile?.theme_color || '#14b8a6'))
  const [comments, setComments] = useState([])
  const [commentText, setCommentText] = useState('')
  const commentInputRef = useRef(null)
  useEffect(() => { if (!loading) signalPwaRouteReady(`/reviews/${reviewId}`) }, [loading, reviewId])
  const [commentsLoading, setCommentsLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const [commentsError, setCommentsError] = useState('')
  const [showSpoiler, setShowSpoiler] = useState(false)
  const [showFullReview, setShowFullReview] = useState(false)
  const [existingLog, setExistingLog] = useState(null)
  const [showLogModal, setShowLogModal] = useState(false)
  const [shareOpen, setShareOpen] = useState(false)
  const [shareCopied, setShareCopied] = useState(false)
  const [shareBusy, setShareBusy] = useState(false)
  const [pendingDelete, setPendingDelete] = useState(null)
  const [replyTo, setReplyTo] = useState(null)
  const [editingCommentId, setEditingCommentId] = useState(null)
  const [editingText, setEditingText] = useState('')
  const [savingCommentEdit, setSavingCommentEdit] = useState(false)
  const deleteTimerRef = useRef(null)
  const mountedRef = useRef(true)
  useAutoResizeTextarea(commentInputRef, commentText)

  useEffect(() => {
    mountedRef.current = true
    return () => { mountedRef.current = false }
  }, [])

  const loadComments = useCallback(async () => {
    setCommentsLoading(true)
    setCommentsError('')
    try {
      setComments(await getLibraryReviewComments(reviewId))
    } catch (err) {
      console.error('Error loading review comments:', err)
      setCommentsError('No se pudieron cargar los comentarios.')
    } finally {
      setCommentsLoading(false)
    }
  }, [reviewId])

  useEffect(() => {
    let active = true
    setLoading(true)
    setError('')
    setReview(null)
    setShowSpoiler(false)
    setShowFullReview(false)
    getLibraryReview(reviewId)
      .then(data => { if (active) setReview(data) })
      .catch(err => {
        console.error('Error loading review:', err)
        if (active) setError('No se pudo cargar esta review.')
      })
      .finally(() => { if (active) setLoading(false) })
    return () => { active = false }
  }, [reviewId])

  useEffect(() => {
    loadComments()
  }, [loadComments])

  useEffect(() => {
    if (!shareOpen) return undefined
    const closeOnEscape = event => { if (event.key === 'Escape') setShareOpen(false) }
    document.addEventListener('keydown', closeOnEscape)
    return () => document.removeEventListener('keydown', closeOnEscape)
  }, [shareOpen])

  useEffect(() => {
    let active = true
    if (!user?.id || !review?.work_id || !review?.work_type) {
      setExistingLog(null)
      return undefined
    }
    getWorkLog(user.id, Number(review.work_id), review.work_type)
      .then(log => { if (active) setExistingLog(log) })
      .catch(err => console.error('Error loading user work entry:', err))
    return () => { active = false }
  }, [user?.id, review?.work_id, review?.work_type])

  const handleSubmit = async event => {
    event.preventDefault()
    if (!user || !commentText.trim() || submitting) return
    setSubmitting(true)
    setCommentsError('')
    try {
      const comment = await addLibraryReviewComment(reviewId, user.id, commentText, replyTo?.id || null)
      setComments(current => [...current, comment].sort((a, b) => new Date(a.created_at) - new Date(b.created_at)))
      setCommentText('')
      setReplyTo(null)
    } catch (err) {
      console.error('Error posting review comment:', err)
      setCommentsError(err.message || 'No se pudo publicar el comentario.')
    } finally {
      setSubmitting(false)
    }
  }

  const handleDeleteComment = async comment => {
    if (!user || comment.user_id !== user.id || pendingDelete) return
    setComments(current => current.filter(item => item.id !== comment.id))
    setPendingDelete(comment)
    deleteTimerRef.current = setTimeout(async () => {
      if (mountedRef.current) setPendingDelete(current => current?.id === comment.id ? null : current)
      try {
        await deleteLibraryReviewComment(comment.id, user.id)
        if (mountedRef.current) setComments(current => current.map(item => item.parent_comment_id === comment.id ? { ...item, parent_comment_id: null } : item))
      } catch (err) {
        console.error('Error deleting review comment:', err)
        if (mountedRef.current) {
          setComments(current => [...current, comment].sort((a, b) => new Date(a.created_at) - new Date(b.created_at)))
          setCommentsError('No se pudo eliminar el comentario.')
        }
      } finally {
        deleteTimerRef.current = null
      }
    }, 4000)
  }

  const handleUndoDelete = () => {
    if (!pendingDelete) return
    clearTimeout(deleteTimerRef.current)
    deleteTimerRef.current = null
    setComments(current => [...current, pendingDelete].sort((a, b) => new Date(a.created_at) - new Date(b.created_at)))
    setPendingDelete(null)
  }

  const handleUpdateComment = async (event, comment) => {
    event.preventDefault()
    if (!user || savingCommentEdit) return
    setSavingCommentEdit(true)
    setCommentsError('')
    try {
      const updated = await updateLibraryReviewComment(comment.id, user.id, editingText)
      setComments(current => current.map(item => item.id === updated.id ? updated : item))
      setEditingCommentId(null)
      setEditingText('')
    } catch (err) {
      console.error('Error editing review comment:', err)
      setCommentsError(err.message || 'No se pudo editar el comentario.')
    } finally {
      setSavingCommentEdit(false)
    }
  }

  if (loading) return isStandalonePwa ? null : <LoadingSpinner />
  if (error || !review) {
    return <main className={`review-detail-page${isStandalonePwa ? ' pwa-detail-screen' : ''}`} style={{ '--pwa-system-bar-color': systemBarColor, '--review-page-accent': '#14b8a6' }}><div className="review-detail-state"><h1>{error ? 'Error al cargar la review' : 'Review no encontrada'}</h1><Link to="/search">Volver a descubrir</Link></div></main>
  }

  const author = review.profile
  const workName = review.work_type === 'game' ? review.work?.name : review.work?.title
  const reviewText = String(review.review_text || '')
  const reviewTextLimit = 460
  const shouldTrimReview = reviewText.length > reviewTextLimit
  const reviewPreviewEnd = shouldTrimReview ? reviewText.lastIndexOf(' ', reviewTextLimit) : reviewText.length
  const reviewPreview = shouldTrimReview && reviewPreviewEnd > 300 ? reviewText.slice(0, reviewPreviewEnd).trimEnd() : reviewText.slice(0, reviewTextLimit).trimEnd()
  const reviewPreviewText = shouldTrimReview && !showFullReview ? `${reviewPreview}… Ver más` : reviewText
  const workCover = review.work_type === 'game' ? review.work?.cover_url : review.work?.image_url
  const reviewBackdrop = workCover
  const shareCover = getReviewShareCover(workCover)
  const workYear = getReleaseYear(review.work, review.work_type)
  const workPath = `/${review.work_type === 'game' ? 'game' : 'anime'}/${review.work_id}`
  const authorName = author?.display_name || author?.username || 'Usuario'
  const authorPath = author?.username ? `/profile/${author.username}` : '/profile'
  const pageAccent = getVisibleAccentColor(author?.theme_color || '#14b8a6')
  const wishlist = currentProfile?.wishlist || []
  const wishlistIndex = wishlist.findIndex(item => String(item.id) === String(review.work_id) && item.type === review.work_type)
  const isInWishlist = wishlistIndex >= 0
  const shareUrl = window.location.href
  const encodedShareUrl = encodeURIComponent(shareUrl)
  const shareTitle = `Review de ${authorName}: ${workName || 'una obra'}`
  const encodedShareTitle = encodeURIComponent(shareTitle)

  const copyReviewLink = async () => {
    try {
      if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(shareUrl)
      else {
        const input = document.createElement('textarea')
        input.value = shareUrl
        input.style.position = 'fixed'
        input.style.opacity = '0'
        document.body.appendChild(input)
        input.select()
        document.execCommand('copy')
        input.remove()
      }
      setShareCopied(true)
      window.setTimeout(() => setShareCopied(false), 1800)
    } catch (err) {
      console.error('No se pudo copiar el enlace de la review', err)
    }
  }

  const downloadReviewImage = async () => {
    if (shareBusy) return
    setShareBusy(true)
    try {
      const image = await createReviewShareImage({
        authorName,
        username: author?.username,
        avatarUrl: author?.avatar_url,
        accent: pageAccent,
        workName,
        workYear,
        workType: review.work_type,
        coverUrl: shareCover,
        rating: review.rating,
        reviewText,
      })
      const imageUrl = URL.createObjectURL(image)
      const link = document.createElement('a')
      link.href = imageUrl
      link.download = `review-${String(workName || 'obra').trim().toLowerCase().replace(/[^a-z0-9]+/gi, '-')}.png`
      link.click()
      window.setTimeout(() => URL.revokeObjectURL(imageUrl), 1500)
    } catch (err) {
      console.error('No se pudo generar la imagen de la review', err)
      window.alert('No se pudo generar la imagen de la review. Inténtalo de nuevo.')
    } finally {
      setShareBusy(false)
    }
  }

  const toggleWishlist = async () => {
    if (!user) {
      navigate('/register')
      return
    }
    if (!currentProfile) {
      navigate('/onboarding')
      return
    }
    if (!review.work) return
    const updatedWishlist = [...wishlist]
    if (isInWishlist) updatedWishlist.splice(wishlistIndex, 1)
    else updatedWishlist.push({
      id: String(review.work_id),
      type: review.work_type,
      title: workName || 'Obra',
      image_url: workCover,
      added_at: new Date().toISOString(),
    })
    try {
      await updateProfile({ wishlist: updatedWishlist })
    } catch (err) {
      console.error('Error updating wishlist:', err)
    }
  }

  const openLogModal = () => {
    if (!user) {
      navigate('/register')
      return
    }
    if (!currentProfile) {
      navigate('/onboarding')
      return
    }
    navigatePwaRoute(navigate, '/share', { state: { reviewWork: {
      id: Number(review.work_id),
      type: review.work_type,
      title: workName || 'Obra',
      image: workCover,
    } } })
  }

  const handleLogSaved = savedLog => {
    setExistingLog(savedLog)
    setShowLogModal(false)
  }
  const commentComposer = user && currentProfile && <form className={`review-comment-form${isStandalonePwa ? ' pwa-comment-composer' : ''}`} style={isStandalonePwa ? { '--comment-accent': currentProfile.theme_color || 'var(--brand-primary)', '--comment-accent-ink': getAccentTextColor(currentProfile.theme_color || '#14b8a6') } : undefined} onSubmit={handleSubmit}>
    <ProfileAvatar profile={currentProfile} size="small" />
    <label className="review-comment-input-wrap"><textarea ref={commentInputRef} aria-label="Escribe un comentario" value={commentText} onChange={event => setCommentText(event.target.value)} maxLength={300} rows={1} placeholder="Escribe un comentario…" /></label>
    <button type="submit" disabled={!commentText.trim() || submitting} aria-label={isStandalonePwa ? (submitting ? 'Enviando comentario' : 'Enviar comentario') : undefined}>{isStandalonePwa ? <><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M22 2 11 13"/><path d="m22 2-7 20-4-9-9-4Z"/></svg><span>{submitting ? 'Enviando…' : 'Enviar'}</span></> : submitting ? 'Enviando…' : 'Comentar'}</button>
  </form>

  return (
    <main className={`review-detail-page${isStandalonePwa ? ' pwa-detail-screen' : ''}${isExitingPwa ? ' is-exiting' : ''}`} style={{ '--pwa-system-bar-color': systemBarColor, '--review-page-accent': pageAccent, '--review-backdrop-image': reviewBackdrop ? `url("${reviewBackdrop}")` : 'none' }}>
      <SEO title={`${authorName}: review de ${workName || 'una obra'}`} description={review.review_text.slice(0, 150)} />
      <div className="review-pwa-topbar">
        <button className="review-detail-back" type="button" aria-label="Volver" onClick={handleBack}>
          <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg>Volver
        </button>
      </div>

      <article className="review-post">
        <header className="review-post-header">
          <Link to={authorPath} className="review-post-author">
            <ProfileAvatar profile={author} />
            <span className="review-post-author-copy">
              <strong>{authorName}</strong>
              {author?.username && <span>@{author.username}</span>}
            </span>
          </Link>
          {review.finished_date && <time className="review-post-finished" dateTime={review.finished_date}>Terminada el {new Date(review.finished_date).toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' })}</time>}
        </header>

        <div className="review-post-main">
          <div className="review-post-copy">
            <Link className="review-post-work-title" to={workPath}>{workName || 'Obra'}</Link>
            <div className="review-post-year-row">
              {workYear && <span className="review-post-year">{workYear}</span>}
            </div>
            <div className="review-post-rating-row">
              <ReviewStars rating={review.rating} />
              <div className="review-post-work-actions">
                <button type="button" className="review-work-action primary" onClick={openLogModal}>
                  <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>
                  {existingLog ? 'Editar registro' : 'Registrar obra'}
                </button>
                <button type="button" className={`review-work-action${isInWishlist ? ' selected' : ''}`} onClick={toggleWishlist} title={isInWishlist ? 'Quitar de la wishlist' : 'Añadir a la wishlist'}>
                  <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 4.75A1.75 1.75 0 0 1 7.75 3h8.5A1.75 1.75 0 0 1 18 4.75V21l-6-4-6 4z"/></svg>
                  {isInWishlist ? 'En wishlist' : 'Wishlist'}
                </button>
              </div>
            </div>
            <h2 className="review-post-review-heading">Review de {authorName}</h2>
            {review.contains_spoiler && !showSpoiler ? (
              <SpoilerNotice text={reviewPreviewText} onReveal={() => setShowSpoiler(true)} />
            ) : <>
              <p className="review-post-text">{shouldTrimReview && !showFullReview ? `${reviewPreview}…` : reviewText}</p>
              {shouldTrimReview && <button type="button" className="review-post-more" onClick={() => setShowFullReview(value => !value)}>{showFullReview ? 'Ver menos' : 'Ver más'}</button>}
            </>}
          </div>
          <Link to={workPath} className="review-post-cover" aria-label={`Ver ${workName || 'la obra'}`}>
            {workCover ? <img src={workCover} alt={`Portada de ${workName || 'la obra'}`} /> : <span>Sin portada</span>}
          </Link>
        </div>

        <div className="review-post-actions">
          <ReviewLikeButton entryId={review.id} />
          <span className="review-post-action-spacer" />
          <button type="button" className="review-post-action upcoming" disabled title="Guardar reviews estará disponible próximamente">
            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 4.75A1.75 1.75 0 0 1 7.75 3h8.5A1.75 1.75 0 0 1 18 4.75V21l-6-4-6 4z"/></svg>Guardar
          </button>
          <button type="button" className="review-post-action upcoming" disabled title="Repostear estará disponible próximamente">
            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m17 2 4 4-4 4M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4M21 13v2a3 3 0 0 1-3 3H3"/></svg>Repostear
          </button>
          <button type="button" className="review-post-action review-share-trigger" onClick={() => setShareOpen(true)} aria-label="Compartir review">
            <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.7 10.7 6.6-4.4M8.7 13.3l6.6 4.4"/></svg>Compartir
          </button>
        </div>

      <section className="review-comments" aria-labelledby="review-comments-title">
        <div className="review-comments-heading"><h2 id="review-comments-title">Comentarios</h2></div>
        {commentsError && <div className="review-comments-error" role="alert">{commentsError}{commentsError.includes('cargar') && <button type="button" onClick={loadComments}>Reintentar</button>}</div>}
        {commentsLoading ? <div className="review-comments-loading">Cargando comentarios…</div> : comments.length === 0 ? <div className="review-comments-empty">No hay comentarios.</div> : (
          <div className="review-comments-list">
            {comments.map(comment => {
              const name = comment.profile?.display_name || comment.profile?.username || 'Usuario'
              const isOwnComment = user?.id === comment.user_id
              const isEditing = editingCommentId === comment.id
              const hasReplies = comments.some(item => item.parent_comment_id === comment.id)
              return <article className={`review-comment${comment.parent_comment_id ? ' is-reply' : ''}${hasReplies ? ' has-replies' : ''}`} key={comment.id}>
                <Link to={comment.profile?.username ? `/profile/${comment.profile.username}` : '/profile'} className="review-comment-avatar-link"><ProfileAvatar profile={comment.profile} size="small" /></Link>
                <div className="review-comment-body">
                  <div className="review-comment-topline"><Link to={comment.profile?.username ? `/profile/${comment.profile.username}` : '/profile'}>{name}</Link><time dateTime={comment.created_at}>{formatRelativeDate(comment.created_at)}</time></div>
                  {isEditing ? (
                    <form className="review-comment-edit-form" onSubmit={event => handleUpdateComment(event, comment)}>
                      <textarea aria-label="Editar comentario" value={editingText} onChange={event => setEditingText(event.target.value)} maxLength={300} rows={2} />
                      <div><button type="button" onClick={() => { setEditingCommentId(null); setEditingText('') }}>Cancelar</button><button type="submit" disabled={!editingText.trim() || savingCommentEdit}>{savingCommentEdit ? 'Guardando…' : 'Guardar'}</button></div>
                    </form>
                  ) : <>
                    <p>{comment.content}</p>
                    <div className="review-comment-actions">
                      {user && <button type="button" onClick={() => { setReplyTo(comment); setCommentText('') }}>Responder</button>}
                      {isOwnComment && <>
                        <button type="button" onClick={() => { setEditingCommentId(comment.id); setEditingText(comment.content) }}>Editar</button>
                        <button type="button" onClick={() => handleDeleteComment(comment)} disabled={Boolean(pendingDelete)}>Eliminar</button>
                      </>}
                    </div>
                  </>}
                </div>
              </article>
            })}
          </div>
        )}
        {user && currentProfile ? (
          <>
          {replyTo && <div className="review-comment-reply-context">Respondiendo a {replyTo.profile?.display_name || replyTo.profile?.username || 'Usuario'}<button type="button" onClick={() => setReplyTo(null)}>Cancelar</button></div>}
          {isStandalonePwa ? createPortal(commentComposer, document.body) : commentComposer}
          </>
        ) : <p className="review-comments-signin"><Link to={user ? '/onboarding' : '/register'}>Inicia sesión para comentar</Link></p>}
      </section>
      {pendingDelete && <div className="review-comment-undo-toast" role="status"><span>Comentario borrado</span><button type="button" onClick={handleUndoDelete}>Deshacer</button></div>}
      </article>
      {shareOpen && createPortal((
        <div className={`review-share-overlay${isStandalonePwa ? ' pwa-prompt-overlay' : ''}`} onClick={() => setShareOpen(false)}>
          <section className="review-share-dialog" style={{ '--review-page-accent': pageAccent }} role="dialog" aria-modal="true" aria-labelledby="review-share-title" onClick={event => event.stopPropagation()}>
            <header className="review-share-heading">
              <div><span className="review-share-eyebrow">COMPARTIR REVIEW</span><h2 id="review-share-title">Una opinión que merece compartirse</h2></div>
              <button className="review-share-close" type="button" onClick={() => setShareOpen(false)} aria-label="Cerrar menú de compartir"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m18 6-12 12M6 6l12 12"/></svg></button>
            </header>
            <div className="review-share-preview">
              <div className="review-share-preview-cover">{shareCover && <img src={shareCover} alt="" />}</div>
              <div className="review-share-preview-copy">
                <div className="review-share-preview-author"><ProfileAvatar profile={author} size="small" /><span>{authorName}<small>@{author?.username || 'usuario'}</small></span></div>
                <strong>{workName || 'Review'}</strong>
                <span>{review.work_type === 'game' ? 'Videojuego' : 'Anime'}{workYear ? ` · ${workYear}` : ''}</span>
                <ReviewStars rating={review.rating} />
              </div>
            </div>
            <button className="review-share-link" type="button" onClick={copyReviewLink} aria-label="Copiar enlace de la review">
              <span>{shareCopied ? 'ENLACE COPIADO' : 'ENLACE DE LA REVIEW'}</span><strong>{shareUrl}</strong>
              <i>{shareCopied ? '✓' : '↗'}</i>
            </button>
            <div className="review-share-section-label">Compartir directamente</div>
            <div className="review-share-networks">
              <a className="whatsapp" href={`https://wa.me/?text=${encodedShareTitle}%20${encodedShareUrl}`} target="_blank" rel="noreferrer"><b><FaWhatsapp /></b><span>WhatsApp</span></a>
              <a className="x-twitter" href={`https://twitter.com/intent/tweet?text=${encodedShareTitle}&url=${encodedShareUrl}`} target="_blank" rel="noreferrer"><b><FaXTwitter /></b><span>X</span></a>
              <a className="telegram" href={`https://t.me/share/url?url=${encodedShareUrl}&text=${encodedShareTitle}`} target="_blank" rel="noreferrer"><b><FaTelegram /></b><span>Telegram</span></a>
              <a className="reddit" href={`https://www.reddit.com/submit?url=${encodedShareUrl}&title=${encodedShareTitle}`} target="_blank" rel="noreferrer"><b><FaRedditAlien /></b><span>Reddit</span></a>
              <a className="facebook" href={`https://www.facebook.com/sharer/sharer.php?u=${encodedShareUrl}`} target="_blank" rel="noreferrer"><b><FaFacebookF /></b><span>Facebook</span></a>
            </div>
            <div className="review-share-divider" />
            <button className="review-share-download" type="button" onClick={downloadReviewImage} disabled={shareBusy}>
              <span className="review-share-download-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3"/></svg></span>
              <span><strong>{shareBusy ? 'Preparando imagen…' : 'Descargar imagen'}</strong><small>Una tarjeta con la portada, nota y tu reseña</small></span>
              <svg className="review-share-download-arrow" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg>
            </button>
          </section>
        </div>
      ), document.body)}
      {showLogModal && <LogModal
        isOpen={showLogModal}
        onClose={() => setShowLogModal(false)}
        work={{ id: Number(review.work_id), type: review.work_type, title: workName, image: workCover, banner_url: review.work?.banner_url }}
        existingLog={existingLog}
        onSaveComplete={handleLogSaved}
      />}
    </main>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Link, useLocation, useNavigate, useSearchParams } from 'react-router-dom'
import { getSearchHighlights, searchPlatform } from '../lib/platformSearchService'
import { getSearchRecommendations } from '../lib/searchRecommendationsService'
import { getDiscoverLists } from '../lib/listService'
import { useAuth } from '../context/AuthContext'
import DefaultAvatar from '../components/DefaultAvatar'
import { hasCustomAvatar } from '../lib/avatar'
import { isStandalonePwa } from '../lib/pwaRouteTransition'
import SEO from '../components/SEO'
import { AlignmentIcon } from '../components/AlignmentBoard'
import { listTypeLabel } from '../lib/listTypes'
import './Search.css'

const FILTERS = [
  { id: 'all', label: 'All' }, { id: 'game', label: 'Games' }, { id: 'anime', label: 'Anime' },
  { id: 'spaces', label: 'Spaces' }, { id: 'lists', label: 'Lists' }, { id: 'users', label: 'Users' },
]
const FILTER_IDS = new Set(FILTERS.map(filter => filter.id))
const CATEGORY_LABELS = { works: 'Obras', spaces: 'Espacios', users: 'Usuarios', lists: 'Listas' }
const MAX_SEARCH_LISTS = 4
const nameOf = item => item.title || item.name || item.display_name || item.username || 'Sin nombre'

function resultHref(item) {
  if (item.type === 'list') return `/lists/${item.id}`
  if (item.type === 'game') return `/game/${item.id}`
  if (item.type === 'anime') return `/anime/${item.id}`
  if (item.username) return `/profile/${item.username}`
  return `/spaces/${item.id}`
}

function getListCollageImages(content) {
  const images = []
  const addImage = item => {
    if (!item) return
    const image = item.image_url || item.cover_url || item.cover?.url
    if (image && !images.includes(image)) images.push(image)
  }
  const priorities = ['S', '#1', 'Top', 'God Tier', 'A', '#2', 'B', '#3', 'C', '#4', 'D', '#5', 'E', 'F']
  const groups = Array.isArray(content) ? [content] : [
    ...priorities.filter(key => content?.[key] != null).map(key => content[key]),
    ...Object.keys(content || {}).filter(key => !priorities.includes(key)).map(key => content[key]),
  ]
  for (const group of groups) {
    for (const item of Array.isArray(group) ? group : [group]) {
      addImage(item)
      if (images.length === 4) return images
    }
  }
  return images
}

function ListPoster({ list, compact = false }) {
  const images = getListCollageImages(list.content)
  const countClass = images.length === 3 ? ' count-three' : images.length === 2 ? ' count-two' : ''
  return <span className={`search-list-poster${compact ? ' compact' : ''}${countClass}`} aria-hidden="true">
    {images.length ? images.map((image, index) => <img key={`${image}-${index}`} src={image} alt="" loading="lazy" />) : <span className="search-list-poster-empty">Lista</span>}
  </span>
}

function resultImage(item) {
  return item.image || item.cover_url || item.image_url || item.avatar_url || null
}

function highResolutionArtwork(item, kind) {
  const src = resultImage(item)
  if (!src) return null
  if (kind === 'games') return src.replace(/\/t_[^/]+\//, '/t_original/')
  if (kind === 'anime') return src.replace('/cover/large/', '/cover/original/').replace('/cover/medium/', '/cover/original/')
  return src
}

function getSecondary(item) {
  if (item.type === 'list') return item.author?.username ? `@${item.author.username}` : '@usuario'
  if (item.type === 'game' || item.type === 'anime') {
    return getYear(item)
  }
  if (item.username) return `@${item.username}`
  if (item.owner_id) return `${item.member_count ?? 0} ${item.member_count === 1 ? 'usuario' : 'usuarios'}`
  return item.description || 'Espacio de la comunidad'
}

function getYear(item) {
  const date = item.release_date || item.first_release_date
  return typeof date === 'number' ? new Date(date * 1000).getFullYear() : date ? String(date).slice(0, 4) : ''
}

function VerifiedBadge({ className = 'search-space-verified' }) {
  return <span className={className} title="Espacio verificado" aria-label="Espacio verificado">
    <svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#1d9bf0" d="M22.5 12.5l-2.43 2.8.57 3.65-3.6.86-2.07 3.14-3.47-1.5-3.47 1.5-2.07-3.14-3.6-.86.57-3.65L.5 12.5l2.43-2.8-.57-3.65 3.6-.86 2.07-3.14 3.47 1.5 3.47-1.5 2.07 3.14 3.6.86-.57 3.65 2.43 2.8z"/><path fill="#fff" d="M10.1 17.6l7.7-7.7-1.4-1.4-6.3 6.3-3-3-1.4 1.4 4.4 4.4z"/></svg>
  </span>
}

function SearchIcon() {
  return <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="7.3"/><path d="m16.2 16.2 4.3 4.3"/></svg>
}

function ResultLink({ item, active, id, onClick, display = 'row' }) {
  const isCard = display === 'card'
  if (item.type === 'list') {
    const listType = listTypeLabel(item.list_type)
    const authorName = item.author?.username || 'usuario'
    const authorAvatar = hasCustomAvatar(item.author?.avatar_url) ? item.author.avatar_url : null
    const typeIcon = item.list_type === 'alignment' ? <AlignmentIcon/> : item.list_type === 'ranking'
      ? <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>
      : item.list_type === 'grid'
        ? <svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/></svg>
        : <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/></svg>
    if (isCard) return <Link id={id} role="option" aria-selected={active} to={resultHref(item)} className={`search-result search-list-result search-list-card${active ? ' is-active' : ''}`} onClick={onClick}>
      <ListPoster list={item}/>
      <span className="search-list-card-content">
        <strong>{nameOf(item)}</strong>
        <span className="search-list-card-author"><span className="search-list-author-avatar">{authorAvatar ? <img src={authorAvatar} alt="" loading="lazy"/> : <DefaultAvatar accent={item.author?.theme_color} />}</span>@{authorName}</span>
        <span className="search-list-tags"><span className={`search-list-tag type-${item.list_type || 'tierlist'}`}>{typeIcon}{listType}</span>{item.list_type !== 'ranking' && item.media_type && <span className={`search-list-tag media-${item.media_type}`}>{item.media_type === 'game' ? 'Videojuegos' : item.media_type === 'anime' ? 'Anime' : item.media_type}</span>}</span>
      </span>
    </Link>
    const username = item.author?.username || 'usuario'
    const avatar = hasCustomAvatar(item.author?.avatar_url) ? item.author.avatar_url : null
    return <Link id={id} role="option" aria-selected={active} to={resultHref(item)} className={`search-result search-list-result search-list-row${active ? ' is-active' : ''}`} onClick={onClick}>
      <ListPoster list={item} compact/>
      <span className="search-result-copy"><strong>{nameOf(item)}</strong><small className="search-list-author"><span className="search-list-author-avatar">{avatar ? <img src={avatar} alt="" loading="lazy"/> : <DefaultAvatar accent={item.author?.theme_color} />}</span><span>@{username}</span></small></span>
      <span className="search-kind list-kind">{listType}</span>
    </Link>
  }
  const image = item.username && !hasCustomAvatar(item.avatar_url)
    ? null
    : isCard && item.owner_id ? item.avatar_url || item.banner_url || resultImage(item) : resultImage(item)
  const title = nameOf(item)
  const imageType = item.type || (item.username ? 'user' : 'space')
  const artwork = image ? <img className={`search-result-image ${imageType}`} src={image} alt="" loading="lazy" /> : item.username ? <DefaultAvatar className="search-result-fallback user" accent={item.theme_color} /> : <span className={`search-result-fallback ${imageType}`} aria-hidden="true">{item.type === 'anime' ? '▣' : item.type === 'game' ? '▤' : '◈'}</span>
  const titleContent = item.owner_id ? <span className="search-space-title-line"><strong>{title}</strong>{item.is_verified && <VerifiedBadge />}</span> : <strong>{title}</strong>
  const profileAccent = item.username ? { '--search-user-accent': item.theme_color || 'var(--brand-primary)' } : undefined
  return <Link id={id} role="option" aria-selected={active} to={resultHref(item)} className={`search-result${active ? ' is-active' : ''}${isCard ? ' search-result-card' : ''}`} onClick={onClick} style={profileAccent}>
    {isCard ? <>
      <span className={`search-result-artwork${item.type ? ' work-artwork' : ' space-artwork'}`}>{artwork}</span>
      <span className="search-result-copy">{titleContent}{item.type && getYear(item) && <small>{getYear(item)}</small>}{item.owner_id && <small>{getSecondary(item)}</small>}</span>
    </> : <>
      {artwork}
      <span className="search-result-copy">{titleContent}{getSecondary(item) && <small>{getSecondary(item)}</small>}</span>
      {(item.type === 'game' || item.type === 'anime') && <span className={`search-kind ${item.type}`}>{item.type === 'game' ? 'VIDEOJUEGO' : 'ANIME'}</span>}
    </>}
  </Link>
}

function SearchInput({ value, onChange, onFocus, onKeyDown, inputRef, resultsId, isOpen, activeDescendant, previewEnabled = true, onCompositionChange }) {
  return <div className="search-input-shell">
    <SearchIcon />
    <input ref={inputRef} type="search" role={previewEnabled ? 'combobox' : undefined} aria-autocomplete={previewEnabled ? 'list' : undefined} aria-expanded={previewEnabled ? isOpen : undefined} aria-controls={previewEnabled ? resultsId : undefined} aria-activedescendant={previewEnabled ? activeDescendant || undefined : undefined} aria-label="Buscar obras, espacios y usuarios" placeholder="Busca cualquier cosa" value={value} onChange={event => onChange(event.target.value)} onFocus={onFocus} onKeyDown={onKeyDown} onCompositionStart={() => onCompositionChange?.(true)} onCompositionEnd={() => onCompositionChange?.(false)} autoComplete="off" />
    {value && <button className="search-clear" type="button" onClick={() => onChange('')} aria-label="Borrar búsqueda">×</button>}
  </div>
}

function SearchSkeleton() {
  return <div className="search-skeleton-list" aria-label="Cargando resultados"><span/><span/><span/><span/></div>
}

function Preview({ query, data, loading, error, activeIndex, onSelect, onViewAll, listRef }) {
  const groups = [
    ['works', data.works.slice(0, 8)], ['spaces', data.spaces.slice(0, 8)], ['lists', data.lists.slice(0, MAX_SEARCH_LISTS)], ['users', data.users.slice(0, 8)],
  ].filter(([, items]) => items?.length)
  const flat = groups.flatMap(([, items]) => items)
  return <div className="search-preview" ref={listRef} id="search-preview" role="listbox" aria-label="Resultados sugeridos">
    {loading && <SearchSkeleton />}
    {!loading && groups.map(([key, items]) => <section className="search-preview-group" key={key} aria-label={CATEGORY_LABELS[key]}>
      <h3>{CATEGORY_LABELS[key]}<span>{items.length}</span></h3>
      {items.map(item => <ResultLink key={`${item.type || key}-${item.id}`} item={item} id={`search-option-${flat.indexOf(item)}`} active={activeIndex === flat.indexOf(item)} onClick={onSelect} />)}
      {data.errors?.[key] && <p className="search-inline-error">No se pudo cargar esta categoría.</p>}
    </section>)}
    {!loading && Object.keys(data.errors || {}).length > 0 && <p className="search-preview-error">Algunos resultados no están disponibles ahora mismo.</p>}
    {!loading && !flat.length && (error ? <p className="search-preview-empty">No se han podido cargar los resultados. Inténtalo de nuevo.</p> : <p className="search-preview-empty">No hay resultados para «{query}».</p>)}
    {!loading && <button id="search-view-all" type="button" className={`search-view-all${activeIndex === flat.length ? ' is-active' : ''}`} role="option" aria-selected={activeIndex === flat.length} onClick={onViewAll}>
      Ver todo sobre «{query}»
    </button>}
  </div>
}

function CategoryCard({ kind, title, items, to, wide = false }) {
  const entries = items || []
  const visuals = kind === 'users' || kind === 'spaces' ? entries.slice(0, 3) : entries.slice(0, wide ? 3 : 2)
  return <Link to={to} className={`search-category-card${wide ? ' wide' : ''} ${kind}`}>
    <span className="category-art" aria-hidden="true">
      {kind === 'lists' ? <span className="category-art-list-icons">
        <svg className="list-type-tier" viewBox="0 0 24 24"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>
        <svg className="list-type-ranking" viewBox="0 0 24 24"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/></svg>
        <svg className="list-type-grid" viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/></svg>
      </span> : null}
      {visuals.length ? visuals.map((item, index) => {
        const image = highResolutionArtwork(item, kind)
        return <span className={`category-art-tile tile-${index + 1}`} key={item.id || index}>{image ? <img src={image} alt="" loading="lazy" decoding="async" onError={event => { if (event.currentTarget.src !== resultImage(item)) event.currentTarget.src = resultImage(item) }}/> : <span>{kind === 'anime' ? '▣' : kind === 'games' ? '▤' : kind === 'users' ? '◎' : '◈'}</span>}</span>
      }) : kind === 'users' ? <span className="category-art-people-fallback"><span>◎</span><span>◎</span><span>◎</span></span> : kind !== 'lists' ? <span className="category-art-fallback">{kind === 'anime' ? '▣' : kind === 'games' ? '▤' : '◈'}</span> : null}
    </span>
    <span className="category-card-copy"><strong>{title}</strong></span>
  </Link>
}

function SpotlightRow({ kind, items = [], loading = false, isLoggedIn = false }) {
  const people = kind === 'people'
  const orderedItems = people ? [...items].sort((a, b) => (isLoggedIn ? b.commonWorks || 0 : b.registeredWorks || 0) - (isLoggedIn ? a.commonWorks || 0 : a.registeredWorks || 0)) : items
  const title = people ? 'Personas' : 'Espacios'
  const href = people ? '/discover/users' : '/discover/spaces'
  const mobileItems = orderedItems.slice(0, 3)
  return <section className={`search-spotlight ${kind}`} aria-labelledby={`search-${kind}-title`}>
    <Link to={href} className={`search-spotlight-mobile-link ${people ? 'people' : 'spaces'}`}>
      <span className="search-spotlight-mobile-avatars" aria-hidden="true">
        {(mobileItems.length ? mobileItems : Array.from({ length: 3 }, (_, index) => ({ id: `loading-${index}` }))).map((item, index) => <span className={`mobile-avatar${loading ? ' loading' : ''}`} key={item.user_id || item.id} style={{ '--avatar-index': index }}>
          {!loading && (hasCustomAvatar(item.avatar_url) ? <img src={item.avatar_url} alt="" loading="lazy"/> : people ? <DefaultAvatar accent={item.theme_color} /> : null)}
        </span>)}
      </span>
      <span className="search-spotlight-mobile-copy">
        <strong>{title}</strong>
        <small>{people ? (isLoggedIn ? 'Tienen mucho en común contigo' : 'Obras registradas en GeekSphere') : 'Comparte tus aficiones'}</small>
      </span>
      <svg className="search-spotlight-mobile-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg>
    </Link>
    <div className="search-spotlight-heading">
      <h2 id={`search-${kind}-title`}>{title}</h2>
      <Link to={href} className="search-spotlight-view-more">Ver todas <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></Link>
    </div>
    {loading ? <div className="search-spotlight-row is-loading" aria-label={`Cargando ${title}`} aria-busy="true">
      {Array.from({ length: 5 }, (_, index) => <div className={`search-spotlight-skeleton ${people ? 'person' : 'space'}`} key={index} aria-hidden="true">
        {people ? <><span className="skeleton-avatar"/><i className="skeleton-title"/><b className="skeleton-subtitle"/></>
          : <><span className="skeleton-cover"/><i className="skeleton-title"/></>}
      </div>)}
    </div> : orderedItems.length ? <div className="search-spotlight-row">
      {orderedItems.slice(0, 8).map(item => {
        const name = item.display_name || item.name || item.username || 'Usuario'
        const image = hasCustomAvatar(item.avatar_url) ? item.avatar_url : null
        const destination = people ? `/profile/${item.username || item.user_id || item.id}` : `/spaces/${item.id}`
        const subtitle = isLoggedIn ? `${item.commonWorks || 0} en común` : `${item.registeredWorks || 0} obras`
        return <Link className={`search-spotlight-card ${people ? 'person' : 'space'}`} to={destination} key={item.user_id || item.id} title={name}>
          {people ? <span className="search-spotlight-avatar" style={{ '--person-theme': item.theme_color || 'var(--brand-primary)' }}>{image ? <img src={image} alt="" loading="lazy"/> : <DefaultAvatar accent={item.theme_color} />}</span>
            : <span className="search-spotlight-cover">{image ? <img src={image} alt="" loading="lazy"/> : <span>{name.slice(0, 1).toUpperCase()}</span>}</span>}
          <strong>{name}</strong>
          {people && <small>{subtitle}</small>}
        </Link>
      })}
    </div> : <p className="search-spotlight-empty">Todavía no hay {people ? 'personas para mostrar' : 'espacios para mostrar'}.</p>}
  </section>
}


function RecommendationItem({ work }) {
  const isAnime = work.type === 'anime' || work.media_type === 'anime'
  const href = isAnime ? `/anime/${work.id}` : `/game/${work.id}`
  const image = work.image || work.cover_url || work.image_url
  return (
    <Link to={href} className="srec-card" title={work.title} aria-label={work.title}>
      <div className="srec-card-poster">
        {image ? (
          <img src={image} alt={work.title} loading="lazy" />
        ) : (
          <div className="srec-card-fallback">{isAnime ? '▣' : '▤'}</div>
        )}
        <div className="srec-card-overlay">
          <span className="srec-card-title">{work.title}</span>
        </div>
      </div>
    </Link>
  )
}

function FeaturedListCard({ list }) {
  const author = list.author?.username || 'comunidad'
  return <Link className="search-featured-list-card" to={`/lists/${list.id}`} title={list.title || 'Lista sin título'}>
    <span className="search-featured-list-art"><ListPoster list={list}/></span>
    <strong>{list.title || 'Lista sin título'}</strong>
    <small className="search-featured-list-author"><span className="search-featured-list-avatar">{hasCustomAvatar(list.author?.avatar_url) ? <img src={list.author.avatar_url} alt="" loading="lazy"/> : <DefaultAvatar accent={list.author?.theme_color} />}</span><span>@{author}</span></small>
  </Link>
}

function FeaturedLists({ lists, loading }) {
  return <section className="search-featured-lists" aria-labelledby="featured-lists-title">
    <div className="search-explore-heading">
      <div><h2 id="featured-lists-title">LISTAS</h2></div>
      <Link to="/discover/lists" className="search-spotlight-view-more">Ver todas <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></Link>
    </div>
    {loading ? <div className="search-featured-list-row" aria-label="Cargando listas">{Array.from({ length: 4 }, (_, index) => <div className="search-featured-list-skeleton" key={index}><span/><i/><b/></div>)}</div>
      : lists.length ? <div className="search-featured-list-row">{lists.map(list => <FeaturedListCard list={list} key={list.id}/>)}</div>
        : <p className="search-spotlight-empty">Todavía no hay listas públicas para mostrar.</p>}
  </section>
}

function FeaturedListsMobile({ lists, loading }) {
  const images = []
  lists.forEach(list => getListCollageImages(list.content).forEach(image => { if (!images.includes(image) && images.length < 3) images.push(image) }))
  return <Link to="/discover/lists" className="search-spotlight-mobile-link lists">
    <span className="search-spotlight-mobile-avatars" aria-hidden="true">
      {Array.from({ length: 3 }, (_, index) => <span className={`mobile-avatar${loading ? ' loading' : ''}`} key={index} style={{ '--avatar-index': index }}>{!loading && images[index] && <img src={images[index]} alt="" loading="lazy"/>}</span>)}
    </span>
    <span className="search-spotlight-mobile-copy"><strong>Listas</strong><small>Descubre listas de la comunidad</small></span>
    <svg className="search-spotlight-mobile-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg>
  </Link>
}

function RecommendationSidebar({ userId }) {
  const [recs, setRecs] = useState([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    getSearchRecommendations(6, userId).then(items => {
      if (!cancelled) {
        setRecs(items)
        setLoading(false)
      }
    }).catch(() => {
      if (!cancelled) setLoading(false)
    })
    return () => { cancelled = true }
  }, [userId])

  return (
    <aside className="search-sidebar" aria-label="Te puede gustar">
      <div className="search-explore-heading">
        <div><h2>{userId ? 'TE PUEDE GUSTAR' : 'OBRAS POPULARES'}</h2></div>
      </div>
      <div className="srec-grid">
        {loading && Array.from({ length: 6 }).map((_, i) => (
          <div key={i} className="srec-skeleton" aria-hidden="true" />
        ))}
        {!loading && recs.length === 0 && (
          <p className="srec-empty">Sin recomendaciones disponibles</p>
        )}
        {!loading && recs.map(work => (
          <RecommendationItem key={`${work.type}-${work.id}`} work={work} />
        ))}
      </div>
    </aside>
  )
}

export default function Search() {
  const { user } = useAuth()
  const location = useLocation()
  const navigate = useNavigate()
  const [params, setParams] = useSearchParams()
  const [isPwa, setIsPwa] = useState(isStandalonePwa)
  const [isComposing, setIsComposing] = useState(false)
  const normalizedPath = location.pathname.replace(/\/+$/, '')
  const isResults = normalizedPath === '/search/results' || (normalizedPath === '/search' && params.has('filter'))
  const urlQuery = params.get('q') || ''
  const filter = FILTER_IDS.has(params.get('filter')) ? params.get('filter') : 'all'
  const [localQuery, setLocalQuery] = useState(urlQuery)
  const [resultsDraft, setResultsDraft] = useState(urlQuery)
  const query = isResults ? resultsDraft : localQuery
  const searchTerm = isResults ? urlQuery : localQuery
  const [debouncedQuery, setDebouncedQuery] = useState(urlQuery)
  const [debouncedResultsDraft, setDebouncedResultsDraft] = useState(urlQuery)
  const [data, setData] = useState({ works: [], spaces: [], users: [], lists: [], errors: {} })
  const [draftData, setDraftData] = useState({ works: [], spaces: [], users: [], lists: [], errors: {} })
  const [loading, setLoading] = useState(urlQuery.trim().length >= 2)
  const [draftLoading, setDraftLoading] = useState(false)
  const [highlightData, setHighlightData] = useState({})
  const [highlightsLoading, setHighlightsLoading] = useState(true)
  const [featuredLists, setFeaturedLists] = useState([])
  const [featuredListsLoading, setFeaturedListsLoading] = useState(true)
  const [isFocused, setIsFocused] = useState(false)
  const [activeIndex, setActiveIndex] = useState(-1)
  const inputRef = useRef(null)
  const rootRef = useRef(null)
  const listRef = useRef(null)
  const requestRef = useRef(0)
  const previewQuery = isResults ? debouncedResultsDraft : debouncedQuery
  const draftPreviewActive = isResults && previewQuery.trim() !== urlQuery.trim()
  const previewData = draftPreviewActive ? draftData : data
  const previewLoading = draftPreviewActive ? draftLoading : loading
  const previewOpen = !isPwa && isFocused && previewQuery.trim().length >= 2
  const requestQuery = isPwa ? isResults ? urlQuery.trim() : '' : debouncedQuery

  useEffect(() => {
    const media = window.matchMedia('(display-mode: standalone), (display-mode: fullscreen)')
    const update = () => setIsPwa(isStandalonePwa())
    media.addEventListener('change', update)
    return () => media.removeEventListener('change', update)
  }, [])

  useEffect(() => { if (isPwa && !isResults) setLocalQuery(urlQuery) }, [isPwa, isResults, urlQuery])

  useEffect(() => {
    if (!isPwa || isComposing) return undefined
    const term = query.trim()
    if (isResults ? term === urlQuery.trim() : term.length < 2) return undefined
    const timer = window.setTimeout(() => {
      const next = new URLSearchParams(params)
      if (term) next.set('q', term)
      else next.delete('q')
      next.set('filter', filter)
      if (isResults) setParams(next, { replace: true })
      else {
        setResultsDraft(term)
        navigate(`/search/results?${next.toString()}`)
      }
    }, 400)
    return () => window.clearTimeout(timer)
  }, [isPwa, isComposing, query, urlQuery, isResults, params, filter, navigate, setParams])

  useEffect(() => { const timer = window.setTimeout(() => setDebouncedQuery(searchTerm.trim()), 300); return () => window.clearTimeout(timer) }, [searchTerm])
  useEffect(() => { const timer = window.setTimeout(() => setDebouncedResultsDraft(resultsDraft.trim()), 300); return () => window.clearTimeout(timer) }, [resultsDraft])

  useEffect(() => { setResultsDraft(urlQuery) }, [urlQuery])

  useEffect(() => {
    const term = debouncedResultsDraft.trim()
    if (isPwa || !isResults || term.length < 2 || term === urlQuery.trim()) {
      setDraftData({ works: [], spaces: [], users: [], lists: [], errors: {} })
      setDraftLoading(false)
      return undefined
    }
    let cancelled = false
    const controller = new AbortController()
    setDraftLoading(true)
    searchPlatform(term, 8, controller.signal).then(result => {
      if (!cancelled) setDraftData(result)
    }).catch(error => {
      if (!cancelled) setDraftData({ works: [], spaces: [], users: [], lists: [], errors: { all: error } })
    }).finally(() => { if (!cancelled) setDraftLoading(false) })
    return () => { cancelled = true; controller.abort() }
  }, [debouncedResultsDraft, isResults, urlQuery, isPwa])

  useEffect(() => {
    if (requestQuery.trim().length < 2) return undefined
    const requestId = ++requestRef.current
    let cancelled = false
    const controller = new AbortController()
    setLoading(true)
    searchPlatform(requestQuery, isResults ? 20 : 8, controller.signal, isResults ? filter : 'all').then(result => {
      if (!cancelled && requestId === requestRef.current) setData(result)
    }).catch(error => {
      if (!cancelled && requestId === requestRef.current) setData({ works: [], spaces: [], users: [], lists: [], errors: { all: error } })
    }).finally(() => { if (!cancelled && requestId === requestRef.current) setLoading(false) })
    return () => { cancelled = true; controller.abort(); requestRef.current += 1 }
  }, [requestQuery, isResults, filter])

  useEffect(() => {
    let cancelled = false
    setHighlightsLoading(true)
    getSearchHighlights(user?.id).then(samples => { if (!cancelled) setHighlightData(samples) }).catch(() => {}).finally(() => { if (!cancelled) setHighlightsLoading(false) })
    return () => { cancelled = true }
  }, [user?.id])

  useEffect(() => {
    if (isResults) return undefined
    let cancelled = false
    const controller = new AbortController()
    setFeaturedListsLoading(true)
    getDiscoverLists({ page: 1, pageSize: 6, signal: controller.signal })
      .then(result => { if (!cancelled) setFeaturedLists(result.items || []) })
      .catch(() => { if (!cancelled) setFeaturedLists([]) })
      .finally(() => { if (!cancelled) setFeaturedListsLoading(false) })
    return () => { cancelled = true; controller.abort() }
  }, [isResults])

  useEffect(() => {
    const onPointer = event => { if (!rootRef.current?.contains(event.target)) setIsFocused(false) }
    document.addEventListener('pointerdown', onPointer)
    return () => document.removeEventListener('pointerdown', onPointer)
  }, [])

  const flatResults = useMemo(() => [...previewData.works.slice(0, 8), ...previewData.spaces.slice(0, 8), ...previewData.lists.slice(0, MAX_SEARCH_LISTS), ...previewData.users.slice(0, 8)], [previewData])
  const viewAll = useCallback(() => {
    if (isPwa && isResults && query.trim() === urlQuery.trim()) return
    const next = new URLSearchParams({ q: query.trim(), filter: isPwa ? filter : 'all' })
    setIsFocused(false)
    setLoading(true)
    if (isPwa) setResultsDraft(query.trim())
    navigate(`/search/results?${next.toString()}`, isPwa && isResults ? { replace: true } : undefined)
  }, [navigate, query, isPwa, isResults, urlQuery, filter])
  const onInputChange = value => {
    setActiveIndex(-1)
    if (isResults) {
      setResultsDraft(value)
    } else {
      requestRef.current += 1
      if (value.trim().length < 2) setLoading(false)
      else setLoading(true)
      setLocalQuery(value)
    }
  }
  const onInputKeyDown = event => {
    if (isPwa && event.nativeEvent.isComposing) return
    if (event.key === 'Escape') { setIsFocused(false); setActiveIndex(-1); inputRef.current?.blur(); return }
    if (!previewOpen) { if (event.key === 'Enter' && query.trim()) viewAll(); return }
    if (event.key === 'ArrowDown') { event.preventDefault(); setActiveIndex(index => Math.min(index + 1, flatResults.length)) }
    if (event.key === 'ArrowUp') { event.preventDefault(); setActiveIndex(index => Math.max(index - 1, 0)) }
    if (event.key === 'Enter') {
      event.preventDefault()
      if (activeIndex >= 0 && activeIndex < flatResults.length) navigate(resultHref(flatResults[activeIndex]))
      else viewAll()
    }
  }
  useEffect(() => {
    if (activeIndex < 0) return
    const option = document.getElementById(activeIndex === flatResults.length ? 'search-view-all' : `search-option-${activeIndex}`)
    option?.scrollIntoView({ block: 'nearest' })
  }, [activeIndex, flatResults.length])

  const selectedItems = filter === 'game' ? data.works.filter(item => item.type === 'game')
    : filter === 'anime' ? data.works.filter(item => item.type === 'anime')
      : filter === 'spaces' ? data.spaces : filter === 'users' ? data.users : filter === 'lists' ? data.lists : null
  const sections = filter === 'all'
    ? [['works', data.works], ['spaces', data.spaces], ['lists', data.lists], ['users', data.users]]
    : filter === 'game' || filter === 'anime' ? [['works', selectedItems]]
      : [[filter, selectedItems]]
  const hasVisibleResults = sections.some(([, items]) => items?.length > 0)
  const activeDescendant = previewOpen && activeIndex >= 0
    ? activeIndex === flatResults.length ? 'search-view-all' : `search-option-${activeIndex}`
    : undefined

  return <div className={`search-page${isResults ? ' results-page' : ''}`} ref={rootRef}>
    <SEO title="Busca tus aficiones" description="Encuentra obras, espacios, personas y listas en GeekSphere." />
    {isResults ? <div className="search-results-layout">
      <div className="search-results-main">
      <section className={`search-universal${previewOpen ? ' has-preview' : ''}`} aria-label="Búsqueda global">
        <SearchInput value={query} onChange={onInputChange} onFocus={() => setIsFocused(true)} onKeyDown={onInputKeyDown} inputRef={inputRef} resultsId="search-preview" isOpen={previewOpen} activeDescendant={activeDescendant} previewEnabled={!isPwa} onCompositionChange={setIsComposing} />
        {previewOpen && <Preview query={previewQuery} data={previewData} loading={previewLoading} error={Object.keys(previewData.errors || {}).length > 0} activeIndex={activeIndex} onSelect={() => setIsFocused(false)} onViewAll={viewAll} listRef={listRef} />}
      </section>
      <section className="search-results-content" aria-live="polite">
        <nav className="search-filters" aria-label="Filtrar resultados" style={{ '--filter-index': FILTERS.findIndex(item => item.id === filter), '--filter-count': FILTERS.length }}>
          {FILTERS.map(item => <button type="button" key={item.id} className={filter === item.id ? 'active' : ''} aria-pressed={filter === item.id} onClick={() => { const term = isPwa ? query.trim() : urlQuery.trim(); setResultsDraft(term); const next = new URLSearchParams(params); next.set('filter', item.id); if (term) next.set('q', term); else next.delete('q'); setParams(next, isPwa ? { replace: true } : undefined) }}>{item.label}</button>)}
        </nav>
        {urlQuery.trim().length < 2 ? <div className="search-full-empty"><span>⌕</span><h2>Empieza con dos letras o más</h2><p>Busca títulos, espacios y usuarios.</p></div>
          : loading && !data.works.length && !data.spaces.length && !data.users.length && !data.lists.length ? <SearchSkeleton />
            : Object.keys(data.errors || {}).length === 4 && !data.works.length && !data.spaces.length && !data.users.length && !data.lists.length ? <div className="search-full-empty"><span>!</span><h2>No se pudo completar la búsqueda</h2><p>Comprueba tu conexión e inténtalo de nuevo.</p></div>
              : <>
                {sections.map(([key, items]) => items?.length > 0 && <section className={`search-result-section ${key}`} data-result-category={key} key={key}>
                  <div className="search-section-heading"><div className="search-section-title"><h2>{CATEGORY_LABELS[key]}</h2><span className="search-section-count">{items.length}</span></div></div>
                  <div className="search-result-grid">{items.map(item => <ResultLink key={`${item.type || key}-${item.id}`} item={item} display={key === 'users' ? 'row' : 'card'} />)}</div>
                </section>)}
                {!loading && Object.keys(data.errors || {}).length > 0 && <p className="search-full-error">Algunos catálogos no respondieron. Los resultados disponibles siguen visibles.</p>}
                {!loading && !hasVisibleResults && <p className="search-no-results">Sin resultados para «{urlQuery}»</p>}
                {loading && <SearchSkeleton />}
              </>}
      </section>
      </div>
      <div className="search-landing-divider" aria-hidden="true" />
      <RecommendationSidebar userId={user?.id} />
    </div> : <div className="search-landing-layout">
      <div className="search-landing-main">
        <section className={`search-universal${previewOpen ? ' has-preview' : ''}`} aria-label="Búsqueda global">
          <SearchInput value={query} onChange={onInputChange} onFocus={() => setIsFocused(true)} onKeyDown={onInputKeyDown} inputRef={inputRef} resultsId="search-preview" isOpen={previewOpen} activeDescendant={activeDescendant} previewEnabled={!isPwa} onCompositionChange={setIsComposing} />
          {previewOpen && <Preview query={previewQuery} data={previewData} loading={previewLoading} error={Object.keys(previewData.errors || {}).length > 0} activeIndex={activeIndex} onSelect={() => setIsFocused(false)} onViewAll={viewAll} listRef={listRef} />}
        </section>
        <section className="search-explore" aria-labelledby="explore-title">
          <div className="search-explore-heading"><div><h2 id="explore-title">EXPLORAR</h2></div></div>
          <div className="search-category-grid">
            <CategoryCard kind="anime" title="Animes" items={highlightData.anime} to="/discover/anime" />
            <CategoryCard kind="games" title="Juegos" items={highlightData.games} to="/discover/games" />
          </div>
        </section>
        <div className="search-spotlight-mobile-panel">
          <SpotlightRow kind="people" items={highlightData.users} loading={highlightsLoading} isLoggedIn={Boolean(user)}/>
          <SpotlightRow kind="spaces" items={highlightData.spaces} loading={highlightsLoading}/>
          <FeaturedListsMobile lists={featuredLists} loading={featuredListsLoading}/>
        </div>
        <FeaturedLists lists={featuredLists} loading={featuredListsLoading}/>
      </div>
      <div className="search-landing-divider" aria-hidden="true" />
      <RecommendationSidebar userId={user?.id} />
    </div>}
  </div>
}

