// ─── Avatar ──────────────────────────────────────────────────────────────────
function ProfileAvatar({ profile, size = 'normal' }) {
    const name = profile?.display_name || profile?.username || 'U';
    return (
        <span
            className={`review-detail-avatar ${size}`}
            style={{ '--review-author-theme': profile?.theme_color || 'var(--brand-primary)' }}
